(336795,37422,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El chico ... tiene un ramo de flores detrás de la espalda le sonríe.'::text,'que'::text,'que'::text,'cuyo'::text,'El chico que tiene un ramo de flores detrás de la espalda le sonríe.'::text),
(336794,37422,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le jeune homme ... tient un bouquet de fleurs derrière son dos lui sourit.'::text,'qui'::text,'qui'::text,'dont'::text,'Le jeune homme qui tient un bouquet de fleurs derrière son dos lui sourit.'::text),
(336797,37422,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkasında bir buket çiçek ... genç adam ona gülümsüyor.'::text,'tutan'::text,'tutan'::text,'tuttuğu'::text,'Arkasında bir buket çiçek tutan genç adam ona gülümsüyor.'::text),
(336798,37422,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiatalember, ... egy csokor virágot tart a háta mögött, rámosolyog.'::text,'aki'::text,'ami'::text,'akinek'::text,'A fiatalember, aki egy csokor virágot tart a háta mögött, rámosolyog.'::text),
(351885,39099,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... gerade auf der Kirmes Eis, als sich das Riesenrad in Bewegung setzte.'::text,'aßen'::text,'aßen'::text,'haben gegessen'::text,'Sie aßen gerade auf der Kirmes Eis, als sich das Riesenrad in Bewegung setzte.'::text),
(351889,39099,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... морозиво на ярмарку, коли оглядове колесо почало рухатися.'::text,'їли'::text,'з''їли'::text,'з''їли'::text,'Вони їли морозиво на ярмарку, коли оглядове колесо почало рухатися.'::text),
(351888,39099,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellos ... helado en la feria cuando la noria empezó a moverse.'::text,'estaban comiendo'::text,'comieron'::text,'han comido'::text,'Ellos estaban comiendo helado en la feria cuando la noria empezó a moverse.'::text),
(351887,39099,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... des glaces à la fête foraine quand la grande roue a commencé à tourner.'::text,'mangeaient'::text,'ont mangé'::text,'ont mangé'::text,'Ils mangeaient des glaces à la fête foraine quand la grande roue a commencé à tourner.'::text),
(351890,39099,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dönme dolap hareket etmeye başladığında lunaparkta dondurma ...'::text,'yiyorlardı'::text,'yediler'::text,'yediler'::text,'Dönme dolap hareket etmeye başladığında lunaparkta dondurma yiyorlardı.'::text),
(351891,39099,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vidámparkban éppen fagyit ..., amikor az óriáskerék megindult.'::text,'ettek'::text,'megettek'::text,'ettek'::text,'A vidámparkban éppen fagyit ettek, amikor az óriáskerék megindult.'::text),
(351894,39100,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Paar ... schon seit drei Stunden über die Kirmes.'::text,'schlendert'::text,'schlendert'::text,'schlendert'::text,'Das Paar schlendert schon seit drei Stunden über die Kirmes.'::text),
(351898,39100,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пара ... ярмарком уже три години.'::text,'гуляє'::text,'гуляє'::text,'гуляє'::text,'Пара гуляє ярмарком уже три години.'::text),
(351897,39100,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pareja ... por la feria desde hace tres horas.'::text,'lleva paseando'::text,'está paseando'::text,'pasea'::text,'La pareja lleva paseando por la feria desde hace tres horas.'::text),
(351896,39100,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le couple ... dans la fête foraine depuis trois heures.'::text,'se promène'::text,'se promène'::text,'se promène'::text,'Le couple se promène dans la fête foraine depuis trois heures.'::text),
(351899,39100,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çift üç saattir lunaparkta ...'::text,'dolaşıyor'::text,'dolaşıyor'::text,'dolaşır'::text,'Çift üç saattir lunaparkta dolaşıyor.'::text),
(351900,39100,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pár már három órája ... a vidámparkban.'::text,'sétál'::text,'sétál'::text,'sétál'::text,'A pár már három órája sétál a vidámparkban.'::text),
(351903,39101,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während sie oben im Riesenrad ..., sah die ganze Kirmes winzig aus. Mäßig aufregend.'::text,'fuhren'::text,'fuhren'::text,'gefahren sind'::text,'Während sie oben im Riesenrad fuhren, sah die ganze Kirmes winzig aus. Mäßig aufregend.'::text),
(351907,39101,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вони ... нагорі на колесі, весь ярмарок здавався крихітним. Трохи захопливо.'::text,'каталися'::text,'покаталися'::text,'покаталися'::text,'Поки вони каталися нагорі на колесі, весь ярмарок здавався крихітним. Трохи захопливо.'::text),
(351906,39101,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ... en lo alto de la noria, toda la feria parecía diminuta. Levemente emocionante.'::text,'montaban'::text,'montaron'::text,'han montado'::text,'Mientras montaban en lo alto de la noria, toda la feria parecía diminuta. Levemente emocionante.'::text),
(351905,39101,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''ils ... tout en haut de la grande roue, toute la fête foraine avait l''air minuscule. Moyennement palpitant.'::text,'tournaient'::text,'ont tourné'::text,'ont tourné'::text,'Pendant qu''ils tournaient tout en haut de la grande roue, toute la fête foraine avait l''air minuscule. Moyennement palpitant.'::text),
(351908,39101,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar dönme dolapta yukarıda ..., bütün lunapark minicik görünüyordu. Hafif heyecanlı.'::text,'giderken'::text,'gittiler'::text,'gittiler'::text,'Onlar dönme dolapta yukarıda giderken, bütün lunapark minicik görünüyordu. Hafif heyecanlı.'::text),
(351909,39101,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben fent ... az óriáskeréken, az egész vidámpark aprónak tűnt. Enyhén izgalmas.'::text,'ültek'::text,'ültek'::text,'ültek'::text,'Miközben fent ültek az óriáskeréken, az egész vidámpark aprónak tűnt. Enyhén izgalmas.'::text),
(351912,39102,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, heute auf dieser Kirmes hat er drei Riesenteddys ..., ohne Witz.'::text,'gewonnen'::text,'gewonnen'::text,'gewinnt'::text,'Yo, heute auf dieser Kirmes hat er drei Riesenteddys gewonnen, ohne Witz.'::text),
(351916,39102,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, він сьогодні ... на цьому ярмарку три гігантські ведмедики, без жартів.'::text,'виграв'::text,'вигравав'::text,'виграє'::text,'Йо, він сьогодні виграв на цьому ярмарку три гігантські ведмедики, без жартів.'::text),
(351915,39102,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, hoy él ... tres peluches gigantes en esta feria, sin mentir.'::text,'ha ganado'::text,'ha estado ganando'::text,'está ganando'::text,'Oye, hoy él ha ganado tres peluches gigantes en esta feria, sin mentir.'::text),
(351914,39102,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, il ... trois nounours géants à cette fête foraine aujourd''hui, sans mentir.'::text,'a gagné'::text,'a gagné'::text,'gagne'::text,'Wesh, il a gagné trois nounours géants à cette fête foraine aujourd''hui, sans mentir.'::text),
(351917,39102,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bugün bu lunaparkta üç dev ayıcık ..., yemin ederim.'::text,'kazandı'::text,'kazanıyordu'::text,'kazanıyor'::text,'Kanka, bugün bu lunaparkta üç dev ayıcık kazandı, yemin ederim.'::text),
(351918,39102,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, ma ezen a vidámparkon ... három óriás macit, komolyan.'::text,'nyert'::text,'nyert'::text,'nyer'::text,'Figyu, ma ezen a vidámparkon nyert három óriás macit, komolyan.'::text),
(351921,39103,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, als sie ins Riesenrad stiegen, ... er schon den größten Teddy der Kirmes gewonnen, echt.'::text,'hatte'::text,'hat'::text,'gewann'::text,'Alter, als sie ins Riesenrad stiegen, hatte er schon den größten Teddy der Kirmes gewonnen, echt.'::text),
(351925,39103,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, поки вони сіли на колесо, він уже ... найбільшого ведмедика ярмарку, реально.'::text,'виграв'::text,'виграв'::text,'виграв'::text,'Чувак, поки вони сіли на колесо, він уже виграв найбільшого ведмедика ярмарку, реально.'::text),
(351924,39103,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, para cuando subieron a la noria, él ya ... el peluche más grande de la feria, en serio.'::text,'había ganado'::text,'ha ganado'::text,'ganó'::text,'Tío, para cuando subieron a la noria, él ya había ganado el peluche más grande de la feria, en serio.'::text),
(351923,39103,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, quand ils sont montés dans la grande roue, il ... le plus gros nounours de la fête, pour de vrai.'::text,'avait gagné'::text,'a gagné'::text,'a gagné'::text,'Mec, quand ils sont montés dans la grande roue, il avait gagné le plus gros nounours de la fête, pour de vrai.'::text),
(351926,39103,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, dönme dolaba bindiklerinde o, lunaparkın en büyük ayıcığını çoktan ..., cidden.'::text,'kazanmıştı'::text,'kazandı'::text,'kazandı'::text,'Kanka, dönme dolaba bindiklerinde o, lunaparkın en büyük ayıcığını çoktan kazanmıştı, cidden.'::text),
(351927,39103,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, mire felszálltak az óriáskerékre, ő már ... a vidámpark legnagyobb maciját, komolyan.'::text,'megnyerte'::text,'megnyerte'::text,'megnyerte'::text,'Haver, mire felszálltak az óriáskerékre, ő már megnyerte a vidámpark legnagyobb maciját, komolyan.'::text),
(351939,39105,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wünscht sich, dass die Fahrt im Riesenrad über der Kirmes länger ...'::text,'dauern würde'::text,'dauern wird'::text,'dauert'::text,'Sie wünscht sich, dass die Fahrt im Riesenrad über der Kirmes länger dauern würde.'::text),
(351943,39105,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона хоче, щоб поїздка на колесі над ярмарком ... довше.'::text,'тривала'::text,'триватиме'::text,'триває'::text,'Вона хоче, щоб поїздка на колесі над ярмарком тривала довше.'::text),
(351942,39105,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella desearía que el paseo en la noria sobre la feria ... más.'::text,'durara'::text,'durará'::text,'dura'::text,'Ella desearía que el paseo en la noria sobre la feria durara más.'::text),
(351941,39105,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle aimerait que le tour de grande roue au-dessus de la fête ... plus longtemps.'::text,'dure'::text,'durera'::text,'dure'::text,'Elle aimerait que le tour de grande roue au-dessus de la fête dure plus longtemps.'::text),
(351944,39105,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke lunaparkın üstündeki dönme dolap turu daha uzun ... diye düşünüyor.'::text,'sürse'::text,'sürecek'::text,'sürüyor'::text,'Keşke lunaparkın üstündeki dönme dolap turu daha uzun sürse diye düşünüyor.'::text),
(351945,39105,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt szeretné, ha a vidámpark feletti óriáskerekezés tovább ...'::text,'tartana'::text,'tart majd'::text,'tart'::text,'Azt szeretné, ha a vidámpark feletti óriáskerekezés tovább tartana.'::text),
(351948,39106,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kirmes, ... Fahrgeschäfte ein großes Riesenrad umfassen, zieht typischerweise junge Paare an.'::text,'deren'::text,'die'::text,'die'::text,'Die Kirmes, deren Fahrgeschäfte ein großes Riesenrad umfassen, zieht typischerweise junge Paare an.'::text),
(351952,39106,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ярмарок, ... атракціони включають велике оглядове колесо, зазвичай приваблює молоді пари.'::text,'чиї'::text,'який'::text,'що'::text,'Ярмарок, чиї атракціони включають велике оглядове колесо, зазвичай приваблює молоді пари.'::text),
(351951,39106,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La feria, ... atracciones incluyen una gran noria, suele atraer a parejas jóvenes.'::text,'cuyas'::text,'que'::text,'que'::text,'La feria, cuyas atracciones incluyen una gran noria, suele atraer a parejas jóvenes.'::text),
(351950,39106,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La fête foraine, ... les attractions comprennent une grande roue, attire généralement de jeunes couples.'::text,'dont'::text,'qui'::text,'que'::text,'La fête foraine, dont les attractions comprennent une grande roue, attire généralement de jeunes couples.'::text),
(351953,39106,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Atraksiyonları arasında büyük bir dönme dolap ... lunapark, genellikle genç çiftleri çeker.'::text,'bulunan'::text,'bulunan'::text,'bulunan'::text,'Atraksiyonları arasında büyük bir dönme dolap bulunan lunapark, genellikle genç çiftleri çeker.'::text),
(351954,39106,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vidámpark, ... attrakciói között egy nagy óriáskerék is van, jellemzően fiatal párokat vonz.'::text,'amelynek'::text,'amely'::text,'ami'::text,'A vidámpark, amelynek attrakciói között egy nagy óriáskerék is van, jellemzően fiatal párokat vonz.'::text),
(351957,39107,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das ist ... Kirmes ihres Lebens, und sie wird sich für immer daran erinnern!'::text,'die beste'::text,'eine beste'::text,'beste'::text,'Das ist die beste Kirmes ihres Lebens, und sie wird sich für immer daran erinnern!'::text),
(351961,39107,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це ... ярмарок у її житті, і вона запам''ятає його назавжди!'::text,'найкращий'::text,'найкращий'::text,'найкращий'::text,'Це найкращий ярмарок у її житті, і вона запам''ятає його назавжди!'::text),
(351960,39107,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Esta es ... feria de su vida, y la recordará para siempre!'::text,'la mejor'::text,'una mejor'::text,'mejor'::text,'¡Esta es la mejor feria de su vida, y la recordará para siempre!'::text),
(351959,39107,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est ... fête foraine de sa vie, et elle s''en souviendra pour toujours !'::text,'la meilleure'::text,'une meilleure'::text,'meilleure'::text,'C''est la meilleure fête foraine de sa vie, et elle s''en souviendra pour toujours !'::text),
(351962,39107,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu, hayatının ... lunaparkı ve onu sonsuza dek hatırlayacak!'::text,'en iyi'::text,'en iyi'::text,'en iyi'::text,'Bu, hayatının en iyi lunaparkı ve onu sonsuza dek hatırlayacak!'::text),
(351963,39107,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez ... vidámpark az életében, és örökké emlékezni fog rá!'::text,'a legjobb'::text,'egy legjobb'::text,'legjobb'::text,'Ez a legjobb vidámpark az életében, és örökké emlékezni fog rá!'::text),
(351975,39109,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende der Nacht werden sie jede Attraktion der Kirmes ...'::text,'ausprobiert haben'::text,'ausprobieren'::text,'gerade ausprobieren'::text,'Bis zum Ende der Nacht werden sie jede Attraktion der Kirmes ausprobiert haben.'::text),
(351979,39109,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця ночі вони ... кожен атракціон на ярмарку.'::text,'спробують'::text,'спробують'::text,'пробують'::text,'До кінця ночі вони спробують кожен атракціон на ярмарку.'::text),
(351978,39109,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final de la noche, ellos ... todas las atracciones de la feria.'::text,'habrán probado'::text,'probarán'::text,'están probando'::text,'Para el final de la noche, ellos habrán probado todas las atracciones de la feria.'::text),
(351977,39109,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin de la soirée, ils ... toutes les attractions de la fête foraine.'::text,'auront essayé'::text,'essaieront'::text,'essaient'::text,'D''ici la fin de la soirée, ils auront essayé toutes les attractions de la fête foraine.'::text),
(351980,39109,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gecenin sonunda lunaparktaki her oyuncağı ...'::text,'denemiş olacaklar'::text,'deneyecekler'::text,'deniyorlar'::text,'Gecenin sonunda lunaparktaki her oyuncağı denemiş olacaklar.'::text),
(351981,39109,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az éjszaka végére ... a vidámpark összes játékát.'::text,'kipróbálják'::text,'ki fogják próbálni'::text,'próbálgatják'::text,'Az éjszaka végére kipróbálják a vidámpark összes játékát.'::text),
(351273,39031,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... auf der Ausstellung gerade ein kleines Gehirnmodell, als sie das riesige entdeckte.'::text,'untersuchte'::text,'untersuchte'::text,'hat untersucht'::text,'Sie untersuchte auf der Ausstellung gerade ein kleines Gehirnmodell, als sie das riesige entdeckte.'::text),
(351277,39031,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... маленьку модель мозку на виставці, коли помітила величезну.'::text,'розглядала'::text,'розглянула'::text,'розглянула'::text,'Вона розглядала маленьку модель мозку на виставці, коли помітила величезну.'::text),
(351276,39031,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... un pequeño modelo de cerebro en la exposición cuando vio el gigante.'::text,'estaba examinando'::text,'examinó'::text,'ha examinado'::text,'Ella estaba examinando un pequeño modelo de cerebro en la exposición cuando vio el gigante.'::text),
(351275,39031,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... une petite maquette de cerveau à l''exposition quand elle a repéré la géante.'::text,'examinait'::text,'a examiné'::text,'a examiné'::text,'Elle examinait une petite maquette de cerveau à l''exposition quand elle a repéré la géante.'::text),
(351278,39031,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dev olanı fark ettiğinde sergide küçük bir beyin modelini ...'::text,'inceliyordu'::text,'inceledi'::text,'inceledi'::text,'Dev olanı fark ettiğinde sergide küçük bir beyin modelini inceliyordu.'::text),
(351279,39031,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éppen egy kis agymodellt ... a kiállításon, amikor észrevette az óriásit.'::text,'vizsgált'::text,'megvizsgált'::text,'megvizsgált'::text,'Éppen egy kis agymodellt vizsgált a kiállításon, amikor észrevette az óriásit.'::text),
(351291,39033,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn diese Ausstellung einen Souvenirshop ..., würde ich mir das pinke Gehirn glatt kaufen.'::text,'hätte'::text,'hat'::text,'haben würde'::text,'Ehrlich, wenn diese Ausstellung einen Souvenirshop hätte, würde ich mir das pinke Gehirn glatt kaufen.'::text),
(351295,39033,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби на цій виставці ... сувенірна крамниця, я б по-тихому купив той рожевий мозок.'::text,'була'::text,'є'::text,'була б'::text,'Чесно, якби на цій виставці була сувенірна крамниця, я б по-тихому купив той рожевий мозок.'::text),
(351294,39033,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, si esta exposición ... tienda de regalos, en plan me compraría ese cerebro rosa.'::text,'tuviera'::text,'tiene'::text,'tendría'::text,'No voy a mentir, si esta exposición tuviera tienda de regalos, en plan me compraría ese cerebro rosa.'::text),
(351293,39033,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si cette expo ... une boutique de souvenirs, j''achèterais carrément ce cerveau rose.'::text,'avait'::text,'a'::text,'aurait'::text,'Franchement, si cette expo avait une boutique de souvenirs, j''achèterais carrément ce cerveau rose.'::text),
(351296,39033,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, bu serginin bir hediyelik eşya dükkânı ..., o pembe beyni resmen alırdım.'::text,'olsaydı'::text,'var'::text,'olurdu'::text,'Açıkçası, bu serginin bir hediyelik eşya dükkânı olsaydı, o pembe beyni resmen alırdım.'::text),
(351297,39033,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha ennek a kiállításnak ... ajándékboltja, simán megvenném azt a rózsaszín agyat.'::text,'lenne'::text,'van'::text,'lenne'::text,'Őszintén, ha ennek a kiállításnak lenne ajándékboltja, simán megvenném azt a rózsaszín agyat.'::text),
(351300,39034,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gehirnausstellung ... von 3.000 Besuchern besucht, deutlich über dem Zielwert.'::text,'wurde'::text,'besuchte'::text,'wird'::text,'Die Gehirnausstellung wurde von 3.000 Besuchern besucht, deutlich über dem Zielwert.'::text),
(351304,39034,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Виставку про мозок ... 3 000 відвідувачів, значно понад план.'::text,'відвідали'::text,'відвідала'::text,'відвідують'::text,'Виставку про мозок відвідали 3 000 відвідувачів, значно понад план.'::text),
(351303,39034,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La exposición del cerebro ... por 3.000 visitantes, muy por encima del objetivo.'::text,'fue visitada'::text,'visitó'::text,'es visitada'::text,'La exposición del cerebro fue visitada por 3.000 visitantes, muy por encima del objetivo.'::text),
(351302,39034,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''exposition sur le cerveau ... par 3 000 visiteurs, bien au-dessus de l''objectif.'::text,'a été visitée'::text,'a visité'::text,'est visitée'::text,'L''exposition sur le cerveau a été visitée par 3 000 visiteurs, bien au-dessus de l''objectif.'::text),
(351305,39034,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beyin sergisi 3.000 ziyaretçi tarafından ..., hedefin çok üzerinde.'::text,'ziyaret edildi'::text,'ziyaret etti'::text,'ziyaret ediliyor'::text,'Beyin sergisi 3.000 ziyaretçi tarafından ziyaret edildi, hedefin çok üzerinde.'::text),
(351306,39034,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az agykiállítást 3000 látogató ..., jóval a cél felett.'::text,'kereste fel'::text,'felkereste'::text,'keresi fel'::text,'Az agykiállítást 3000 látogató kereste fel, jóval a cél felett.'::text),
(351309,39035,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Ausstellung ... Gehirnmodelle, also geht es um Gehirne.'::text,'zeigt'::text,'wird gezeigt'::text,'zeigend'::text,'Die Ausstellung zeigt Gehirnmodelle, also geht es um Gehirne.'::text),
(351313,39035,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Виставка ... моделі мозку, отже, вона про мозок.'::text,'показує'::text,'показана'::text,'показуючи'::text,'Виставка показує моделі мозку, отже, вона про мозок.'::text),
(351312,39035,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La exposición ... modelos de cerebros, así que va de cerebros.'::text,'muestra'::text,'es mostrada'::text,'mostrando'::text,'La exposición muestra modelos de cerebros, así que va de cerebros.'::text),
(351311,39035,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''exposition ... des maquettes de cerveaux, donc elle parle de cerveaux.'::text,'montre'::text,'est montrée'::text,'montrant'::text,'L''exposition montre des maquettes de cerveaux, donc elle parle de cerveaux.'::text),
(351314,39035,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sergi beyin modellerini ..., yani beyinlerle ilgili.'::text,'gösteriyor'::text,'gösteriliyor'::text,'gösteren'::text,'Sergi beyin modellerini gösteriyor, yani beyinlerle ilgili.'::text),
(351315,39035,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kiállítás agymodelleket ..., szóval agyakról szól.'::text,'mutat be'::text,'be van mutatva'::text,'bemutatva'::text,'A kiállítás agymodelleket mutat be, szóval agyakról szól.'::text),
(351318,39036,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Angesichts seiner Windungen ... das Exponat auf der Ausstellung ein Modell eines menschlichen Gehirns sein.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Angesichts seiner Windungen muss das Exponat auf der Ausstellung ein Modell eines menschlichen Gehirns sein.'::text),
(351322,39036,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зважаючи на його звивини, експонат на виставці ... бути моделлю людського мозку.'::text,'має'::text,'не може'::text,'повинен'::text,'Зважаючи на його звивини, експонат на виставці має бути моделлю людського мозку.'::text),
(351321,39036,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dados sus pliegues, el ejemplar de la exposición ... ser un modelo de cerebro humano.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Dados sus pliegues, el ejemplar de la exposición debe de ser un modelo de cerebro humano.'::text),
(351320,39036,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vu ses plis, le spécimen de l''exposition ... être une maquette de cerveau humain.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Vu ses plis, le spécimen de l''exposition doit être une maquette de cerveau humain.'::text),
(351323,39036,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kıvrımlarına bakılırsa sergideki örnek bir insan beyni modeli ...'::text,'olmalı'::text,'olamaz'::text,'olması gerekir'::text,'Kıvrımlarına bakılırsa sergideki örnek bir insan beyni modeli olmalı.'::text),
(351324,39036,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tekervényei alapján a kiállítási példány ... egy emberi agy modellje.'::text,'biztosan'::text,'nem lehet'::text,'elvileg'::text,'A tekervényei alapján a kiállítási példány biztosan egy emberi agy modellje.'::text),
(351327,39037,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast deiner Freundin gesagt, dass die Ausstellung fantastisch ..., und ehrlich, deine Reaktion beweist es.'::text,'war'::text,'ist'::text,'sein wird'::text,'Du hast deiner Freundin gesagt, dass die Ausstellung fantastisch war, und ehrlich, deine Reaktion beweist es.'::text),
(351331,39037,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти сказала подрузі, що виставка ... неймовірна, і чесно, твоя реакція це доводить.'::text,'була'::text,'є'::text,'буде'::text,'Ти сказала подрузі, що виставка була неймовірна, і чесно, твоя реакція це доводить.'::text),
(351330,39037,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le dijiste a tu amiga que la exposición ... increíble, y la verdad, tu reacción lo demuestra.'::text,'era'::text,'es'::text,'será'::text,'Le dijiste a tu amiga que la exposición era increíble, y la verdad, tu reacción lo demuestra.'::text),
(351329,39037,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as dit à ton amie que l''expo ... incroyable, et franchement, ta réaction le prouve.'::text,'était'::text,'est'::text,'sera'::text,'Tu as dit à ton amie que l''expo était incroyable, et franchement, ta réaction le prouve.'::text),
(351332,39037,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşına serginin harika ... söyledin ve açıkçası tepkin bunu kanıtlıyor.'::text,'olduğunu'::text,'olduğunu'::text,'olacağını'::text,'Arkadaşına serginin harika olduğunu söyledin ve açıkçası tepkin bunu kanıtlıyor.'::text),
(351333,39037,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondtad a barátnődnek, hogy a kiállítás csodás ..., és őszintén, a reakciód ezt bizonyítja.'::text,'volt'::text,NULL::text,'lesz'::text,'Azt mondtad a barátnődnek, hogy a kiállítás csodás volt, és őszintén, a reakciód ezt bizonyítja.'::text),
(351336,39038,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... Wissenschaft, aber diese Ausstellung hat dich voll gepackt. Respekt.'::text,'hasstest früher'::text,'hasstest früher'::text,'warst es gewohnt zu hassen'::text,'Ehrlich, du hasstest früher Wissenschaft, aber diese Ausstellung hat dich voll gepackt. Respekt.'::text),
(351340,39038,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... науку, але ця виставка тебе затягнула. Респект.'::text,'раніше ненавиділа'::text,'раніше ненавиділа'::text,'звикла ненавидіти'::text,'Чесно, ти раніше ненавиділа науку, але ця виставка тебе затягнула. Респект.'::text),
(351339,39038,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, tú ... odiar la ciencia, pero esta exposición te tiene enganchada. Respeto.'::text,'solías'::text,'solías'::text,'estabas acostumbrada a'::text,'La verdad, tú solías odiar la ciencia, pero esta exposición te tiene enganchada. Respeto.'::text),
(351338,39038,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, avant tu ... la science, mais cette expo t''a complètement accrochée. Respect.'::text,'détestais'::text,'détestais'::text,'étais habituée à détester'::text,'Franchement, avant tu détestais la science, mais cette expo t''a complètement accrochée. Respect.'::text),
(351341,39038,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, eskiden bilimden ..., ama bu sergi seni resmen yakaladı. Saygılar.'::text,'nefret ederdin'::text,'nefret ederdin'::text,'nefret etmeye alışkındın'::text,'Açıkçası, eskiden bilimden nefret ederdin, ama bu sergi seni resmen yakaladı. Saygılar.'::text),
(351342,39038,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, régen ... a tudományt, de ez a kiállítás teljesen beszippantott. Respekt.'::text,'utáltad'::text,'utáltad'::text,'hozzá voltál szokva utálni'::text,'Őszintén, régen utáltad a tudományt, de ez a kiállítás teljesen beszippantott. Respekt.'::text),
(351345,39039,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt scheinst du es zu genießen, jedes Gehirnmodell auf dieser Ausstellung ...'::text,'zu studieren'::text,'zu studieren'::text,'studieren'::text,'Ehrlich gesagt scheinst du es zu genießen, jedes Gehirnmodell auf dieser Ausstellung zu studieren.'::text),
(351349,39039,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брехатиму, тобі, здається, подобається ... кожну модель мозку на цій виставці.'::text,'вивчати'::text,'вивчати'::text,'вивчати'::text,'Не брехатиму, тобі, здається, подобається вивчати кожну модель мозку на цій виставці.'::text),
(351348,39039,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, parece que disfrutas ... cada modelo de cerebro de esta exposición.'::text,'estudiando'::text,'estudiar'::text,'estudias'::text,'No voy a mentir, parece que disfrutas estudiando cada modelo de cerebro de esta exposición.'::text),
(351347,39039,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, t''as l''air d''adorer ... chaque maquette de cerveau de cette expo.'::text,'étudier'::text,'étudier'::text,'étudier'::text,'Je vais pas mentir, t''as l''air d''adorer étudier chaque maquette de cerveau de cette expo.'::text),
(351350,39039,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, bu sergideki her beyin modelini ... seviyor gibisin.'::text,'incelemeyi'::text,'incelemeyi'::text,'incele'::text,'Yalan yok, bu sergideki her beyin modelini incelemeyi seviyor gibisin.'::text),
(351351,39039,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, úgy tűnik, élvezed ... a kiállítás minden agymodelljét.'::text,'tanulmányozni'::text,'tanulmányozni'::text,'tanulmányozod'::text,'Nem hazudok, úgy tűnik, élvezed tanulmányozni a kiállítás minden agymodelljét.'::text),
(351363,39041,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor sie das riesige Gehirn erreichte, ... sie jedes Modell der Ausstellung studiert.'::text,'hatte'::text,'hat'::text,'studierte'::text,'Bevor sie das riesige Gehirn erreichte, hatte sie jedes Modell der Ausstellung studiert.'::text),
(351367,39041,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж дійти до гігантського мозку, вона ... кожну модель на виставці.'::text,'вивчила'::text,'вивчила'::text,'вивчала'::text,'Перш ніж дійти до гігантського мозку, вона вивчила кожну модель на виставці.'::text),
(351366,39041,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de llegar al cerebro gigante, ella ya ... cada modelo de la exposición.'::text,'había estudiado'::text,'ha estudiado'::text,'estaba estudiando'::text,'Antes de llegar al cerebro gigante, ella ya había estudiado cada modelo de la exposición.'::text),
(351365,39041,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant d''atteindre le cerveau géant, elle ... chaque maquette de l''exposition.'::text,'avait étudié'::text,'a étudié'::text,'étudiait'::text,'Avant d''atteindre le cerveau géant, elle avait étudié chaque maquette de l''exposition.'::text),
(351368,39041,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dev beyne ulaşmadan önce sergideki her modeli ...'::text,'incelemişti'::text,'inceledi'::text,'inceliyordu'::text,'Dev beyne ulaşmadan önce sergideki her modeli incelemişti.'::text),
(351369,39041,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt az óriási agyhoz ért, ... a kiállítás minden modelljét.'::text,'megnézte'::text,'megnézte'::text,'nézegette'::text,'Mielőtt az óriási agyhoz ért, megnézte a kiállítás minden modelljét.'::text),
(372720,41414,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während die Parade die Straße entlang ..., rannte sie, als wäre es das Ende der Welt!'::text,'tanzte'::text,'tanzte'::text,'getanzt hat'::text,'Während die Parade die Straße entlang tanzte, rannte sie, als wäre es das Ende der Welt!'::text),
(372724,41414,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки парад ... вулицею, вона бігла, ніби настав кінець світу!'::text,'танцював'::text,'танцював'::text,'протанцював'::text,'Поки парад танцював вулицею, вона бігла, ніби настав кінець світу!'::text),
(372723,41414,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mientras el desfile ... calle abajo, ella corría como si fuera el fin del mundo!'::text,'bailaba'::text,'bailó'::text,'ha bailado'::text,'¡Mientras el desfile bailaba calle abajo, ella corría como si fuera el fin del mundo!'::text),
(372722,41414,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que le défilé ... dans la rue, elle courait comme si c''était la fin du monde !'::text,'dansait'::text,'a dansé'::text,'a dansé'::text,'Pendant que le défilé dansait dans la rue, elle courait comme si c''était la fin du monde !'::text),
(372725,41414,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geçit töreni caddede ..., o dünyanın sonu gelmiş gibi koştu!'::text,'dans ederken'::text,'dans etti'::text,'dans etti'::text,'Geçit töreni caddede dans ederken, o dünyanın sonu gelmiş gibi koştu!'::text),
(372726,41414,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a felvonulás ... végig az utcán, ő úgy rohant, mintha itt lenne a világvége!'::text,'táncolt'::text,'táncolt'::text,'táncolt'::text,'Miközben a felvonulás táncolt végig az utcán, ő úgy rohant, mintha itt lenne a világvége!'::text),
(372729,41415,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Parade ... schon seit einer Stunde hinter ihr her, und das Konfetti ist wirklich überall!'::text,'tanzt'::text,'tanzt'::text,'tanzt'::text,'Diese Parade tanzt schon seit einer Stunde hinter ihr her, und das Konfetti ist wirklich überall!'::text),
(372733,41415,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей парад ... позаду неї вже годину, і конфетті буквально всюди!'::text,'танцює'::text,'танцює'::text,'танцює'::text,'Цей парад танцює позаду неї вже годину, і конфетті буквально всюди!'::text),
(372732,41415,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Este desfile ... detrás de ella desde hace una hora, y el confeti está literalmente por todas partes!'::text,'lleva bailando'::text,'está bailando'::text,'baila'::text,'¡Este desfile lleva bailando detrás de ella desde hace una hora, y el confeti está literalmente por todas partes!'::text),
(372731,41415,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce défilé ... derrière elle depuis une heure, et il y a littéralement des confettis partout !'::text,'danse'::text,'danse'::text,'danse'::text,'Ce défilé danse derrière elle depuis une heure, et il y a littéralement des confettis partout !'::text),
(372734,41415,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu geçit töreni bir saattir arkasında ... ve konfeti resmen her yerde!'::text,'dans ediyor'::text,'dans ediyor'::text,'dans eder'::text,'Bu geçit töreni bir saattir arkasında dans ediyor ve konfeti resmen her yerde!'::text),
(372735,41415,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a felvonulás már egy órája ... mögötte, és a konfetti szó szerint mindenhol ott van!'::text,'táncol'::text,'táncol'::text,'táncol'::text,'Ez a felvonulás már egy órája táncol mögötte, és a konfetti szó szerint mindenhol ott van!'::text),
(372738,41416,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... gerade die Straße entlang, als die ganze Parade plötzlich in Konfetti explodierte!'::text,'rannte'::text,'rannte'::text,'ist gerannt'::text,'Sie rannte gerade die Straße entlang, als die ganze Parade plötzlich in Konfetti explodierte!'::text),
(372742,41416,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... вулицею, коли весь парад раптом вибухнув конфетті!'::text,'бігла'::text,'пробігла'::text,'пробігла'::text,'Вона бігла вулицею, коли весь парад раптом вибухнув конфетті!'::text),
(372741,41416,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... calle abajo cuando todo el desfile estalló de repente en confeti!'::text,'estaba corriendo'::text,'corrió'::text,'ha corrido'::text,'¡Ella estaba corriendo calle abajo cuando todo el desfile estalló de repente en confeti!'::text),
(372740,41416,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... dans la rue quand tout le défilé a soudain explosé en confettis !'::text,'courait'::text,'a couru'::text,'a couru'::text,'Elle courait dans la rue quand tout le défilé a soudain explosé en confettis !'::text),
(372743,41416,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün geçit töreni aniden konfetiye boğulduğunda o caddede ...!'::text,'koşuyordu'::text,'koştu'::text,'koştu'::text,'Bütün geçit töreni aniden konfetiye boğulduğunda o caddede koşuyordu!'::text),
(372744,41416,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... az utcán, amikor az egész felvonulás hirtelen konfettiesőben robbant fel!'::text,'futott'::text,'futott'::text,'futott'::text,'Épp futott az utcán, amikor az egész felvonulás hirtelen konfettiesőben robbant fel!'::text),
(372747,41417,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, anscheinend ... sie den ganzen Tag vor der Parade her, und sie lacht immer noch.'::text,'rennt'::text,'rannte'::text,'rennt'::text,'Mädel, anscheinend rennt sie den ganzen Tag vor der Parade her, und sie lacht immer noch.'::text),
(372751,41417,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона ... перед парадом цілий день і досі сміється.'::text,'бігає'::text,'бігала'::text,'бігає'::text,'Подруго, кажуть, вона бігає перед парадом цілий день і досі сміється.'::text),
(372750,41417,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ella ... delante del desfile todo el día, y todavía se está riendo.'::text,'lleva corriendo'::text,'corrió'::text,'está corriendo'::text,'Tía, al parecer ella lleva corriendo delante del desfile todo el día, y todavía se está riendo.'::text),
(372749,41417,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment elle ... devant le défilé toute la journée, et elle rigole encore.'::text,'court'::text,'a couru'::text,'court'::text,'Meuf, apparemment elle court devant le défilé toute la journée, et elle rigole encore.'::text),
(372752,41417,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, anlaşılan bütün gün geçit töreninin önünde ... ve hâlâ gülüyor.'::text,'koşuyor'::text,'koştu'::text,'koşuyor'::text,'Kızım, anlaşılan bütün gün geçit töreninin önünde koşuyor ve hâlâ gülüyor.'::text),
(372753,41417,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag egész nap ... a felvonulás előtt, és még mindig nevet.'::text,'futkos'::text,'futott'::text,'fut'::text,'Csajszi, állítólag egész nap futkos a felvonulás előtt, és még mindig nevet.'::text),
(372756,41418,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, dass die Tänzer bis zum Start der Parade jede Paillette zweimal ...'::text,'kontrolliert hatten'::text,'kontrolliert haben'::text,'kontrollieren'::text,'Hör mal, ich hab gehört, dass die Tänzer bis zum Start der Parade jede Paillette zweimal kontrolliert hatten.'::text),
(372760,41418,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що поки почався парад, танцюристи ... кожну блискітку двічі.'::text,'перевірили'::text,'перевірили'::text,'перевіряють'::text,'Слухай, я чула, що поки почався парад, танцюристи перевірили кожну блискітку двічі.'::text),
(372759,41418,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me han dicho que, para cuando empezó el desfile, los bailarines ya ... cada lentejuela dos veces.'::text,'habían revisado'::text,'han revisado'::text,'revisan'::text,'Oye, me han dicho que, para cuando empezó el desfile, los bailarines ya habían revisado cada lentejuela dos veces.'::text),
(372758,41418,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il paraît qu''au début du défilé, les danseurs ... chaque paillette deux fois.'::text,'avaient vérifié'::text,'ont vérifié'::text,'vérifient'::text,'Écoute, il paraît qu''au début du défilé, les danseurs avaient vérifié chaque paillette deux fois.'::text),
(372761,41418,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre geçit töreni başladığında dansçılar her pulu iki kez ...'::text,'kontrol etmişlerdi'::text,'kontrol ettiler'::text,'kontrol ediyorlar'::text,'Dinle, duyduğuma göre geçit töreni başladığında dansçılar her pulu iki kez kontrol etmişlerdi.'::text),
(372762,41418,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy mire a felvonulás elkezdődött, a táncosok minden flittert kétszer ...'::text,'ellenőriztek'::text,'ellenőriztek'::text,'ellenőriznek'::text,'Figyelj, azt hallottam, hogy mire a felvonulás elkezdődött, a táncosok minden flittert kétszer ellenőriztek.'::text),
(372765,41419,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie weiter so schnell rennt, ... die Parade sie in der nächsten Straße nicht einholen.'::text,'wird'::text,'würde'::text,'konnte'::text,'Wenn sie weiter so schnell rennt, wird die Parade sie in der nächsten Straße nicht einholen.'::text),
(372769,41419,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона й далі так швидко бігтиме, парад ... її на наступній вулиці.'::text,'не наздожене'::text,'не наздогнав би'::text,'не наздогнав'::text,'Якщо вона й далі так швидко бігтиме, парад не наздожене її на наступній вулиці.'::text),
(372768,41419,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si sigue corriendo tan rápido, el desfile no la ... en la siguiente calle.'::text,'alcanzará'::text,'alcanzaría'::text,'alcanzó'::text,'Si sigue corriendo tan rápido, el desfile no la alcanzará en la siguiente calle.'::text),
(372767,41419,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle continue à courir aussi vite, le défilé ... dans la rue suivante.'::text,'ne la rattrapera pas'::text,'ne la rattraperait pas'::text,'ne l''a pas rattrapée'::text,'Si elle continue à courir aussi vite, le défilé ne la rattrapera pas dans la rue suivante.'::text),
(372770,41419,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu kadar hızlı koşmaya devam ederse geçit töreni onu bir sonraki sokakta ...'::text,'yakalayamayacak'::text,'yakalayamazdı'::text,'yakalayamadı'::text,'Bu kadar hızlı koşmaya devam ederse geçit töreni onu bir sonraki sokakta yakalayamayacak.'::text),
(372771,41419,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha így rohan tovább, a felvonulás a következő utcában ... őt.'::text,'nem éri utol'::text,'nem érné utol'::text,'nem érte utol'::text,'Ha így rohan tovább, a felvonulás a következő utcában nem éri utol őt.'::text),
(372783,41421,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Parade ... mit der Kamera gefilmt, während sie vor den Tänzern herlief.'::text,'wurde'::text,'filmte'::text,'wird'::text,'Die Parade wurde mit der Kamera gefilmt, während sie vor den Tänzern herlief.'::text),
(372787,41421,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Парад ... на камеру, поки вона бігла попереду танцюристів.'::text,'зняли'::text,'знімав'::text,'знімають'::text,'Парад зняли на камеру, поки вона бігла попереду танцюристів.'::text),
(372786,41421,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El desfile ... con la cámara mientras ella corría delante de los bailarines.'::text,'fue grabado'::text,'grabó'::text,'es grabado'::text,'El desfile fue grabado con la cámara mientras ella corría delante de los bailarines.'::text),
(372785,41421,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le défilé ... à la caméra pendant qu''elle courait devant les danseurs.'::text,'a été filmé'::text,'a filmé'::text,'est filmé'::text,'Le défilé a été filmé à la caméra pendant qu''elle courait devant les danseurs.'::text),
(372788,41421,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O dansçıların önünde koşarken geçit töreni kameraya ...'::text,'çekildi'::text,'çekti'::text,'çekiliyor'::text,'O dansçıların önünde koşarken geçit töreni kameraya çekildi.'::text),
(372789,41421,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A felvonulást kamerával ..., miközben ő a táncosok előtt futott.'::text,'vették fel'::text,'felvette'::text,'veszik fel'::text,'A felvonulást kamerával vették fel, miközben ő a táncosok előtt futott.'::text),
(372792,41422,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Karnevalsparade ... gestern Tausende Touristen auf die Straße.'::text,'brachte'::text,'wurde gebracht'::text,'bringend'::text,'Die Karnevalsparade brachte gestern Tausende Touristen auf die Straße.'::text),
(372796,41422,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Карнавальний парад учора ... тисячі туристів на вулицю.'::text,'привів'::text,'був приведений'::text,'приводячи'::text,'Карнавальний парад учора привів тисячі туристів на вулицю.'::text),
(372795,41422,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El desfile de carnaval ... ayer a miles de turistas a la calle.'::text,'trajo'::text,'fue traído'::text,'trayendo'::text,'El desfile de carnaval trajo ayer a miles de turistas a la calle.'::text),
(372794,41422,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le défilé du carnaval ... des milliers de touristes dans la rue hier.'::text,'a amené'::text,'a été amené'::text,'amenant'::text,'Le défilé du carnaval a amené des milliers de touristes dans la rue hier.'::text),
(372797,41422,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Karnaval geçit töreni dün binlerce turisti sokağa ...'::text,'getirdi'::text,'getirildi'::text,'getirerek'::text,'Karnaval geçit töreni dün binlerce turisti sokağa getirdi.'::text),
(372798,41422,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A karneváli felvonulás tegnap turisták ezreit ... az utcára.'::text,'hozta ki'::text,'ki lett hozva'::text,'kihozva'::text,'A karneváli felvonulás tegnap turisták ezreit hozta ki az utcára.'::text),
(372801,41423,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie rannte vor ... Parade, die sie je gesehen hatte, die Straße entlang.'::text,'der größten'::text,'einer größten'::text,'größten'::text,'Sie rannte vor der größten Parade, die sie je gesehen hatte, die Straße entlang.'::text),
(372805,41423,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона бігла вулицею попереду ... параду, який вона колись бачила.'::text,'найбільшого'::text,'найбільшого'::text,'найбільшого'::text,'Вона бігла вулицею попереду найбільшого параду, який вона колись бачила.'::text),
(372804,41423,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Corrió calle abajo ante ... desfile que había visto jamás.'::text,'el mayor'::text,'un mayor'::text,'mayor'::text,'Corrió calle abajo ante el mayor desfile que había visto jamás.'::text),
(372803,41423,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle courait dans la rue devant ... défilé qu''elle ait jamais vu.'::text,'le plus grand'::text,'un plus grand'::text,'plus grand'::text,'Elle courait dans la rue devant le plus grand défilé qu''elle ait jamais vu.'::text),
(372806,41423,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayatında gördüğü ... geçit töreninin önünde caddede koştu.'::text,'en büyük'::text,'en büyük'::text,'en büyük'::text,'Hayatında gördüğü en büyük geçit töreninin önünde caddede koştu.'::text),
(372807,41423,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Végigfutott az utcán ... felvonulás előtt, amit valaha látott.'::text,'a legnagyobb'::text,'egy legnagyobb'::text,'legnagyobb'::text,'Végigfutott az utcán a legnagyobb felvonulás előtt, amit valaha látott.'::text),
(392898,43656,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, ich hab gehört, dass sie morgen den ganzen Vormittag auf Betonblöcke ...'::text,'einschlagen wird'::text,'einschlagen wird'::text,'einschlägt'::text,'Mädel, ich hab gehört, dass sie morgen den ganzen Vormittag auf Betonblöcke einschlagen wird.'::text),
(392902,43656,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що завтра весь ранок вона ... по бетонних блоках.'::text,'битиме'::text,'вдарить'::text,'б''є'::text,'Подруго, я чула, що завтра весь ранок вона битиме по бетонних блоках.'::text),
(392901,43656,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, he oído que mañana ella ... bloques de hormigón toda la mañana.'::text,'estará golpeando'::text,'golpeará'::text,'golpea'::text,'Tía, he oído que mañana ella estará golpeando bloques de hormigón toda la mañana.'::text),
(392900,43656,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il paraît qu''elle ... des blocs de béton toute la matinée demain.'::text,'sera en train de frapper'::text,'frappera'::text,'frappe'::text,'Meuf, il paraît qu''elle sera en train de frapper des blocs de béton toute la matinée demain.'::text),
(392903,43656,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duydum ki yarın bütün sabah beton bloklara ...'::text,'vuruyor olacak'::text,'vuracak'::text,'vuruyor'::text,'Kızım, duydum ki yarın bütün sabah beton bloklara vuruyor olacak.'::text),
(392904,43656,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy holnap egész délelőtt ... a betontömböket.'::text,'ütni fogja'::text,'üti majd'::text,'üti'::text,'Csajszi, azt hallottam, hogy holnap egész délelőtt ütni fogja a betontömböket.'::text),
(392907,43657,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, sie schwört, dass sie als Nächstes den Beton ..., und keiner glaubt es.'::text,'durchschlagen wird'::text,'gerade durchschlagen wird'::text,'gerade durchschlägt'::text,'Hör mal, sie schwört, dass sie als Nächstes den Beton durchschlagen wird, und keiner glaubt es.'::text),
(392911,43657,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона клянеться, що наступним ... бетон, і ніхто не вірить.'::text,'розіб''є'::text,'розбиватиме'::text,'розбиває'::text,'Слухай, вона клянеться, що наступним розіб''є бетон, і ніхто не вірить.'::text),
(392910,43657,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, jura que después ... el hormigón, y nadie se lo cree.'::text,'golpeará'::text,'estará golpeando'::text,'está golpeando'::text,'Oye, jura que después golpeará el hormigón, y nadie se lo cree.'::text),
(392909,43657,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle jure qu''ensuite elle ... le béton, et personne n''y croit.'::text,'frappera'::text,'sera en train de frapper'::text,'frappe'::text,'Écoute, elle jure qu''ensuite elle frappera le béton, et personne n''y croit.'::text),
(392912,43657,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bir sonraki adımda betona ... yemin ediyor ve kimse buna inanmıyor.'::text,'vuracağına'::text,'vuruyor olacağına'::text,'vurduğuna'::text,'Dinle, bir sonraki adımda betona vuracağına yemin ediyor ve kimse buna inanmıyor.'::text),
(392913,43657,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, esküszik, hogy legközelebb a betont ..., és senki sem hiszi el.'::text,'üti szét'::text,'fogja ütni'::text,'üti'::text,'Figyelj, esküszik, hogy legközelebb a betont üti szét, és senki sem hiszi el.'::text),
(392925,43659,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du hast Beton durchschlagen, also ... du jahrelang trainiert haben.'::text,'musst'::text,'könntest'::text,'kannst nicht'::text,'Ehrlich, du hast Beton durchschlagen, also musst du jahrelang trainiert haben.'::text),
(392929,43659,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти пробила бетон, тож ти ... тренуватися роками.'::text,'мусила'::text,'могла'::text,'не могла'::text,'Чесно, ти пробила бетон, тож ти мусила тренуватися роками.'::text),
(392928,43659,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, atravesaste hormigón, así que ... entrenado durante años.'::text,'debes de haber'::text,'podrías haber'::text,'no puedes haber'::text,'La verdad, atravesaste hormigón, así que debes de haber entrenado durante años.'::text),
(392927,43659,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, t''as traversé du béton, donc tu ... t''être entraînée pendant des années.'::text,'dois'::text,'pourrais'::text,'ne peux pas'::text,'Franchement, t''as traversé du béton, donc tu dois t''être entraînée pendant des années.'::text),
(392930,43659,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası betonu delip geçtin, demek yıllarca antrenman ...'::text,'yapmış olmalısın'::text,'yapmış olabilirsin'::text,'yapmış olamazsın'::text,'Açıkçası betonu delip geçtin, demek yıllarca antrenman yapmış olmalısın.'::text),
(392931,43659,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, átütötted a betont, szóval ... évekig edzettél.'::text,'biztosan'::text,'talán'::text,'nem lehet, hogy'::text,'Őszintén, átütötted a betont, szóval biztosan évekig edzettél.'::text),
(392934,43660,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau, ... Hand auf die Platten schlug, hat den schwarzen Gürtel.'::text,'deren'::text,'die'::text,'welche'::text,'Die Frau, deren Hand auf die Platten schlug, hat den schwarzen Gürtel.'::text),
(392938,43660,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка, ... рука вдарила по плитах, має чорний пояс.'::text,'чия'::text,'яка'::text,'котра'::text,'Жінка, чия рука вдарила по плитах, має чорний пояс.'::text),
(392937,43660,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer ... mano golpeó las losas es cinturón negro.'::text,'cuya'::text,'que'::text,'la cual'::text,'La mujer cuya mano golpeó las losas es cinturón negro.'::text),
(392936,43660,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme ... la main a frappé les dalles est ceinture noire.'::text,'dont'::text,'qui'::text,'que'::text,'La femme dont la main a frappé les dalles est ceinture noire.'::text),
(392939,43660,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eli plakalara ... kadın siyah kuşak.'::text,'vuran'::text,'vuran'::text,'vuran'::text,'Eli plakalara vuran kadın siyah kuşak.'::text),
(392940,43660,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő, ... keze lesújtott a lapokra, fekete öves.'::text,'akinek a'::text,'aki'::text,'amely'::text,'A nő, akinek a keze lesújtott a lapokra, fekete öves.'::text),
(392943,43661,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie sagte, sie ... nach den Fliesen die Betonplatten zerschlagen.'::text,'würde'::text,'werde'::text,'zerschlage'::text,'Sie sagte, sie würde nach den Fliesen die Betonplatten zerschlagen.'::text),
(392947,43661,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала, що після плиток ... по бетонних плитах.'::text,'вдарить'::text,'вдарить'::text,'б''є'::text,'Вона сказала, що після плиток вдарить по бетонних плитах.'::text),
(392946,43661,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que después de las baldosas ... las losas de hormigón.'::text,'golpearía'::text,'golpeará'::text,'golpea'::text,'Dijo que después de las baldosas golpearía las losas de hormigón.'::text),
(392945,43661,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a dit qu''elle ... les dalles de béton après les carreaux.'::text,'frapperait'::text,'frappera'::text,'frappe'::text,'Elle a dit qu''elle frapperait les dalles de béton après les carreaux.'::text),
(392948,43661,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Karolardan sonra beton plakalara ... söyledi.'::text,'vuracağını'::text,'vuracağını'::text,'vurduğunu'::text,'Karolardan sonra beton plakalara vuracağını söyledi.'::text),
(392949,43661,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy a csempék után a betonlapokat ...'::text,'üti szét'::text,'fogja ütni'::text,'üti'::text,'Azt mondta, hogy a csempék után a betonlapokat üti szét.'::text),
(392952,43662,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als Anfängerin ... sie nur dünne Holzbretter.'::text,'zerschlug'::text,'war es gewohnt zu zerschlagen'::text,'zerschlug'::text,'Als Anfängerin zerschlug sie nur dünne Holzbretter.'::text),
(392956,43662,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Як новачка, вона ... лише по тонких дерев''яних дошках.'::text,'раніше била'::text,'звикла бити'::text,'раніше била'::text,'Як новачка, вона раніше била лише по тонких дерев''яних дошках.'::text),
(392955,43662,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De principiante, ... golpear solo tablas finas de madera.'::text,'solía'::text,'estaba acostumbrada a'::text,'solía'::text,'De principiante, solía golpear solo tablas finas de madera.'::text),
(392954,43662,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand elle débutait, elle ... seulement de fines planches de bois.'::text,'frappait'::text,'avait l''habitude de frapper'::text,'frappait'::text,'Quand elle débutait, elle frappait seulement de fines planches de bois.'::text),
(392957,43662,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yeni başladığında sadece ince tahtalara ...'::text,'vururdu'::text,'vurmaya alışkındı'::text,'vururdu'::text,'Yeni başladığında sadece ince tahtalara vururdu.'::text),
(392958,43662,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kezdőként csak vékony fadeszkákat ...'::text,'ütött szét'::text,'volt hozzászokva szétütni'::text,'ütött szét'::text,'Kezdőként csak vékony fadeszkákat ütött szét.'::text),
(392961,43663,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie beschloss, den Beton ..., und er zerbrach komplett!'::text,'zu schlagen'::text,'schlagend'::text,'schlagen'::text,'Sie beschloss, den Beton zu schlagen, und er zerbrach komplett!'::text),
(392965,43663,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона вирішила ... по бетону, і він повністю розсипався!'::text,'вдарити'::text,'б''ючи'::text,'вдарити'::text,'Вона вирішила вдарити по бетону, і він повністю розсипався!'::text),
(392964,43663,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Decidió ... el hormigón, y se derrumbó por completo!'::text,'golpear'::text,'golpeando'::text,'golpear'::text,'¡Decidió golpear el hormigón, y se derrumbó por completo!'::text),
(392963,43663,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a décidé ... le béton, et il s''est complètement effondré !'::text,'de frapper'::text,'frapper'::text,'frapper'::text,'Elle a décidé de frapper le béton, et il s''est complètement effondré !'::text),
(392966,43663,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Betona ... karar verdi ve beton tamamen çöktü!'::text,'vurmaya'::text,'vurmaya'::text,'vur'::text,'Betona vurmaya karar verdi ve beton tamamen çöktü!'::text),
(392967,43663,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy döntött, hogy ... a betont, és az teljesen összeomlott!'::text,'megüti'::text,'ütve'::text,'üt'::text,'Úgy döntött, hogy megüti a betont, és az teljesen összeomlott!'::text),
(392970,43664,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wow! Sie schlägt zu wie ein absoluter Albtraum, ...?'::text,'nicht wahr'::text,'nicht wahr'::text,'nicht wahr'::text,'Wow! Sie schlägt zu wie ein absoluter Albtraum, nicht wahr?'::text),
(392974,43664,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ого! Вона б''є як справжній кошмар, ...?'::text,'чи не так'::text,'чи не так'::text,'чи не так'::text,'Ого! Вона б''є як справжній кошмар, чи не так?'::text),
(392973,43664,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Guau! Golpea como una auténtica pesadilla, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'¡Guau! Golpea como una auténtica pesadilla, ¿verdad?'::text),
(392972,43664,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Waouh ! Elle frappe comme un vrai cauchemar, ... ?'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'Waouh ! Elle frappe comme un vrai cauchemar, n''est-ce pas ?'::text),
(392975,43664,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vay! Tam bir kâbus gibi vuruyor, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Vay! Tam bir kâbus gibi vuruyor, değil mi?'::text),
(392976,43664,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hűha! Úgy üt, mint egy igazi rémálom, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Hűha! Úgy üt, mint egy igazi rémálom, ugye?'::text),
(392979,43665,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... sie auf den Beton ein, und er zerbröckelt total!'::text,'schlägt'::text,'schlägt'::text,'schlug'::text,'Gerade schlägt sie auf den Beton ein, und er zerbröckelt total!'::text),
(392983,43665,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прямо зараз вона ... по бетону, і він просто кришиться!'::text,'б''є'::text,'б''є'::text,'вдарила'::text,'Прямо зараз вона б''є по бетону, і він просто кришиться!'::text),
(392982,43665,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ahora mismo ella ... el hormigón, y se está desmoronando por completo!'::text,'está golpeando'::text,'golpea'::text,'ha golpeado'::text,'¡Ahora mismo ella está golpeando el hormigón, y se está desmoronando por completo!'::text),
(392981,43665,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, elle ... le béton, et il s''effrite complètement !'::text,'frappe'::text,'frappe'::text,'a frappé'::text,'En ce moment, elle frappe le béton, et il s''effrite complètement !'::text),
(392984,43665,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda betona ... ve beton resmen ufalanıyor!'::text,'vuruyor'::text,'vurur'::text,'vurdu'::text,'Şu anda betona vuruyor ve beton resmen ufalanıyor!'::text),
(392985,43665,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most ... a betont, és az teljesen morzsolódik!'::text,'üti'::text,'üti'::text,'ütötte'::text,'Épp most üti a betont, és az teljesen morzsolódik!'::text),
(336324,37370,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während sie auf dem gefrorenen Hang ..., wurde jeder Atemzug zu einer furchterregenden weißen Wolke!'::text,'stand'::text,'stand'::text,'gestanden hat'::text,'Während sie auf dem gefrorenen Hang stand, wurde jeder Atemzug zu einer furchterregenden weißen Wolke!'::text),
(336328,37370,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона ... на замерзлому схилі, кожен подих перетворювався на моторошну білу хмару!'::text,'стояла'::text,'постояла'::text,'постояла'::text,'Поки вона стояла на замерзлому схилі, кожен подих перетворювався на моторошну білу хмару!'::text),
(336327,37370,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mientras ella ... en la ladera helada, cada aliento se convertía en una aterradora nube blanca!'::text,'estaba de pie'::text,'estuvo de pie'::text,'ha estado de pie'::text,'¡Mientras ella estaba de pie en la ladera helada, cada aliento se convertía en una aterradora nube blanca!'::text),
(336326,37370,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''elle ... sur la pente gelée, chaque souffle se transformait en un terrifiant nuage blanc !'::text,'se tenait'::text,'s''est tenue'::text,'s''est tenue'::text,'Pendant qu''elle se tenait sur la pente gelée, chaque souffle se transformait en un terrifiant nuage blanc !'::text),
(336329,37370,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Donmuş yamaçta ..., her nefesi korkunç beyaz bir buluta dönüşüyordu!'::text,'dururken'::text,'durdu'::text,'durdu'::text,'Donmuş yamaçta dururken, her nefesi korkunç beyaz bir buluta dönüşüyordu!'::text),
(336330,37370,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a fagyott lejtőn ..., minden lélegzete ijesztő fehér felhővé vált!'::text,'állt'::text,'állt'::text,'állt'::text,'Miközben a fagyott lejtőn állt, minden lélegzete ijesztő fehér felhővé vált!'::text),
(336333,37371,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das ist das Schlimmste! Sie ... seit zehn Minuten weiße Atemwolken aus und kann immer noch nicht aufhören!'::text,'bläst'::text,'blies'::text,'bläst'::text,'Das ist das Schlimmste! Sie bläst seit zehn Minuten weiße Atemwolken aus und kann immer noch nicht aufhören!'::text),
(336337,37371,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це найгірше! Вона ... білі хмари подиху вже десять хвилин і досі не може зупинитися!'::text,'видихає'::text,'видихнула'::text,'видихає'::text,'Це найгірше! Вона видихає білі хмари подиху вже десять хвилин і досі не може зупинитися!'::text),
(336336,37371,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Es lo peor! ¡Ella ... nubes blancas de aliento desde hace diez minutos y todavía no puede parar!'::text,'lleva soltando'::text,'ha soltado'::text,'está soltando'::text,'¡Es lo peor! ¡Ella lleva soltando nubes blancas de aliento desde hace diez minutos y todavía no puede parar!'::text),
(336335,37371,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est le pire ! Elle ... des nuages blancs de souffle depuis dix minutes et elle n''arrive toujours pas à s''arrêter !'::text,'souffle'::text,'a soufflé'::text,'souffle'::text,'C''est le pire ! Elle souffle des nuages blancs de souffle depuis dix minutes et elle n''arrive toujours pas à s''arrêter !'::text),
(336338,37371,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu en kötüsü! On dakikadır beyaz nefes bulutları ... ve hâlâ duramıyor!'::text,'üflüyor'::text,'üfledi'::text,'üflüyor'::text,'Bu en kötüsü! On dakikadır beyaz nefes bulutları üflüyor ve hâlâ duramıyor!'::text),
(336339,37371,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a legrosszabb! Tíz perce ... a fehér leheletfelhőket, és még mindig nem tudja abbahagyni!'::text,'fújja'::text,'fújta'::text,'fújja'::text,'Ez a legrosszabb! Tíz perce fújja a fehér leheletfelhőket, és még mindig nem tudja abbahagyni!'::text),
(336342,37372,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, sie hat mir erzählt, dass sie vor dieser Reise ihren Atem nie so gefrieren ...'::text,'gesehen hatte'::text,'gesehen hat'::text,'sieht'::text,'Mädel, sie hat mir erzählt, dass sie vor dieser Reise ihren Atem nie so gefrieren gesehen hatte.'::text),
(336346,37372,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала мені, що до цієї поїздки ..., як її подих так замерзає.'::text,'ніколи не бачила'::text,'ніколи не бачила'::text,'ніколи не бачить'::text,'Подруго, вона сказала мені, що до цієї поїздки ніколи не бачила, як її подих так замерзає.'::text),
(336345,37372,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me contó que antes de este viaje ... su aliento congelarse así.'::text,'nunca había visto'::text,'nunca ha visto'::text,'nunca ve'::text,'Tía, me contó que antes de este viaje nunca había visto su aliento congelarse así.'::text),
(336344,37372,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, elle m''a dit qu''avant ce voyage, elle ... son souffle geler comme ça.'::text,'n''avait jamais vu'::text,'n''a jamais vu'::text,'ne voit jamais'::text,'Meuf, elle m''a dit qu''avant ce voyage, elle n''avait jamais vu son souffle geler comme ça.'::text),
(336347,37372,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana bu geziden önce nefesinin böyle donduğunu hiç ... söyledi.'::text,'görmemiş olduğunu'::text,'görmediğini'::text,'görmediğini'::text,'Kızım, bana bu geziden önce nefesinin böyle donduğunu hiç görmemiş olduğunu söyledi.'::text),
(336348,37372,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy ezelőtt az út előtt még ..., hogy így megfagyjon a lehelete.'::text,'sosem látta'::text,'sosem látta'::text,'sosem látja'::text,'Csajszi, azt mondta, hogy ezelőtt az út előtt még sosem látta, hogy így megfagyjon a lehelete.'::text),
(336351,37373,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... sie auf einem anderen Berg weiße Atemwolken pusten.'::text,'wird'::text,'wird'::text,'pustet'::text,'Morgen um diese Zeit wird sie auf einem anderen Berg weiße Atemwolken pusten.'::text),
(336355,37373,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час вона ... білі хмарки подиху на іншій горі.'::text,'видихатиме'::text,'видихне'::text,'видихає'::text,'Завтра в цей час вона видихатиме білі хмарки подиху на іншій горі.'::text),
(336354,37373,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, ella ... nubes blancas de aliento en otra montaña.'::text,'estará soltando'::text,'soltará'::text,'suelta'::text,'Mañana a esta hora, ella estará soltando nubes blancas de aliento en otra montaña.'::text),
(336353,37373,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à cette heure-ci, elle ... des nuages de souffle blancs sur une autre montagne.'::text,'sera en train de souffler'::text,'soufflera'::text,'souffle'::text,'Demain à cette heure-ci, elle sera en train de souffler des nuages de souffle blancs sur une autre montagne.'::text),
(336356,37373,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte başka bir dağda beyaz nefes bulutları ...'::text,'üflüyor olacak'::text,'üfleyecek'::text,'üflüyor'::text,'Yarın bu saatte başka bir dağda beyaz nefes bulutları üflüyor olacak.'::text),
(336357,37373,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor egy másik hegyen ... a fehér leheletfelhőket.'::text,'fogja fújni'::text,'fújja majd'::text,'fújja'::text,'Holnap ilyenkor egy másik hegyen fogja fújni a fehér leheletfelhőket.'::text),
(336360,37374,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bei dieser Kälte ... sich auch ihr nächster Atemzug in eine weiße Wolke verwandeln.'::text,'wird'::text,'wird'::text,'verwandelte'::text,'Bei dieser Kälte wird sich auch ihr nächster Atemzug in eine weiße Wolke verwandeln.'::text),
(336364,37374,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У такий холод її наступний подих теж ... на білу хмару.'::text,'перетвориться'::text,'перетворюватиметься'::text,'перетворився'::text,'У такий холод її наступний подих теж перетвориться на білу хмару.'::text),
(336363,37374,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Con este frío, su próximo aliento también ... en una nube blanca.'::text,'se convertirá'::text,'se estará convirtiendo'::text,'se convirtió'::text,'Con este frío, su próximo aliento también se convertirá en una nube blanca.'::text),
(336362,37374,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Par ce froid, son prochain souffle ... aussi en nuage blanc.'::text,'se transformera'::text,'sera en train de se transformer'::text,'s''est transformé'::text,'Par ce froid, son prochain souffle se transformera aussi en nuage blanc.'::text),
(336365,37374,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu soğukta bir sonraki nefesi de beyaz bir buluta ...'::text,'dönüşecek'::text,'dönüşüyor olacak'::text,'dönüştü'::text,'Bu soğukta bir sonraki nefesi de beyaz bir buluta dönüşecek.'::text),
(336366,37374,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebben a hidegben a következő lélegzete is fehér felhővé ...'::text,'válik'::text,'fog válni'::text,'vált'::text,'Ebben a hidegben a következő lélegzete is fehér felhővé válik.'::text),
(336369,37375,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Luft sehr kalt ist, ... ein warmer Atemzug eine weiße Wolke.'::text,'bildet'::text,'bildete'::text,'wird bilden'::text,'Wenn die Luft sehr kalt ist, bildet ein warmer Atemzug eine weiße Wolke.'::text),
(336373,37375,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо повітря дуже холодне, теплий подих ... білу хмару.'::text,'утворює'::text,'утворив'::text,'утворить'::text,'Якщо повітря дуже холодне, теплий подих утворює білу хмару.'::text),
(336372,37375,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el aire está muy frío, un aliento cálido ... una nube blanca.'::text,'forma'::text,'formó'::text,'formará'::text,'Si el aire está muy frío, un aliento cálido forma una nube blanca.'::text),
(336371,37375,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''air est très froid, un souffle chaud ... un nuage blanc.'::text,'forme'::text,'a formé'::text,'formera'::text,'Si l''air est très froid, un souffle chaud forme un nuage blanc.'::text),
(336374,37375,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hava çok soğuksa sıcak bir nefes beyaz bir bulut ...'::text,'oluşturur'::text,'oluşturdu'::text,'oluşturacak'::text,'Hava çok soğuksa sıcak bir nefes beyaz bir bulut oluşturur.'::text),
(336375,37375,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a levegő nagyon hideg, a meleg lehelet fehér felhőt ...'::text,'képez'::text,'képzett'::text,'fog képezni'::text,'Ha a levegő nagyon hideg, a meleg lehelet fehér felhőt képez.'::text),
(336387,37377,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, wenn ich solche Atemwolken wie du machen würde, ... ich den ganzen Tag hier oben bleiben.'::text,'würde'::text,'werde'::text,'blieb'::text,'Ehrlich gesagt, wenn ich solche Atemwolken wie du machen würde, würde ich den ganzen Tag hier oben bleiben.'::text),
(336391,37377,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брехатиму, якби я робив такі хмарки подиху, як у тебе, я ... тут нагорі цілий день.'::text,'залишився б'::text,'залишуся'::text,'залишився'::text,'Не брехатиму, якби я робив такі хмарки подиху, як у тебе, я залишився б тут нагорі цілий день.'::text),
(336390,37377,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, si yo hiciera nubes de aliento como las tuyas, ... aquí arriba todo el día.'::text,'me quedaría'::text,'me quedaré'::text,'me quedé'::text,'No voy a mentir, si yo hiciera nubes de aliento como las tuyas, me quedaría aquí arriba todo el día.'::text),
(336389,37377,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, si je faisais des nuages de souffle comme les tiens, je ... ici toute la journée.'::text,'resterais'::text,'resterai'::text,'suis resté'::text,'Je vais pas mentir, si je faisais des nuages de souffle comme les tiens, je resterais ici toute la journée.'::text),
(336392,37377,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, senin gibi nefes bulutları yapsaydım bütün gün burada ...'::text,'kalırdım'::text,'kalacağım'::text,'kaldım'::text,'Yalan yok, senin gibi nefes bulutları yapsaydım bütün gün burada kalırdım.'::text),
(336393,37377,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, ha olyan leheletfelhőket csinálnék, mint te, egész nap itt fent ...'::text,'maradnék'::text,'maradok'::text,'maradtam'::text,'Nem hazudok, ha olyan leheletfelhőket csinálnék, mint te, egész nap itt fent maradnék.'::text),
(336396,37378,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine perfekte weiße Atemwolke ... in die eiskalte Luft geblasen. Wirklich bahnbrechende Wissenschaft.'::text,'wurde'::text,'blies'::text,'wird'::text,'Eine perfekte weiße Atemwolke wurde in die eiskalte Luft geblasen. Wirklich bahnbrechende Wissenschaft.'::text),
(336400,37378,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ідеальну білу хмару подиху ... в морозне повітря. Справді революційна наука.'::text,'видихнули'::text,'видихнула'::text,'видихають'::text,'Ідеальну білу хмару подиху видихнули в морозне повітря. Справді революційна наука.'::text),
(336399,37378,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una perfecta nube blanca de aliento ... al aire helado. Ciencia realmente revolucionaria.'::text,'fue soltada'::text,'soltó'::text,'es soltada'::text,'Una perfecta nube blanca de aliento fue soltada al aire helado. Ciencia realmente revolucionaria.'::text),
(336398,37378,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un parfait nuage blanc de souffle ... dans l''air glacial. Une science vraiment révolutionnaire.'::text,'a été soufflé'::text,'a soufflé'::text,'est soufflé'::text,'Un parfait nuage blanc de souffle a été soufflé dans l''air glacial. Une science vraiment révolutionnaire.'::text),
(336401,37378,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dondurucu havaya kusursuz beyaz bir nefes bulutu ..., gerçekten çığır açan bir bilim.'::text,'üflendi'::text,'üfledi'::text,'üfleniyor'::text,'Dondurucu havaya kusursuz beyaz bir nefes bulutu üflendi, gerçekten çığır açan bir bilim.'::text),
(336402,37378,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy tökéletes fehér leheletfelhő ... a fagyos levegőbe. Igazán úttörő tudomány.'::text,'lett kifújva'::text,'fújt'::text,'van kifújva'::text,'Egy tökéletes fehér leheletfelhő lett kifújva a fagyos levegőbe. Igazán úttörő tudomány.'::text),
(336405,37379,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die anderen Wanderer ... denselben Atemtrick. Wie originell.'::text,'kopierten'::text,'wurden kopiert'::text,'kopierend'::text,'Die anderen Wanderer kopierten denselben Atemtrick. Wie originell.'::text),
(336409,37379,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Інші туристи ... той самий трюк із подихом. Як оригінально.'::text,'скопіювали'::text,'були скопійовані'::text,'копіюючи'::text,'Інші туристи скопіювали той самий трюк із подихом. Як оригінально.'::text),
(336408,37379,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los demás senderistas ... el mismo truco del aliento. Qué original.'::text,'copiaron'::text,'fueron copiados'::text,'copiando'::text,'Los demás senderistas copiaron el mismo truco del aliento. Qué original.'::text),
(336407,37379,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les autres randonneurs ... le même tour de souffle. Très original.'::text,'ont copié'::text,'ont été copiés'::text,'copiant'::text,'Les autres randonneurs ont copié le même tour de souffle. Très original.'::text),
(336410,37379,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diğer yürüyüşçüler aynı nefes numarasını ..., ne kadar orijinal.'::text,'kopyaladı'::text,'kopyalandı'::text,'kopyalayan'::text,'Diğer yürüyüşçüler aynı nefes numarasını kopyaladı, ne kadar orijinal.'::text),
(336411,37379,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A többi túrázó ... ugyanazt a leheletes trükköt. Milyen eredeti.'::text,'lemásolta'::text,'le lett másolva'::text,'lemásolva'::text,'A többi túrázó lemásolta ugyanazt a leheletes trükköt. Milyen eredeti.'::text),
(336414,37380,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Atem wird weiß, also ... es da oben leicht frisch sein.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Ihr Atem wird weiß, also muss es da oben leicht frisch sein.'::text),
(336418,37380,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її подих біліє, тож там нагорі ... бути трохи прохолодно.'::text,'мусить'::text,'не може'::text,'має'::text,'Її подих біліє, тож там нагорі мусить бути трохи прохолодно.'::text),
(336417,37380,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su aliento se vuelve blanco, así que ahí arriba ... hacer un poco de fresco.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Su aliento se vuelve blanco, así que ahí arriba debe de hacer un poco de fresco.'::text),
(336416,37380,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son souffle devient blanc, donc il ... faire un peu frais là-haut.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Son souffle devient blanc, donc il doit faire un peu frais là-haut.'::text),
(336419,37380,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nefesi beyazlıyor, demek orası biraz serin ...'::text,'olmalı'::text,'olamaz'::text,'olması lazım'::text,'Nefesi beyazlıyor, demek orası biraz serin olmalı.'::text),
(336420,37380,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lehelete fehér, szóval ott fent ... egy kicsit hűvös van.'::text,'biztosan'::text,'nem lehet, hogy'::text,'elvileg'::text,'A lehelete fehér, szóval ott fent biztosan egy kicsit hűvös van.'::text),
(372981,41443,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine Mama verspricht, dass sie heute Abend einen Flicken auf das neue Loch ...'::text,'nähen wird'::text,'am Nähen sein wird'::text,'näht'::text,'Seine Mama verspricht, dass sie heute Abend einen Flicken auf das neue Loch nähen wird.'::text),
(372985,41443,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його мама обіцяє, що сьогодні ввечері ... латку на нову дірку.'::text,'пришиє'::text,'пришиватиме'::text,'пришиває'::text,'Його мама обіцяє, що сьогодні ввечері пришиє латку на нову дірку.'::text),
(372984,41443,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su madre promete que esta noche ... un parche sobre el agujero nuevo.'::text,'coserá'::text,'estará cosiendo'::text,'cose'::text,'Su madre promete que esta noche coserá un parche sobre el agujero nuevo.'::text),
(372983,41443,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa mère promet qu''elle ... une pièce sur le nouveau trou ce soir.'::text,'coudra'::text,'sera en train de coudre'::text,'coud'::text,'Sa mère promet qu''elle coudra une pièce sur le nouveau trou ce soir.'::text),
(372986,41443,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Annesi bu akşam yeni deliğin üstüne bir yama ... söz veriyor.'::text,'dikeceğine'::text,'dikiyor olacağına'::text,'diktiğine'::text,'Annesi bu akşam yeni deliğin üstüne bir yama dikeceğine söz veriyor.'::text),
(372987,41443,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az anyukája megígéri, hogy ma este ... egy foltot az új lyukra.'::text,'felvarr'::text,'varrni fog'::text,'varr'::text,'Az anyukája megígéri, hogy ma este felvarr egy foltot az új lyukra.'::text),
(397056,44118,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie kippte den Eimer mit Äpfeln um, und ...'::text,'der Mann am Strand auch'::text,'der Mann am Strand auch'::text,'der Mann am Strand auch nicht'::text,'Sie kippte den Eimer mit Äpfeln um, und der Mann am Strand auch.'::text),
(397060,44118,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона перекинула відро з яблуками, і ...'::text,'чоловік на пляжі теж'::text,'чоловік на пляжі теж'::text,'чоловік на пляжі теж ні'::text,'Вона перекинула відро з яблуками, і чоловік на пляжі теж.'::text),
(397059,44118,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Volcó el cubo de manzanas, y ...'::text,'el hombre de la playa también'::text,'el hombre de la playa también'::text,'el hombre de la playa tampoco'::text,'Volcó el cubo de manzanas, y el hombre de la playa también.'::text),
(397058,44118,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a renversé le seau de pommes, et ...'::text,'l''homme sur la plage aussi'::text,'l''homme sur la plage aussi'::text,'l''homme sur la plage non plus'::text,'Elle a renversé le seau de pommes, et l''homme sur la plage aussi.'::text),
(397061,44118,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elma kovasını devirdi, ...'::text,'sahildeki adam da öyle'::text,'sahildeki adam da öyle'::text,'sahildeki adam da devirmedi'::text,'Elma kovasını devirdi, sahildeki adam da öyle.'::text),
(397062,44118,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felborította az almás vödröt, és ...'::text,'a strandon álló férfi is'::text,'a strandon álló férfi is'::text,'a strandon álló férfi sem'::text,'Felborította az almás vödröt, és a strandon álló férfi is.'::text),
(397074,44120,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte sie den Eimer nicht so weit gekippt, ... die Äpfel nicht über den ganzen Tisch gerollt.'::text,'wären'::text,'werden'::text,'sind'::text,'Hätte sie den Eimer nicht so weit gekippt, wären die Äpfel nicht über den ganzen Tisch gerollt.'::text),
(397078,44120,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не нахилила відро так сильно, яблука ... по всьому столу.'::text,'не розкотилися б'::text,'не розкотяться'::text,'не розкотилися'::text,'Якби вона не нахилила відро так сильно, яблука не розкотилися б по всьому столу.'::text),
(397077,44120,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera inclinado tanto el cubo, las manzanas no ... por toda la mesa.'::text,'habrían rodado'::text,'rodarán'::text,'rodaron'::text,'Si no hubiera inclinado tanto el cubo, las manzanas no habrían rodado por toda la mesa.'::text),
(397076,44120,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle n''avait pas autant penché le seau, les pommes ... sur toute la table.'::text,'n''auraient pas roulé'::text,'ne rouleront pas'::text,'n''ont pas roulé'::text,'Si elle n''avait pas autant penché le seau, les pommes n''auraient pas roulé sur toute la table.'::text),
(397079,44120,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kovayı o kadar eğmeseydi elmalar bütün masaya ...'::text,'yuvarlanmazdı'::text,'yuvarlanmayacak'::text,'yuvarlanmadı'::text,'Kovayı o kadar eğmeseydi elmalar bütün masaya yuvarlanmazdı.'::text),
(397080,44120,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem döntötte volna meg ennyire a vödröt, az almák nem ... szét az egész asztalon.'::text,'gurultak volna'::text,'fognak gurulni'::text,'gurultak'::text,'Ha nem döntötte volna meg ennyire a vödröt, az almák nem gurultak volna szét az egész asztalon.'::text),
(397083,44121,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau bestritt, den Eimer zu weit ..., obwohl die Äpfel etwas anderes nahelegen.'::text,'gekippt zu haben'::text,'zu kippen'::text,'kippte'::text,'Die Frau bestritt, den Eimer zu weit gekippt zu haben, obwohl die Äpfel etwas anderes nahelegen.'::text),
(397087,44121,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка заперечила, що ... відро надто сильно, хоча яблука свідчать про інше.'::text,'нахилила'::text,'нахилить'::text,'нахилила'::text,'Жінка заперечила, що нахилила відро надто сильно, хоча яблука свідчать про інше.'::text),
(397086,44121,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer negó ... el cubo demasiado, aunque las manzanas indican lo contrario.'::text,'haber inclinado'::text,'inclinar'::text,'inclinó'::text,'La mujer negó haber inclinado el cubo demasiado, aunque las manzanas indican lo contrario.'::text),
(397085,44121,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme a nié ... trop le seau, bien que les pommes indiquent le contraire.'::text,'avoir penché'::text,'pencher'::text,'a penché'::text,'La femme a nié avoir penché trop le seau, bien que les pommes indiquent le contraire.'::text),
(397088,44121,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadın kovayı fazla ... inkâr etti, ancak elmalar aksini gösteriyor.'::text,'eğdiğini'::text,'eğmeyi'::text,'eğdi'::text,'Kadın kovayı fazla eğdiğini inkâr etti, ancak elmalar aksini gösteriyor.'::text),
(397089,44121,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő tagadta, hogy túlságosan ... a vödröt, bár az almák mást mutatnak.'::text,'megdöntötte'::text,'megdönteni'::text,'megdöntötte'::text,'A nő tagadta, hogy túlságosan megdöntötte a vödröt, bár az almák mást mutatnak.'::text),
(397092,44122,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hätte den Eimer nicht so weit ...; jetzt sind die Äpfel überall, eine totale Katastrophe!'::text,'kippen sollen'::text,'kippen dürfen'::text,'kippen können'::text,'Sie hätte den Eimer nicht so weit kippen sollen; jetzt sind die Äpfel überall, eine totale Katastrophe!'::text),
(397096,44122,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їй ... так сильно нахиляти відро; тепер яблука всюди, повна катастрофа!'::text,'не варто було'::text,'не можна було'::text,'не вдалося'::text,'Їй не варто було так сильно нахиляти відро; тепер яблука всюди, повна катастрофа!'::text),
(397095,44122,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... inclinado tanto el cubo; ahora hay manzanas por todas partes, un desastre total!'::text,'no debería haber'::text,'no debía haber'::text,'no pudo haber'::text,'¡Ella no debería haber inclinado tanto el cubo; ahora hay manzanas por todas partes, un desastre total!'::text),
(397094,44122,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... pencher le seau autant ; maintenant il y a des pommes partout, une catastrophe totale !'::text,'n''aurait pas dû'::text,'n''aurait pas dû'::text,'n''a pas pu'::text,'Elle n''aurait pas dû pencher le seau autant ; maintenant il y a des pommes partout, une catastrophe totale !'::text),
(397097,44122,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kovayı o kadar ...; şimdi elmalar her yerde, tam bir felaket!'::text,'eğmemeliydi'::text,'eğmemiş olmalı'::text,'eğemedi'::text,'Kovayı o kadar eğmemeliydi; şimdi elmalar her yerde, tam bir felaket!'::text),
(397098,44122,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem ... ennyire megdönteni a vödröt; most mindenhol almák vannak, totális katasztrófa!'::text,'kellett volna'::text,'szabadott volna'::text,'tudta'::text,'Nem kellett volna ennyire megdönteni a vödröt; most mindenhol almák vannak, totális katasztrófa!'::text),
(397101,44123,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ließ ihre Freundin den Eimer ..., und es folgte totales Chaos!'::text,'kippen'::text,'zu kippen'::text,'gekippt'::text,'Sie ließ ihre Freundin den Eimer kippen, und es folgte totales Chaos!'::text),
(397105,44123,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона попросила подругу ... відро, і почався повний хаос!'::text,'перекинути'::text,'перекинути'::text,'перекинула'::text,'Вона попросила подругу перекинути відро, і почався повний хаос!'::text),
(397104,44123,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Hizo que su amiga ... el cubo, y siguió un caos total!'::text,'volcara'::text,'volcar'::text,'volcó'::text,'¡Hizo que su amiga volcara el cubo, y siguió un caos total!'::text),
(397103,44123,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a fait ... le seau à son amie, et le chaos total a suivi !'::text,'renverser'::text,'renverser'::text,'renversé'::text,'Elle a fait renverser le seau à son amie, et le chaos total a suivi !'::text),
(397106,44123,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşına kovayı ... ve ardından tam bir kaos çıktı!'::text,'devirtti'::text,'devirmesini'::text,'devirdi'::text,'Arkadaşına kovayı devirtti ve ardından tam bir kaos çıktı!'::text),
(397107,44123,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megkérte a barátnőjét, hogy ... fel a vödröt, és totális káosz lett belőle!'::text,'borítsa'::text,'borítani'::text,'borította'::text,'Megkérte a barátnőjét, hogy borítsa fel a vödröt, és totális káosz lett belőle!'::text),
(397110,44124,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wünschte, sie hätte den Eimer nicht so weit ..., die Äpfel sind für immer ruiniert!'::text,'gekippt'::text,'kippte'::text,'kippen würde'::text,'Sie wünschte, sie hätte den Eimer nicht so weit gekippt, die Äpfel sind für immer ruiniert!'::text),
(397114,44124,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона шкодує, що ... відро так сильно, яблука зіпсовані назавжди!'::text,'нахилила'::text,'нахиляє'::text,'нахилить'::text,'Вона шкодує, що нахилила відро так сильно, яблука зіпсовані назавжди!'::text),
(397113,44124,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ojalá ella no ... tanto el cubo, las manzanas están arruinadas para siempre!'::text,'hubiera inclinado'::text,'inclinara'::text,'inclinaría'::text,'¡Ojalá ella no hubiera inclinado tanto el cubo, las manzanas están arruinadas para siempre!'::text),
(397112,44124,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle aimerait ne pas ... le seau autant, les pommes sont fichues pour toujours !'::text,'avoir penché'::text,'pencher'::text,'pencher'::text,'Elle aimerait ne pas avoir penché le seau autant, les pommes sont fichues pour toujours !'::text),
(397115,44124,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke kovayı o kadar ... diyor, elmalar sonsuza dek mahvoldu!'::text,'eğmeseydim'::text,'eğmesem'::text,'eğmezdim'::text,'Keşke kovayı o kadar eğmeseydim diyor, elmalar sonsuza dek mahvoldu!'::text),
(397116,44124,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bárcsak ne ... meg ennyire a vödröt, az almák örökre tönkrementek!'::text,'döntötte volna'::text,'döntené'::text,'döntené'::text,'Bárcsak ne döntötte volna meg ennyire a vödröt, az almák örökre tönkrementek!'::text),
(397119,44125,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, anscheinend hat die Frau, ... die Äpfel ausgekippt hat, gerade einen gegessen.'::text,'die'::text,'deren'::text,'welche'::text,'Hör mal, anscheinend hat die Frau, die die Äpfel ausgekippt hat, gerade einen gegessen.'::text),
(397123,44125,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, жінка, ... висипала ті яблука, щойно одне з''їла.'::text,'яка'::text,'чия'::text,'котра'::text,'Слухай, кажуть, жінка, яка висипала ті яблука, щойно одне з''їла.'::text),
(397122,44125,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer la mujer ... volcó esas manzanas acaba de comerse una.'::text,'que'::text,'cuya'::text,'la cual'::text,'Oye, al parecer la mujer que volcó esas manzanas acaba de comerse una.'::text),
(397121,44125,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment la femme ... a renversé ces pommes vient d''en manger une.'::text,'qui'::text,'dont'::text,'que'::text,'Écoute, apparemment la femme qui a renversé ces pommes vient d''en manger une.'::text),
(397124,44125,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, anlaşılan o elmaları ... kadın az önce bir tane yedi.'::text,'döken'::text,'döktüğü'::text,'döken'::text,'Dinle, anlaşılan o elmaları döken kadın az önce bir tane yedi.'::text),
(397125,44125,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag a nő, ... kiborította azokat az almákat, épp megevett egyet.'::text,'aki'::text,'akinek'::text,'ami'::text,'Figyelj, állítólag a nő, aki kiborította azokat az almákat, épp megevett egyet.'::text),
(397128,44126,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie kippte den Eimer langsam, ... die Äpfel herausfielen.'::text,'damit'::text,'um'::text,'im Falle'::text,'Sie kippte den Eimer langsam, damit die Äpfel herausfielen.'::text),
(397132,44126,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона повільно нахилила відро, ... яблука випали.'::text,'щоб'::text,'щоб'::text,'на випадок'::text,'Вона повільно нахилила відро, щоб яблука випали.'::text),
(397131,44126,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Inclinó el cubo despacio ... las manzanas cayeran.'::text,'para que'::text,'para'::text,'en caso de'::text,'Inclinó el cubo despacio para que las manzanas cayeran.'::text),
(397130,44126,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a penché le seau lentement ... les pommes tombent.'::text,'pour que'::text,'pour'::text,'en cas de'::text,'Elle a penché le seau lentement pour que les pommes tombent.'::text),
(397133,44126,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elmalar dışarı düşsün ... kovayı yavaşça eğdi.'::text,'diye'::text,'için'::text,'durumunda'::text,'Elmalar dışarı düşsün diye kovayı yavaşça eğdi.'::text),
(397134,44126,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lassan döntötte meg a vödröt, ... kiessenek az almák.'::text,'hogy'::text,'azért, hogy'::text,'arra az esetre'::text,'Lassan döntötte meg a vödröt, hogy kiessenek az almák.'::text),
(397137,44127,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Warte, ich hab gehört, morgen um diese Zeit ... er wieder Eimer an dem Strand auskippen.'::text,'wird'::text,'wird'::text,'kippt'::text,'Warte, ich hab gehört, morgen um diese Zeit wird er wieder Eimer an dem Strand auskippen.'::text),
(397141,44127,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стривай, я чув, що завтра в цей час він знову ... відра на тому пляжі.'::text,'перекидатиме'::text,'перекине'::text,'перекидає'::text,'Стривай, я чув, що завтра в цей час він знову перекидатиме відра на тому пляжі.'::text),
(397140,44127,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, he oído que mañana a esta hora él ... cubos otra vez en esa playa.'::text,'estará volcando'::text,'volcará'::text,'vuelca'::text,'Espera, he oído que mañana a esta hora él estará volcando cubos otra vez en esa playa.'::text),
(397139,44127,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, il paraît que demain à cette heure-ci il ... encore des seaux sur cette plage.'::text,'sera en train de renverser'::text,'renversera'::text,'renverse'::text,'Attends, il paraît que demain à cette heure-ci il sera en train de renverser encore des seaux sur cette plage.'::text),
(397142,44127,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur, duydum ki yarın bu saatte o sahilde yine kova ...'::text,'deviriyor olacak'::text,'devirecek'::text,'deviriyor'::text,'Dur, duydum ki yarın bu saatte o sahilde yine kova deviriyor olacak.'::text),
(397143,44127,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, azt hallottam, hogy holnap ilyenkor megint vödröket ... azon a strandon.'::text,'fog borogatni'::text,'borít majd'::text,'borogat'::text,'Várj, azt hallottam, hogy holnap ilyenkor megint vödröket fog borogatni azon a strandon.'::text),
(344730,38304,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau, ... über dem Feuer hockt, legt Stöcke in die Flammen.'::text,'die'::text,'die'::text,'deren'::text,'Die Frau, die über dem Feuer hockt, legt Stöcke in die Flammen.'::text),
(344734,38304,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка, ... присіла над вогнем, підкладає палички у вогонь.'::text,'яка'::text,'яка'::text,'чия'::text,'Жінка, яка присіла над вогнем, підкладає палички у вогонь.'::text),
(344733,38304,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer ... está agachada junto al fuego echa palitos a las llamas.'::text,'que'::text,'que'::text,'cuya'::text,'La mujer que está agachada junto al fuego echa palitos a las llamas.'::text),
(344732,38304,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme ... est accroupie au-dessus du feu met des bâtons dans les flammes.'::text,'qui'::text,'qui'::text,'dont'::text,'La femme qui est accroupie au-dessus du feu met des bâtons dans les flammes.'::text),
(344735,38304,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ateşin üzerine ... kadın alevlere çubuk atıyor.'::text,'çömelmiş'::text,'çömelmiş'::text,'çömeldiği'::text,'Ateşin üzerine çömelmiş kadın alevlere çubuk atıyor.'::text),
(344736,38304,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő, ... a tűz fölé guggol, gallyakat rak a lángokba.'::text,'aki'::text,'ami'::text,'akinek'::text,'A nő, aki a tűz fölé guggol, gallyakat rak a lángokba.'::text),
(344739,38305,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du hockst wie ein Profi. Ich wette, früher ... du jeden Sommer Strandfeuer.'::text,'machtest'::text,'machtest'::text,'warst es gewohnt zu machen'::text,'Ehrlich, du hockst wie ein Profi. Ich wette, früher machtest du jeden Sommer Strandfeuer.'::text),
(344743,38305,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти присідаєш як профі. Б''юся об заклад, ти ... багаття на пляжі щоліта.'::text,'раніше розпалювала'::text,'раніше розпалювала'::text,'звикла розпалювати'::text,'Чесно, ти присідаєш як профі. Б''юся об заклад, ти раніше розпалювала багаття на пляжі щоліта.'::text),
(344742,38305,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, te agachas como una pro. Seguro que ... hacer hogueras en la playa cada verano.'::text,'solías'::text,'solías'::text,'estabas acostumbrada a'::text,'La verdad, te agachas como una pro. Seguro que solías hacer hogueras en la playa cada verano.'::text),
(344741,38305,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu t''accroupis comme une pro. Je parie qu''avant tu ... des feux sur la plage chaque été.'::text,'faisais'::text,'faisais'::text,'avais l''habitude de faire'::text,'Franchement, tu t''accroupis comme une pro. Je parie qu''avant tu faisais des feux sur la plage chaque été.'::text),
(344744,38305,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası profesyonel gibi çömeliyorsun. Bahse girerim eskiden her yaz sahilde ateş ...'::text,'yakardın'::text,'yakardın'::text,'yakmaya alışkındın'::text,'Açıkçası profesyonel gibi çömeliyorsun. Bahse girerim eskiden her yaz sahilde ateş yakardın.'::text),
(344745,38305,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, úgy guggolsz, mint egy profi. Fogadok, hogy régen minden nyáron ... tüzet a strandon.'::text,'raktál'::text,'raktál'::text,'hozzá voltál szokva rakni'::text,'Őszintén, úgy guggolsz, mint egy profi. Fogadok, hogy régen minden nyáron raktál tüzet a strandon.'::text),
(344748,38306,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... in einer Jeansjacke immer weiter über dem Feuer. Makelloser Sicherheitsplan.'::text,'hockt'::text,'hockt'::text,'hockt'::text,'Sie hockt in einer Jeansjacke immer weiter über dem Feuer. Makelloser Sicherheitsplan.'::text),
(344752,38306,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона й далі ... над вогнем у джинсовій куртці. Бездоганний план безпеки.'::text,'сидить навпочіпки'::text,'сидіти навпочіпки'::text,'сидіти навпочіпки'::text,'Вона й далі сидить навпочіпки над вогнем у джинсовій куртці. Бездоганний план безпеки.'::text),
(344751,38306,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella sigue ... sobre el fuego con una chaqueta vaquera. Plan de seguridad impecable.'::text,'agachada'::text,'agacharse'::text,'agacharse'::text,'Ella sigue agachada sobre el fuego con una chaqueta vaquera. Plan de seguridad impecable.'::text),
(344750,38306,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle continue de ... au-dessus du feu en veste en jean. Plan de sécurité impeccable.'::text,'s''accroupir'::text,'s''accroupir'::text,'s''accroupir'::text,'Elle continue de s''accroupir au-dessus du feu en veste en jean. Plan de sécurité impeccable.'::text),
(344753,38306,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kot ceketle ateşin üzerine ... devam ediyor. Kusursuz güvenlik planı.'::text,'çömelmeye'::text,'çömelmeye'::text,'çömel'::text,'Kot ceketle ateşin üzerine çömelmeye devam ediyor. Kusursuz güvenlik planı.'::text),
(344754,38306,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Farmerdzsekiben tovább ... a tűz fölött. Hibátlan biztonsági terv.'::text,'guggol'::text,'guggolni'::text,'guggol'::text,'Farmerdzsekiben tovább guggol a tűz fölött. Hibátlan biztonsági terv.'::text),
(344766,38308,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Natürlich hockte sie den ganzen Abend am Feuer, und ...'::text,'die zwei Leute am Ufer auch'::text,'die zwei Leute am Ufer auch'::text,'die zwei Leute am Ufer auch'::text,'Natürlich hockte sie den ganzen Abend am Feuer, und die zwei Leute am Ufer auch.'::text),
(344770,38308,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, вона цілий вечір сиділа навпочіпки біля вогню, і ...'::text,'ті двоє людей на березі теж'::text,'ті двоє людей на березі теж'::text,'ті двоє людей на березі теж'::text,'Звісно, вона цілий вечір сиділа навпочіпки біля вогню, і ті двоє людей на березі теж.'::text),
(344769,38308,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente se agachó junto al fuego toda la tarde, y ...'::text,'las dos personas de la orilla también'::text,'las dos personas de la orilla también'::text,'las dos personas de la orilla también'::text,'Obviamente se agachó junto al fuego toda la tarde, y las dos personas de la orilla también.'::text),
(344768,38308,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment, elle est restée accroupie près du feu toute la soirée, et ...'::text,'les deux personnes sur le rivage aussi'::text,'les deux personnes sur le rivage aussi'::text,'les deux personnes sur le rivage aussi'::text,'Évidemment, elle est restée accroupie près du feu toute la soirée, et les deux personnes sur le rivage aussi.'::text),
(344771,38308,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabii ki bütün akşam ateşin yanında çömeldi, ...'::text,'kıyıdaki iki kişi de öyle'::text,'kıyıdaki iki kişi de öyle'::text,'kıyıdaki iki kişi de öyle'::text,'Tabii ki bütün akşam ateşin yanında çömeldi, kıyıdaki iki kişi de öyle.'::text),
(344772,38308,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván egész este a tűz mellett guggolt, és ...'::text,'a két ember a parton is'::text,'a két ember a parton is'::text,'a két ember a parton is'::text,'Nyilván egész este a tűz mellett guggolt, és a két ember a parton is.'::text),
(344784,38310,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Um Mitternacht ... sie seit sechs Stunden an diesem Feuer. Die schlimmste Nacht überhaupt!'::text,'hockt'::text,'wird hocken'::text,'wird hocken'::text,'Um Mitternacht hockt sie seit sechs Stunden an diesem Feuer. Die schlimmste Nacht überhaupt!'::text),
(344788,38310,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До півночі вона ... біля цього вогню шість годин. Найгірша ніч у житті!'::text,'просидить навпочіпки'::text,'сидітиме навпочіпки'::text,'сидітиме навпочіпки'::text,'До півночі вона просидить навпочіпки біля цього вогню шість годин. Найгірша ніч у житті!'::text),
(344787,38310,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para medianoche, ella ... seis horas agachada junto a este fuego. ¡La peor noche de la historia!'::text,'habrá pasado'::text,'pasará'::text,'estará pasando'::text,'Para medianoche, ella habrá pasado seis horas agachada junto a este fuego. ¡La peor noche de la historia!'::text),
(344786,38310,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici minuit, elle ... accroupie six heures près de ce feu. La pire nuit de sa vie !'::text,'sera restée'::text,'restera'::text,'restera'::text,'D''ici minuit, elle sera restée accroupie six heures près de ce feu. La pire nuit de sa vie !'::text),
(344789,38310,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gece yarısına kadar bu ateşin başında altı saat ..., tüm zamanların en kötü gecesi!'::text,'çömelmiş olacak'::text,'çömelecek'::text,'çömeliyor olacak'::text,'Gece yarısına kadar bu ateşin başında altı saat çömelmiş olacak, tüm zamanların en kötü gecesi!'::text),
(344790,38310,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éjfélre már hat órája ... ennél a tűznél. A valaha volt legrosszabb éjszaka!'::text,'fog guggolni'::text,'guggol majd'::text,'fog guggolni'::text,'Éjfélre már hat órája fog guggolni ennél a tűznél. A valaha volt legrosszabb éjszaka!'::text),
(344793,38311,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, bei Sonnenaufgang ... sie anscheinend schon zehn ganze Stunden an dem Feuer.'::text,'hockt'::text,'wird hocken'::text,'wird gehockt haben'::text,'Rate mal, bei Sonnenaufgang hockt sie anscheinend schon zehn ganze Stunden an dem Feuer.'::text),
(344797,38311,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, кажуть, до світанку вона ... біля того вогню цілих десять годин.'::text,'сидітиме навпочіпки'::text,'сидітиме навпочіпки'::text,'просидить навпочіпки'::text,'Уяви, кажуть, до світанку вона сидітиме навпочіпки біля того вогню цілих десять годин.'::text),
(344796,38311,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina, al parecer, al amanecer ella ... diez horas enteras agachada junto a ese fuego.'::text,'llevará'::text,'estará'::text,'habrá pasado'::text,'Adivina, al parecer, al amanecer ella llevará diez horas enteras agachada junto a ese fuego.'::text),
(344795,38311,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, apparemment au lever du soleil, elle ... accroupie près de ce feu depuis dix heures entières.'::text,'sera'::text,'sera'::text,'aura été'::text,'Devine quoi, apparemment au lever du soleil, elle sera accroupie près de ce feu depuis dix heures entières.'::text),
(344798,38311,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, anlaşılan gün doğana kadar o ateşin başında tam on saattir ...'::text,'çömeliyor olacak'::text,'çömeliyor olacak'::text,'çömelmiş olacak'::text,'Bil bakalım, anlaşılan gün doğana kadar o ateşin başında tam on saattir çömeliyor olacak.'::text),
(344799,38311,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, állítólag napkeltére már tíz teljes órája ... annál a tűznél.'::text,'fog guggolni'::text,'fog guggolni'::text,'guggolt majd'::text,'Képzeld, állítólag napkeltére már tíz teljes órája fog guggolni annál a tűznél.'::text),
(344802,38312,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte sie sich nicht so nah hingehockt, ... sie die Stöcke nicht in die Mitte des Feuers legen können.'::text,'hätte'::text,'kann'::text,'legte'::text,'Hätte sie sich nicht so nah hingehockt, hätte sie die Stöcke nicht in die Mitte des Feuers legen können.'::text),
(344806,38312,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не присіла так близько, вона ... палички в середину вогню.'::text,'не змогла б підкласти'::text,'не може підкласти'::text,'не підклала'::text,'Якби вона не присіла так близько, вона не змогла б підкласти палички в середину вогню.'::text),
(344805,38312,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no se hubiera agachado tan cerca, ella ... los palitos en medio del fuego.'::text,'no habría podido echar'::text,'no puede echar'::text,'no echó'::text,'Si no se hubiera agachado tan cerca, ella no habría podido echar los palitos en medio del fuego.'::text),
(344804,38312,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle ne s''était pas accroupie si près, elle ... les bâtons au milieu du feu.'::text,'n''aurait pas pu mettre'::text,'ne peut pas mettre'::text,'n''a pas mis'::text,'Si elle ne s''était pas accroupie si près, elle n''aurait pas pu mettre les bâtons au milieu du feu.'::text),
(344807,38312,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu kadar yakına çömelmeseydi çubukları ateşin ortasına ...'::text,'atamazdı'::text,'atamaz'::text,'atmadı'::text,'Bu kadar yakına çömelmeseydi çubukları ateşin ortasına atamazdı.'::text),
(344808,38312,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem guggolt volna ilyen közel, nem ... a gallyakat a tűz közepébe.'::text,'tudta volna betenni'::text,'tudja betenni'::text,'tette be'::text,'Ha nem guggolt volna ilyen közel, nem tudta volna betenni a gallyakat a tűz közepébe.'::text),
(344811,38313,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte sie sich nicht hingehockt, um es zu schüren, würde das Feuer jetzt nicht so hell ...'::text,'brennen'::text,'gebrannt haben'::text,'brennen'::text,'Hätte sie sich nicht hingehockt, um es zu schüren, würde das Feuer jetzt nicht so hell brennen.'::text),
(344815,38313,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не присіла, щоб підживити його, вогонь зараз ... так яскраво.'::text,'не горів би'::text,'не горів би'::text,'не горітиме'::text,'Якби вона не присіла, щоб підживити його, вогонь зараз не горів би так яскраво.'::text),
(344814,38313,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no se hubiera agachado para avivarlo, el fuego no ... tan fuerte ahora.'::text,'estaría ardiendo'::text,'habría ardido'::text,'arderá'::text,'Si no se hubiera agachado para avivarlo, el fuego no estaría ardiendo tan fuerte ahora.'::text),
(344813,38313,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle ne s''était pas accroupie pour l''alimenter, le feu ne ... pas aussi fort maintenant.'::text,'brûlerait'::text,'aurait brûlé'::text,'brûlera'::text,'Si elle ne s''était pas accroupie pour l''alimenter, le feu ne brûlerait pas aussi fort maintenant.'::text),
(344816,38313,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onu beslemek için çömelmeseydi ateş şimdi bu kadar parlak ...'::text,'yanmıyor olurdu'::text,'yanmazdı'::text,'yanmayacak'::text,'Onu beslemek için çömelmeseydi ateş şimdi bu kadar parlak yanmıyor olurdu.'::text),
(344817,38313,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem guggolt volna le, hogy táplálja, a tűz most nem ... ilyen fényesen.'::text,'égne'::text,'égett volna'::text,'fog égni'::text,'Ha nem guggolt volna le, hogy táplálja, a tűz most nem égne ilyen fényesen.'::text),
(344820,38314,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie soll schon oft über solchen Strandfeuern ...'::text,'gehockt haben'::text,'hocken'::text,'hockend'::text,'Sie soll schon oft über solchen Strandfeuern gehockt haben.'::text),
(344824,38314,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважають, що вона вже багато разів ... над такими пляжними вогнищами.'::text,'сиділа навпочіпки'::text,'сидить навпочіпки'::text,'сидячи навпочіпки'::text,'Вважають, що вона вже багато разів сиділа навпочіпки над такими пляжними вогнищами.'::text),
(344823,38314,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que ella ... junto a hogueras de playa como esta muchas veces antes.'::text,'se ha agachado'::text,'se agacha'::text,'agachándose'::text,'Se cree que ella se ha agachado junto a hogueras de playa como esta muchas veces antes.'::text),
(344822,38314,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense qu''elle ... au-dessus de feux de plage comme celui-ci de nombreuses fois auparavant.'::text,'s''est accroupie'::text,'s''accroupit'::text,'s''accroupissant'::text,'On pense qu''elle s''est accroupie au-dessus de feux de plage comme celui-ci de nombreuses fois auparavant.'::text),
(344825,38314,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha önce de bu tür sahil ateşlerinin başında defalarca ... düşünülüyor.'::text,'çömeldiği'::text,'çömeldiği'::text,'çömelerek'::text,'Daha önce de bu tür sahil ateşlerinin başında defalarca çömeldiği düşünülüyor.'::text),
(344826,38314,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy tartják, hogy korábban már sokszor ... ilyen tengerparti tüzek fölött.'::text,'guggolt'::text,'guggol'::text,'guggolva'::text,'Úgy tartják, hogy korábban már sokszor guggolt ilyen tengerparti tüzek fölött.'::text),
(347871,38653,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er bestritt, das Küchendesaster ...; der rauchende Toast sieht das natürlich anders.'::text,'verursacht zu haben'::text,'zu verursachen'::text,'verursachte'::text,'Er bestritt, das Küchendesaster verursacht zu haben; der rauchende Toast sieht das natürlich anders.'::text),
(347875,38653,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він заперечив, що ... кухонну катастрофу. Димний тост, звісно, не погоджується.'::text,'спричинив'::text,'спричинити'::text,'спричинив'::text,'Він заперечив, що спричинив кухонну катастрофу. Димний тост, звісно, не погоджується.'::text),
(347874,38653,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Negó ... el desastre de la cocina. La tostada humeante no está de acuerdo, obviamente.'::text,'haber causado'::text,'causar'::text,'causó'::text,'Negó haber causado el desastre de la cocina. La tostada humeante no está de acuerdo, obviamente.'::text),
(347873,38653,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a nié ... la catastrophe en cuisine. Le toast qui fume n''est pas d''accord, évidemment.'::text,'avoir causé'::text,'causer'::text,'a causé'::text,'Il a nié avoir causé la catastrophe en cuisine. Le toast qui fume n''est pas d''accord, évidemment.'::text),
(347876,38653,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mutfak felaketine ... inkâr etti. Duman çıkaran tost buna katılmıyor tabii.'::text,'sebep olduğunu'::text,'sebep olmayı'::text,'sebep oldu'::text,'Mutfak felaketine sebep olduğunu inkâr etti. Duman çıkaran tost buna katılmıyor tabii.'::text),
(347877,38653,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tagadta, hogy ő ... a konyhai katasztrófát. A füstölgő pirítós persze nem ért egyet.'::text,'okozta'::text,'okozni'::text,'okozta'::text,'Tagadta, hogy ő okozta a konyhai katasztrófát. A füstölgő pirítós persze nem ért egyet.'::text),
(347880,38654,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hätte das Hähnchen nicht so lange im Ofen ...; eine kleine Katastrophe, echt.'::text,'lassen sollen'::text,'lassen dürfen'::text,'lassen können'::text,'Er hätte das Hähnchen nicht so lange im Ofen lassen sollen; eine kleine Katastrophe, echt.'::text),
(347884,38654,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йому ... залишати курку в духовці так довго. Невелика катастрофа, справді.'::text,'не варто було'::text,'не можна було'::text,'не вдалося'::text,'Йому не варто було залишати курку в духовці так довго. Невелика катастрофа, справді.'::text),
(347883,38654,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... dejado el pollo tanto tiempo en el horno. Un desastre menor, la verdad.'::text,'no debería haber'::text,'no debía haber'::text,'no pudo haber'::text,'Él no debería haber dejado el pollo tanto tiempo en el horno. Un desastre menor, la verdad.'::text),
(347882,38654,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... laisser le poulet au four si longtemps. Une petite catastrophe, vraiment.'::text,'n''aurait pas dû'::text,'n''aurait pas dû'::text,'n''a pas pu'::text,'Il n''aurait pas dû laisser le poulet au four si longtemps. Une petite catastrophe, vraiment.'::text),
(347885,38654,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavuğu fırında o kadar uzun ...; küçük bir felaket, gerçekten.'::text,'bırakmamalıydı'::text,'bırakmamış olmalı'::text,'bırakamadı'::text,'Tavuğu fırında o kadar uzun bırakmamalıydı; küçük bir felaket, gerçekten.'::text),
(347886,38654,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem ... ennyi ideig a sütőben hagyni a csirkét. Kisebb katasztrófa, tényleg.'::text,'kellett volna'::text,'szabadott volna'::text,'tudta'::text,'Nem kellett volna ennyi ideig a sütőben hagyni a csirkét. Kisebb katasztrófa, tényleg.'::text),
(347889,38655,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nicht nur ... verbrannte der Toast, auch das Hähnchen war eine Katastrophe. Nicht ideal.'::text,''::text,NULL::text,NULL::text,'Nicht nur verbrannte der Toast, auch das Hähnchen war eine Katastrophe. Nicht ideal.'::text),
(347893,38655,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не лише ... згорів тост, а й курка була катастрофою. Не ідеально.'::text,''::text,NULL::text,NULL::text,'Не лише згорів тост, а й курка була катастрофою. Не ідеально.'::text),
(347892,38655,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No solo ... se quemó la tostada, sino que el pollo también fue un desastre. No es lo ideal.'::text,''::text,NULL::text,NULL::text,'No solo se quemó la tostada, sino que el pollo también fue un desastre. No es lo ideal.'::text),
(347891,38655,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non seulement ... le toast a brûlé, mais le poulet était aussi une catastrophe. Pas idéal.'::text,''::text,NULL::text,NULL::text,'Non seulement le toast a brûlé, mais le poulet était aussi une catastrophe. Pas idéal.'::text),
(347894,38655,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sadece tost ... yanmadı, tavuk da felaketti. Pek ideal değil.'::text,''::text,NULL::text,NULL::text,'Sadece tost yanmadı, tavuk da felaketti. Pek ideal değil.'::text),
(347895,38655,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nemcsak ... a pirítós égett oda, hanem a csirke is katasztrófa lett. Nem ideális.'::text,''::text,NULL::text,NULL::text,'Nemcsak a pirítós égett oda, hanem a csirke is katasztrófa lett. Nem ideális.'::text),
(347898,38656,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Totale Katastrophe! Er muss jemanden dazu bringen, diese verrauchte Küche ..., bevor sie abbrennt!'::text,'zu putzen'::text,'putzen'::text,'geputzt'::text,'Totale Katastrophe! Er muss jemanden dazu bringen, diese verrauchte Küche zu putzen, bevor sie abbrennt!'::text),
(347902,38656,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Повна катастрофа! Йому треба когось попросити ... цю задимлену кухню, поки вона не згоріла!'::text,'прибрати'::text,'прибрати'::text,'прибрав'::text,'Повна катастрофа! Йому треба когось попросити прибрати цю задимлену кухню, поки вона не згоріла!'::text),
(347901,38656,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre total! ¡Necesita conseguir que alguien ... esta cocina llena de humo antes de que se queme!'::text,'limpie'::text,'limpiar'::text,'limpió'::text,'¡Desastre total! ¡Necesita conseguir que alguien limpie esta cocina llena de humo antes de que se queme!'::text),
(347900,38656,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe totale ! Il doit trouver quelqu''un pour ... cette cuisine enfumée avant qu''elle ne brûle !'::text,'nettoyer'::text,'nettoyer'::text,'nettoyé'::text,'Catastrophe totale ! Il doit trouver quelqu''un pour nettoyer cette cuisine enfumée avant qu''elle ne brûle !'::text),
(347903,38656,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tam bir felaket! Bu dumanlı mutfak yanmadan önce birine ... lazım!'::text,'temizletmesi'::text,'temizlemesi'::text,'temizledi'::text,'Tam bir felaket! Bu dumanlı mutfak yanmadan önce birine temizletmesi lazım!'::text),
(347904,38656,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Totális katasztrófa! Valakivel ... kell ezt a füstös konyhát, mielőtt leég!'::text,'kitakaríttatnia'::text,'kitakarítani'::text,'kitakarította'::text,'Totális katasztrófa! Valakivel kitakaríttatnia kell ezt a füstös konyhát, mielőtt leég!'::text),
(347907,38657,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünschte, er hätte auf den Toaster ..., denn jetzt ist das ganze Abendessen eine Katastrophe!'::text,'aufgepasst'::text,'aufpasste'::text,'aufpassen würde'::text,'Er wünschte, er hätte auf den Toaster aufgepasst, denn jetzt ist das ganze Abendessen eine Katastrophe!'::text),
(347911,38657,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він шкодує, що не ... за тостером, бо тепер уся вечеря — катастрофа!'::text,'стежив'::text,'стежить'::text,'стежитиме'::text,'Він шкодує, що не стежив за тостером, бо тепер уся вечеря — катастрофа!'::text),
(347910,38657,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ojalá él ... la tostadora, porque ahora toda la cena es un desastre!'::text,'hubiera vigilado'::text,'vigilara'::text,'vigilaría'::text,'¡Ojalá él hubiera vigilado la tostadora, porque ahora toda la cena es un desastre!'::text),
(347909,38657,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il regrette de ne pas ... le grille-pain, parce que maintenant tout le dîner est une catastrophe !'::text,'avoir surveillé'::text,'surveiller'::text,'surveiller'::text,'Il regrette de ne pas avoir surveillé le grille-pain, parce que maintenant tout le dîner est une catastrophe !'::text),
(347912,38657,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke ekmek kızartma makinesine ... diyor, çünkü şimdi bütün akşam yemeği felaket!'::text,'göz kulak olsaydım'::text,'göz kulak olsam'::text,'göz kulak olurdum'::text,'Keşke ekmek kızartma makinesine göz kulak olsaydım diyor, çünkü şimdi bütün akşam yemeği felaket!'::text),
(347913,38657,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bárcsak ... a kenyérpirítóra, mert most az egész vacsora katasztrófa!'::text,'figyelt volna'::text,'figyelne'::text,'figyelne'::text,'Bárcsak figyelt volna a kenyérpirítóra, mert most az egész vacsora katasztrófa!'::text),
(347916,38658,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, er hat mir erzählt, dass das Hähnchen, ... Rauch die Küche füllte, die wahre Katastrophe war.'::text,'dessen'::text,'das'::text,'welches'::text,'Mädel, er hat mir erzählt, dass das Hähnchen, dessen Rauch die Küche füllte, die wahre Katastrophe war.'::text),
(347920,38658,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що курка, ... дим заповнив кухню, була справжньою катастрофою.'::text,'чий'::text,'яка'::text,'що'::text,'Подруго, він сказав мені, що курка, чий дим заповнив кухню, була справжньою катастрофою.'::text),
(347919,38658,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que el pollo, ... humo llenó la cocina, fue el verdadero desastre.'::text,'cuyo'::text,'que'::text,'el cual'::text,'Tía, me dijo que el pollo, cuyo humo llenó la cocina, fue el verdadero desastre.'::text),
(347918,38658,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit que le poulet, ... la fumée a rempli la cuisine, était la vraie catastrophe.'::text,'dont'::text,'qui'::text,'que'::text,'Meuf, il m''a dit que le poulet, dont la fumée a rempli la cuisine, était la vraie catastrophe.'::text),
(347921,38658,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana dumanı mutfağı ... tavuğun asıl felaket olduğunu söyledi.'::text,'dolduran'::text,'dolduran'::text,'dolduran'::text,'Kızım, bana dumanı mutfağı dolduran tavuğun asıl felaket olduğunu söyledi.'::text),
(347922,38658,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy a csirke, ... füstje betöltötte a konyhát, volt az igazi katasztrófa.'::text,'amelynek a'::text,'amely'::text,'ami'::text,'Csajszi, azt mondta, hogy a csirke, amelynek a füstje betöltötte a konyhát, volt az igazi katasztrófa.'::text),
(347925,38659,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also, ich hab gehört, sein Abendessen war ... von Anfang bis Ende.'::text,'eine totale Katastrophe'::text,'die totale Katastrophe'::text,'totale Katastrophe'::text,'Okay, also, ich hab gehört, sein Abendessen war eine totale Katastrophe von Anfang bis Ende.'::text),
(347929,38659,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, я чула, що його вечеря була ... від початку до кінця.'::text,'повною катастрофою'::text,'повною катастрофою'::text,'повною катастрофою'::text,'Отже, я чула, що його вечеря була повною катастрофою від початку до кінця.'::text),
(347928,38659,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, he oído que su cena fue ... de principio a fin.'::text,'un desastre total'::text,'el desastre total'::text,'desastre total'::text,'Vale, he oído que su cena fue un desastre total de principio a fin.'::text),
(347927,38659,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, il paraît que son dîner a été ... du début à la fin.'::text,'un désastre total'::text,'le désastre total'::text,'désastre total'::text,'Bon, il paraît que son dîner a été un désastre total du début à la fin.'::text),
(347930,38659,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, duyduğuma göre akşam yemeği baştan sona ... olmuş.'::text,'tam bir felaket'::text,'tam felaket'::text,'tam felaket'::text,'Tamam, duyduğuma göre akşam yemeği baştan sona tam bir felaket olmuş.'::text),
(347931,38659,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval azt hallottam, hogy a vacsorája ... volt az elejétől a végéig.'::text,'egy totális katasztrófa'::text,'a totális katasztrófa'::text,'totális katasztrófa'::text,'Szóval azt hallottam, hogy a vacsorája egy totális katasztrófa volt az elejétől a végéig.'::text),
(347934,38660,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Abendessen wurde ... des verbrannten Toasts und des rauchenden Ofens zur Katastrophe.'::text,'wegen'::text,'trotz'::text,'vorausgesetzt'::text,'Das Abendessen wurde wegen des verbrannten Toasts und des rauchenden Ofens zur Katastrophe.'::text),
(347938,38660,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вечеря перетворилася на катастрофу ... згорілий тост і задимлену духовку.'::text,'через'::text,'попри'::text,'за умови що'::text,'Вечеря перетворилася на катастрофу через згорілий тост і задимлену духовку.'::text),
(347937,38660,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cena se convirtió en un desastre ... la tostada quemada y el horno humeante.'::text,'debido a'::text,'a pesar de'::text,'siempre que'::text,'La cena se convirtió en un desastre debido a la tostada quemada y el horno humeante.'::text),
(347936,38660,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le dîner a tourné à la catastrophe ... toast brûlé et au four fumant.'::text,'dû au'::text,'malgré le'::text,'pourvu que le'::text,'Le dîner a tourné à la catastrophe dû au toast brûlé et au four fumant.'::text),
(347939,38660,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yanmış tost ve dumanı tüten fırın ... akşam yemeği felakete döndü.'::text,'yüzünden'::text,'rağmen'::text,'şartıyla'::text,'Yanmış tost ve dumanı tüten fırın yüzünden akşam yemeği felakete döndü.'::text),
(347940,38660,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vacsora az odaégett pirítós és a füstölgő sütő ... katasztrófába fulladt.'::text,'miatt'::text,'ellenére'::text,'feltéve, hogy'::text,'A vacsora az odaégett pirítós és a füstölgő sütő miatt katasztrófába fulladt.'::text),
(347943,38661,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als er den Ofen anmachte, wusste er nicht, dass das Abendessen eine Katastrophe ...'::text,'werden würde'::text,'werden wird'::text,'ist'::text,'Als er den Ofen anmachte, wusste er nicht, dass das Abendessen eine Katastrophe werden würde.'::text),
(347947,38661,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли він увімкнув духовку, він не знав, що вечеря ... катастрофою.'::text,'буде'::text,'буде'::text,'є'::text,'Коли він увімкнув духовку, він не знав, що вечеря буде катастрофою.'::text),
(347946,38661,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando encendió el horno, no sabía que la cena ... un desastre.'::text,'sería'::text,'será'::text,'es'::text,'Cuando encendió el horno, no sabía que la cena sería un desastre.'::text),
(347945,38661,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand il a allumé le four, il ne savait pas que le dîner ... une catastrophe.'::text,'serait'::text,'sera'::text,'est'::text,'Quand il a allumé le four, il ne savait pas que le dîner serait une catastrophe.'::text),
(347948,38661,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fırını açtığında akşam yemeğinin felaket ... bilmiyordu.'::text,'olacağını'::text,'olacağını'::text,'olduğunu'::text,'Fırını açtığında akşam yemeğinin felaket olacağını bilmiyordu.'::text),
(347949,38661,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor bekapcsolta a sütőt, nem tudta, hogy a vacsora katasztrófa ...'::text,'lesz'::text,'lesz'::text,NULL::text,'Amikor bekapcsolta a sütőt, nem tudta, hogy a vacsora katasztrófa lesz.'::text),
(347952,38662,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rauch ... aus dem Ofen, und die Küche ist eine Katastrophe.'::text,'quillt'::text,'quillt'::text,'ist gequollen'::text,'Rauch quillt aus dem Ofen, und die Küche ist eine Katastrophe.'::text),
