(372347,41372,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duydum ki kıvılcımlar uçuştuğunda avuçlarını ateşin üzerinde ...'::text,'tutuyormuş'::text,'tutmuş'::text,'tutmuş'::text,'Kızım, duydum ki kıvılcımlar uçuştuğunda avuçlarını ateşin üzerinde tutuyormuş.'::text),
(372348,41372,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy épp a tenyerét ... a tűz fölé, amikor felszálltak a szikrák.'::text,'tartotta'::text,'tartotta'::text,'tartotta'::text,'Csajszi, azt hallottam, hogy épp a tenyerét tartotta a tűz fölé, amikor felszálltak a szikrák.'::text),
(372351,41373,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, anscheinend ... sie sich schon seit einer Stunde die Handflächen an dem Feuer.'::text,'wärmt'::text,'wärmt'::text,'wärmt'::text,'Bestie, anscheinend wärmt sie sich schon seit einer Stunde die Handflächen an dem Feuer.'::text),
(372355,41373,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, кажуть, вона ... долоні біля того вогню вже годину.'::text,'гріє'::text,'гріє'::text,'гріє'::text,'Подружко, кажуть, вона гріє долоні біля того вогню вже годину.'::text),
(372354,41373,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer ella ... las palmas junto a ese fuego desde hace una hora.'::text,'lleva calentándose'::text,'se está calentando'::text,'se calienta'::text,'Amiga, al parecer ella lleva calentándose las palmas junto a ese fuego desde hace una hora.'::text),
(372353,41373,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment elle ... les paumes près de ce feu depuis une heure.'::text,'se réchauffe'::text,'se réchauffe'::text,'se réchauffe'::text,'Ma belle, apparemment elle se réchauffe les paumes près de ce feu depuis une heure.'::text),
(372356,41373,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, anlaşılan bir saattir o ateşin başında avuçlarını ...'::text,'ısıtıyor'::text,'ısıtıyor'::text,'ısıtır'::text,'Kanka, anlaşılan bir saattir o ateşin başında avuçlarını ısıtıyor.'::text),
(372357,41373,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag már egy órája ... a tenyerét annál a tűznél.'::text,'melegíti'::text,'melegíti'::text,'melegíti'::text,'Csajszi, állítólag már egy órája melegíti a tenyerét annál a tűznél.'::text),
(372360,41374,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also er meinte, sie ... zuerst das Feuer und streckte dann die Handflächen aus.'::text,'schürte'::text,'schürte gerade'::text,'hat geschürt'::text,'Okay, also er meinte, sie schürte zuerst das Feuer und streckte dann die Handflächen aus.'::text),
(372364,41374,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, він сказав, що вона спершу ... вогонь, а потім простягнула долоні.'::text,'підживила'::text,'підживлювала'::text,'підживила'::text,'Отже, він сказав, що вона спершу підживила вогонь, а потім простягнула долоні.'::text),
(372363,41374,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, él dijo que primero ella ... el fuego y luego extendió las palmas.'::text,'avivó'::text,'estaba avivando'::text,'ha avivado'::text,'Vale, él dijo que primero ella avivó el fuego y luego extendió las palmas.'::text),
(372362,41374,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, il a dit qu''elle ... le feu d''abord, puis a tendu les paumes.'::text,'a alimenté'::text,'alimentait'::text,'a alimenté'::text,'Bon, il a dit qu''elle a alimenté le feu d''abord, puis a tendu les paumes.'::text),
(372365,41374,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, o dedi ki kız önce ateşi ..., sonra avuçlarını uzattı.'::text,'besledi'::text,'besliyordu'::text,'besledi'::text,'Tamam, o dedi ki kız önce ateşi besledi, sonra avuçlarını uzattı.'::text),
(372366,41374,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval azt mondta, hogy először ... a tüzet, aztán kinyújtotta a tenyerét.'::text,'táplálta'::text,'táplálta'::text,'táplálta'::text,'Szóval azt mondta, hogy először táplálta a tüzet, aztán kinyújtotta a tenyerét.'::text),
(372369,41375,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... sich den ganzen Abend die Handflächen über diesem winzigen Feuer. Tolles Heizsystem, offensichtlich.'::text,'wärmt'::text,'wärmte'::text,'wärmt'::text,'Sie wärmt sich den ganzen Abend die Handflächen über diesem winzigen Feuer. Tolles Heizsystem, offensichtlich.'::text),
(372373,41375,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона цілий вечір ... долоні над тим крихітним вогником. Чудова система опалення, звісно.'::text,'гріє'::text,'зігріла'::text,'гріє'::text,'Вона цілий вечір гріє долоні над тим крихітним вогником. Чудова система опалення, звісно.'::text),
(372372,41375,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... las palmas sobre ese fuego diminuto toda la tarde. Gran sistema de calefacción, obviamente.'::text,'ha estado calentándose'::text,'se ha calentado'::text,'se calienta'::text,'Ella ha estado calentándose las palmas sobre ese fuego diminuto toda la tarde. Gran sistema de calefacción, obviamente.'::text),
(372371,41375,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... les paumes au-dessus de ce minuscule feu toute la soirée. Super système de chauffage, évidemment.'::text,'se réchauffe'::text,'s''est réchauffé'::text,'se réchauffe'::text,'Elle se réchauffe les paumes au-dessus de ce minuscule feu toute la soirée. Super système de chauffage, évidemment.'::text),
(372374,41375,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün akşam o minicik ateşin üzerinde avuçlarını ...; harika bir ısıtma sistemi, belli ki.'::text,'ısıtıyor'::text,'ısıttı'::text,'ısıtır'::text,'Bütün akşam o minicik ateşin üzerinde avuçlarını ısıtıyor; harika bir ısıtma sistemi, belli ki.'::text),
(372375,41375,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egész este ... a tenyerét azon az apró tűzön. Remek fűtési rendszer, nyilván.'::text,'melegíti'::text,'megmelegítette'::text,'melegíti'::text,'Egész este melegíti a tenyerét azon az apró tűzön. Remek fűtési rendszer, nyilván.'::text),
(372378,41376,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Handflächen über diesem winzigen Feuer? Ihr ... sehr kalt sein. Tolle Strandnacht, ganz klar.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Handflächen über diesem winzigen Feuer? Ihr muss sehr kalt sein. Tolle Strandnacht, ganz klar.'::text),
(372382,41376,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Долоні над тим крихітним вогником? Їй ... бути дуже холодно. Чудова ніч на пляжі, ясно.'::text,'мусить'::text,'не може'::text,'має'::text,'Долоні над тим крихітним вогником? Їй мусить бути дуже холодно. Чудова ніч на пляжі, ясно.'::text),
(372381,41376,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Las palmas sobre ese fuego diminuto? Ella ... tener mucho frío. Gran noche de playa, está claro.'::text,'debe de'::text,'no puede'::text,'debería'::text,'¿Las palmas sobre ese fuego diminuto? Ella debe de tener mucho frío. Gran noche de playa, está claro.'::text),
(372380,41376,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les paumes au-dessus de ce minuscule feu ? Elle ... avoir très froid. Super soirée à la plage, clairement.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Les paumes au-dessus de ce minuscule feu ? Elle doit avoir très froid. Super soirée à la plage, clairement.'::text),
(372383,41376,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O minicik ateşin üzerinde avuçlar? Çok üşüyor ...; harika bir sahil gecesi, belli ki.'::text,'olmalı'::text,'olamaz'::text,'olmalı'::text,'O minicik ateşin üzerinde avuçlar? Çok üşüyor olmalı; harika bir sahil gecesi, belli ki.'::text),
(372384,41376,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tenyér kinyújtva azon az apró tűz fölött? Ő ... nagyon fázik. Remek strandos este, egyértelműen.'::text,'biztosan'::text,'nem lehet, hogy'::text,'valószínűleg'::text,'Tenyér kinyújtva azon az apró tűz fölött? Ő biztosan nagyon fázik. Remek strandos este, egyértelműen.'::text),
(372387,41377,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, das Mädel, ... Handflächen über dem Feuer sind, lebt gerade voll ihr bestes Leben.'::text,'dessen'::text,'das'::text,'welches'::text,'Bro, das Mädel, dessen Handflächen über dem Feuer sind, lebt gerade voll ihr bestes Leben.'::text),
(372391,41377,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, дівчина, ... долоні над тим вогнем, по-тихому живе найкраще життя.'::text,'чиї'::text,'яка'::text,'котра'::text,'Бро, дівчина, чиї долоні над тим вогнем, по-тихому живе найкраще життя.'::text),
(372390,41377,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, la chica ... palmas están sobre ese fuego está viviendo su mejor vida, en plan.'::text,'cuyas'::text,'que'::text,'la cual'::text,'Bro, la chica cuyas palmas están sobre ese fuego está viviendo su mejor vida, en plan.'::text),
(372389,41377,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, la meuf ... les paumes sont au-dessus du feu vit carrément sa meilleure vie.'::text,'dont'::text,'qui'::text,'que'::text,'Frère, la meuf dont les paumes sont au-dessus du feu vit carrément sa meilleure vie.'::text),
(372392,41377,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, avuçları o ateşin üzerinde ... kız resmen hayatını yaşıyor.'::text,'olan'::text,'olan'::text,'olan'::text,'Kanka, avuçları o ateşin üzerinde olan kız resmen hayatını yaşıyor.'::text),
(372393,41377,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az a csaj, ... a tenyere a tűz fölött van, simán éli a legjobb életét.'::text,'akinek'::text,'aki'::text,'ami'::text,'Tesó, az a csaj, akinek a tenyere a tűz fölött van, simán éli a legjobb életét.'::text),
(372396,41378,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie sagte, dass ihre Handflächen kalt ..., bevor sie das Feuer anzündete.'::text,'gewesen waren'::text,'gewesen sind'::text,'sind'::text,'Sie sagte, dass ihre Handflächen kalt gewesen waren, bevor sie das Feuer anzündete.'::text),
(372400,41378,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала, що її долоні ... холодними, поки вона не розпалила вогонь.'::text,'були'::text,'були'::text,'є'::text,'Вона сказала, що її долоні були холодними, поки вона не розпалила вогонь.'::text),
(372399,41378,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que sus palmas ... frías antes de encender el fuego.'::text,'habían estado'::text,'han estado'::text,'están'::text,'Dijo que sus palmas habían estado frías antes de encender el fuego.'::text),
(372398,41378,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a dit que ses paumes ... froides avant qu''elle allume le feu.'::text,'avaient été'::text,'ont été'::text,'sont'::text,'Elle a dit que ses paumes avaient été froides avant qu''elle allume le feu.'::text),
(372401,41378,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ateşi yakmadan önce avuçlarının soğuk ... söyledi.'::text,'olmuş olduğunu'::text,'olduğunu'::text,'olduğunu'::text,'Ateşi yakmadan önce avuçlarının soğuk olmuş olduğunu söyledi.'::text),
(372402,41378,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy a tenyere hideg ..., mielőtt meggyújtotta a tüzet.'::text,'volt'::text,'volt'::text,NULL::text,'Azt mondta, hogy a tenyere hideg volt, mielőtt meggyújtotta a tüzet.'::text),
(372414,41380,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... immer weiter Stöcke ins Feuer, bis ihre Handflächen warm waren.'::text,'legte'::text,'legte'::text,'legte'::text,'Sie legte immer weiter Stöcke ins Feuer, bis ihre Handflächen warm waren.'::text),
(372418,41380,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона все ... палички у вогонь, поки долоні не зігрілися.'::text,'підкладала'::text,'підкладати'::text,'підкладати'::text,'Вона все підкладала палички у вогонь, поки долоні не зігрілися.'::text),
(372417,41380,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Siguió ... palitos al fuego hasta que sus palmas se calentaron.'::text,'echando'::text,'echar'::text,'echar'::text,'Siguió echando palitos al fuego hasta que sus palmas se calentaron.'::text),
(372416,41380,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a continué ... des bâtons dans le feu jusqu''à ce que ses paumes soient chaudes.'::text,'à mettre'::text,'de mettre'::text,'mettre'::text,'Elle a continué à mettre des bâtons dans le feu jusqu''à ce que ses paumes soient chaudes.'::text),
(372419,41380,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avuçları ısınana kadar ateşe çubuk ... devam etti.'::text,'atmaya'::text,'atmaya'::text,'at'::text,'Avuçları ısınana kadar ateşe çubuk atmaya devam etti.'::text),
(372420,41380,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Addig ... gallyakat a tűzre, amíg a tenyere át nem melegedett.'::text,'rakott'::text,'rakni'::text,'rak'::text,'Addig rakott gallyakat a tűzre, amíg a tenyere át nem melegedett.'::text),
(372432,41382,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Handflächen ... schon stundenlang taub, bevor dieses Feuer sie vor der totalen Katastrophe rettete!'::text,'waren'::text,'sind'::text,'werden'::text,'Ihre Handflächen waren schon stundenlang taub, bevor dieses Feuer sie vor der totalen Katastrophe rettete!'::text),
(372436,41382,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її долоні ... годинами, поки той вогонь не врятував її від повної катастрофи!'::text,'терпли'::text,'терпнуть'::text,'терпнуть'::text,'Її долоні терпли годинами, поки той вогонь не врятував її від повної катастрофи!'::text),
(372435,41382,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Sus palmas ... entumeciéndose durante horas antes de que ese fuego la salvara del desastre total!'::text,'habían estado'::text,'han estado'::text,'están'::text,'¡Sus palmas habían estado entumeciéndose durante horas antes de que ese fuego la salvara del desastre total!'::text),
(372434,41382,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses paumes ... engourdies depuis des heures avant que ce feu la sauve d''une catastrophe totale !'::text,'étaient'::text,'sont'::text,'deviennent'::text,'Ses paumes étaient engourdies depuis des heures avant que ce feu la sauve d''une catastrophe totale !'::text),
(372437,41382,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O ateş onu tam bir felaketten kurtarmadan önce avuçları saatlerdir ...!'::text,'uyuşuyordu'::text,'uyuşuyor'::text,'uyuşuyor'::text,'O ateş onu tam bir felaketten kurtarmadan önce avuçları saatlerdir uyuşuyordu!'::text),
(372438,41382,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tenyere órák óta ..., mielőtt az a tűz megmentette a totális katasztrófától!'::text,'zsibbadt'::text,'zsibbad'::text,'zsibbad'::text,'A tenyere órák óta zsibbadt, mielőtt az a tűz megmentette a totális katasztrófától!'::text),
(347493,38611,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, er hat mir erzählt, dass sie ihn morgen Mittag aus dem Sand ...'::text,'ausgraben werden'::text,'ausgraben werden'::text,'ausgraben'::text,'Mädel, er hat mir erzählt, dass sie ihn morgen Mittag aus dem Sand ausgraben werden.'::text),
(347497,38611,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що завтра опівдні його ... з піску.'::text,'відкопуватимуть'::text,'відкопають'::text,'відкопують'::text,'Подруго, він сказав мені, що завтра опівдні його відкопуватимуть з піску.'::text),
(347496,38611,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que mañana a mediodía lo ... de la arena.'::text,'estarán desenterrando'::text,'desenterrarán'::text,'están desenterrando'::text,'Tía, me dijo que mañana a mediodía lo estarán desenterrando de la arena.'::text),
(347495,38611,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit que demain midi, ils ... du sable.'::text,'seront en train de le déterrer'::text,'le déterreront'::text,'le déterrent'::text,'Meuf, il m''a dit que demain midi, ils seront en train de le déterrer du sable.'::text),
(347498,38611,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana yarın öğlen onu kumdan ... söyledi.'::text,'çıkarıyor olacaklarını'::text,'çıkaracaklarını'::text,'çıkardıklarını'::text,'Kızım, bana yarın öğlen onu kumdan çıkarıyor olacaklarını söyledi.'::text),
(347499,38611,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy holnap délben ... a homokból.'::text,'fogják kiásni'::text,'kiássák'::text,'ássák ki'::text,'Csajszi, azt mondta, hogy holnap délben fogják kiásni a homokból.'::text),
(347502,38612,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, chill, wir ... dich gleich aus, versprochen, echt.'::text,'graben'::text,'graben gerade'::text,'graben'::text,'Bro, chill, wir graben dich gleich aus, versprochen, echt.'::text),
(347506,38612,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, розслабся, ми ... тебе за секунду, обіцяю, реально.'::text,'відкопаємо'::text,'відкопуватимемо'::text,'відкопуємо'::text,'Бро, розслабся, ми відкопаємо тебе за секунду, обіцяю, реально.'::text),
(347505,38612,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, tranqui, te ... en un segundo, te lo prometo, en serio.'::text,'sacaremos'::text,'estaremos sacando'::text,'estamos sacando'::text,'Bro, tranqui, te sacaremos en un segundo, te lo prometo, en serio.'::text),
(347504,38612,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, détends-toi, on te ... dans une seconde, promis, pour de vrai.'::text,'sortira'::text,'sera en train de sortir'::text,'sort'::text,'Frère, détends-toi, on te sortira dans une seconde, promis, pour de vrai.'::text),
(347507,38612,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, rahatla, seni bir saniyede ..., söz, cidden.'::text,'çıkaracağız'::text,'çıkarıyor olacağız'::text,'çıkarıyoruz'::text,'Kanka, rahatla, seni bir saniyede çıkaracağız, söz, cidden.'::text),
(347508,38612,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, nyugi, egy pillanat alatt ... téged, ígérem, komolyan.'::text,'kiásunk'::text,'ásni fogunk'::text,'ásunk'::text,'Tesó, nyugi, egy pillanat alatt kiásunk téged, ígérem, komolyan.'::text),
(347511,38613,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, wenn du so nah an den Wellen ein Loch ..., läuft es voll Wasser, ohne Witz.'::text,'gräbst'::text,'gegraben hast'::text,'graben wirst'::text,'Alter, wenn du so nah an den Wellen ein Loch gräbst, läuft es voll Wasser, ohne Witz.'::text),
(347515,38613,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, якщо ... яму так близько до хвиль, вона наповнюється водою, без жартів.'::text,'копаєш'::text,'копав'::text,'копатимеш'::text,'Чувак, якщо копаєш яму так близько до хвиль, вона наповнюється водою, без жартів.'::text),
(347514,38613,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, si ... un hoyo tan cerca de las olas, se llena de agua, sin mentir.'::text,'cavas'::text,'cavaste'::text,'cavarás'::text,'Tío, si cavas un hoyo tan cerca de las olas, se llena de agua, sin mentir.'::text),
(347513,38613,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, si tu ... un trou aussi près des vagues, il se remplit d''eau, sans mentir.'::text,'creuses'::text,'as creusé'::text,'creuseras'::text,'Mec, si tu creuses un trou aussi près des vagues, il se remplit d''eau, sans mentir.'::text),
(347516,38613,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dostum, dalgalara bu kadar yakın bir çukur ..., suyla dolar, yemin ederim.'::text,'kazarsan'::text,'kazdıysan'::text,'kazacaksan'::text,'Dostum, dalgalara bu kadar yakın bir çukur kazarsan, suyla dolar, yemin ederim.'::text),
(347517,38613,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, ha ilyen közel a hullámokhoz ... egy gödröt, megtelik vízzel, komolyan.'::text,'ásol'::text,'ástál'::text,'fogsz ásni'::text,'Haver, ha ilyen közel a hullámokhoz ásol egy gödröt, megtelik vízzel, komolyan.'::text),
(347520,38614,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Freunde, ... das Loch gegraben haben, haben ihre Deadline um 10 Minuten unterboten.'::text,'die'::text,'welche'::text,'deren'::text,'Die Freunde, die das Loch gegraben haben, haben ihre Deadline um 10 Minuten unterboten.'::text),
(347524,38614,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Друзі, ... викопали яму, випередили дедлайн на 10 хвилин.'::text,'які'::text,'що'::text,'чиї'::text,'Друзі, які викопали яму, випередили дедлайн на 10 хвилин.'::text),
(347523,38614,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los amigos ... cavaron el hoyo se adelantaron 10 minutos a su plazo.'::text,'que'::text,'los cuales'::text,'cuyos'::text,'Los amigos que cavaron el hoyo se adelantaron 10 minutos a su plazo.'::text),
(347522,38614,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les amis ... ont creusé le trou ont battu leur deadline de 10 minutes.'::text,'qui'::text,'que'::text,'dont'::text,'Les amis qui ont creusé le trou ont battu leur deadline de 10 minutes.'::text),
(347525,38614,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çukuru ... arkadaşlar teslim tarihini 10 dakika farkla geçti.'::text,'kazan'::text,'kazan'::text,'kazdığı'::text,'Çukuru kazan arkadaşlar teslim tarihini 10 dakika farkla geçti.'::text),
(347526,38614,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barátok, ... kiásták a gödröt, 10 perccel a határidő előtt végeztek.'::text,'akik'::text,'amik'::text,'akiknek'::text,'A barátok, akik kiásták a gödröt, 10 perccel a határidő előtt végeztek.'::text),
(347529,38615,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte, dass seine Freunde ein Loch ..., und deshalb sei er in einem Loch.'::text,'gegraben hatten'::text,'gegraben haben'::text,'graben'::text,'Er sagte, dass seine Freunde ein Loch gegraben hatten, und deshalb sei er in einem Loch.'::text),
(347533,38615,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що його друзі ... яму, тому він і був у ямі.'::text,'викопали'::text,'викопали'::text,'копають'::text,'Він сказав, що його друзі викопали яму, тому він і був у ямі.'::text),
(347532,38615,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que sus amigos ... un hoyo, así que por eso estaba en un hoyo.'::text,'habían cavado'::text,'han cavado'::text,'cavan'::text,'Dijo que sus amigos habían cavado un hoyo, así que por eso estaba en un hoyo.'::text),
(347531,38615,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit que ses amis ... un trou, et que c''était pour ça qu''il était dans un trou.'::text,'avaient creusé'::text,'ont creusé'::text,'creusent'::text,'Il a dit que ses amis avaient creusé un trou, et que c''était pour ça qu''il était dans un trou.'::text),
(347534,38615,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşlarının bir çukur ... söyledi, çukurda olmasının sebebi buymuş.'::text,'kazmış olduğunu'::text,'kazdığını'::text,'kazdığını'::text,'Arkadaşlarının bir çukur kazmış olduğunu söyledi, çukurda olmasının sebebi buymuş.'::text),
(347535,38615,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy a barátai ... egy gödröt, és ezért volt egy gödörben.'::text,'ástak'::text,'ástak'::text,'ásnak'::text,'Azt mondta, hogy a barátai ástak egy gödröt, és ezért volt egy gödörben.'::text),
(347538,38616,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als Kinder ... sie jeden Sommer an diesem Strand Löcher.'::text,'gruben'::text,'gruben'::text,'waren gewohnt zu graben'::text,'Als Kinder gruben sie jeden Sommer an diesem Strand Löcher.'::text),
(347542,38616,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У дитинстві вони ... ями на цьому пляжі щоліта.'::text,'копали'::text,'копали'::text,'звикли копати'::text,'У дитинстві вони копали ями на цьому пляжі щоліта.'::text),
(347541,38616,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De niños, ... cavar hoyos en esta playa cada verano.'::text,'solían'::text,'solían'::text,'estaban acostumbrados a'::text,'De niños, solían cavar hoyos en esta playa cada verano.'::text),
(347540,38616,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Enfants, ils ... des trous sur cette plage chaque été.'::text,'creusaient'::text,'creusaient'::text,'avaient l''habitude de creuser'::text,'Enfants, ils creusaient des trous sur cette plage chaque été.'::text),
(347543,38616,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocukken her yaz bu sahilde çukur ...'::text,'kazarlardı'::text,'kazarlardı'::text,'kazmaya alışkındılar'::text,'Çocukken her yaz bu sahilde çukur kazarlardı.'::text),
(347544,38616,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gyerekként minden nyáron ... gödröket ezen a strandon.'::text,'ástak'::text,'ástak'::text,'hozzá voltak szokva ásni'::text,'Gyerekként minden nyáron ástak gödröket ezen a strandon.'::text),
(347547,38617,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine Freunde haben mehr Spaß daran, Sand auf ihn ..., als ihn auszugraben.'::text,'zu werfen'::text,'zu werfen'::text,'werfen'::text,'Seine Freunde haben mehr Spaß daran, Sand auf ihn zu werfen, als ihn auszugraben.'::text),
(347551,38617,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його друзям більше подобається ... на нього пісок, ніж відкопувати його.'::text,'сипати'::text,'сипати'::text,'сипати'::text,'Його друзям більше подобається сипати на нього пісок, ніж відкопувати його.'::text),
(347550,38617,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sus amigos les gusta más ... arena encima que desenterrarlo.'::text,'echarle'::text,'echarle'::text,'echarle'::text,'A sus amigos les gusta más echarle arena encima que desenterrarlo.'::text),
(347549,38617,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses amis adorent ... du sable sur lui plus que le déterrer.'::text,'jeter'::text,'jeter'::text,'jeter'::text,'Ses amis adorent jeter du sable sur lui plus que le déterrer.'::text),
(347552,38617,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşları onun üstüne kum ... onu çıkarmaktan daha çok seviyor.'::text,'atmayı'::text,'atmayı'::text,'at'::text,'Arkadaşları onun üstüne kum atmayı onu çıkarmaktan daha çok seviyor.'::text),
(347553,38617,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barátai jobban élvezik, hogy homokot ... rá, mint hogy kiássák.'::text,'szórnak'::text,'szórni'::text,'szór'::text,'A barátai jobban élvezik, hogy homokot szórnak rá, mint hogy kiássák.'::text),
(347556,38618,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie haben ihm zuerst ein großes Loch gegraben, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Sie haben ihm zuerst ein großes Loch gegraben, oder?'::text),
(347560,38618,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Спочатку вони викопали для нього велику яму, ...?'::text,'так'::text,'так'::text,'так'::text,'Спочатку вони викопали для нього велику яму, так?'::text),
(347559,38618,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Primero le cavaron un gran hoyo, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Primero le cavaron un gran hoyo, ¿verdad?'::text),
(347558,38618,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils lui ont d''abord creusé un grand trou, ... ?'::text,'pas vrai'::text,'pas vrai'::text,'pas vrai'::text,'Ils lui ont d''abord creusé un grand trou, pas vrai ?'::text),
(347561,38618,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Önce ona büyük bir çukur kazdılar, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Önce ona büyük bir çukur kazdılar, değil mi?'::text),
(347562,38618,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Először egy nagy gödröt ástak neki, ...?'::text,'igaz'::text,'igaz'::text,'igaz'::text,'Először egy nagy gödröt ástak neki, igaz?'::text),
(347583,38621,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, anscheinend ... sie schon zehn Minuten gegraben, bevor er zustimmte, sich ins Loch zu legen.'::text,'hatten'::text,'haben'::text,'gruben'::text,'Hör mal, anscheinend hatten sie schon zehn Minuten gegraben, bevor er zustimmte, sich ins Loch zu legen.'::text),
(347587,38621,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, вони ... десять хвилин, перш ніж він погодився лягти в яму.'::text,'копали'::text,'копали'::text,'копали'::text,'Слухай, кажуть, вони копали десять хвилин, перш ніж він погодився лягти в яму.'::text),
(347586,38621,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer ... diez minutos cavando antes de que él aceptara tumbarse en el hoyo.'::text,'llevaban'::text,'llevan'::text,'estaban'::text,'Oye, al parecer llevaban diez minutos cavando antes de que él aceptara tumbarse en el hoyo.'::text),
(347585,38621,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment ils ... depuis dix minutes quand il a accepté de s''allonger dans le trou.'::text,'creusaient'::text,'creusent'::text,'creusaient'::text,'Écoute, apparemment ils creusaient depuis dix minutes quand il a accepté de s''allonger dans le trou.'::text),
(347588,38621,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, anlaşılan o çukura yatmayı kabul etmeden önce on dakika ...'::text,'kazıyorlarmış'::text,'kazıyorlar'::text,'kazıyorlardı'::text,'Dinle, anlaşılan o çukura yatmayı kabul etmeden önce on dakika kazıyorlarmış.'::text),
(347589,38621,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag már tíz perce ..., mielőtt beleegyezett, hogy befekszik a gödörbe.'::text,'ástak'::text,'ásnak'::text,'ástak'::text,'Figyelj, állítólag már tíz perce ástak, mielőtt beleegyezett, hogy befekszik a gödörbe.'::text),
(356871,39653,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mann, als die Beerdigung vorbei war, ... die Arbeiter schon das ganze Grab zugeschüttet. Ziemlich heftig.'::text,'hatten'::text,'haben'::text,'schütten'::text,'Mann, als die Beerdigung vorbei war, hatten die Arbeiter schon das ganze Grab zugeschüttet. Ziemlich heftig.'::text),
(356875,39653,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, поки похорон закінчився, робітники вже ... всю могилу. Трохи важко.'::text,'засипали'::text,'засипали'::text,'засипають'::text,'Чувак, поки похорон закінчився, робітники вже засипали всю могилу. Трохи важко.'::text),
(356874,39653,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, para cuando terminó el funeral, los operarios ya ... toda la tumba. Bastante fuerte.'::text,'habían rellenado'::text,'han rellenado'::text,'rellenan'::text,'Tío, para cuando terminó el funeral, los operarios ya habían rellenado toda la tumba. Bastante fuerte.'::text),
(356873,39653,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, quand l''enterrement s''est terminé, les ouvriers ... toute la tombe. Un peu lourd.'::text,'avaient rebouché'::text,'ont rebouché'::text,'rebouchent'::text,'Mec, quand l''enterrement s''est terminé, les ouvriers avaient rebouché toute la tombe. Un peu lourd.'::text),
(356876,39653,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dostum, cenaze bittiğinde işçiler bütün mezarı çoktan ..., biraz ağır.'::text,'doldurmuşlardı'::text,'doldurdular'::text,'dolduruyorlar'::text,'Dostum, cenaze bittiğinde işçiler bütün mezarı çoktan doldurmuşlardı, biraz ağır.'::text),
(356877,39653,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, mire a temetés véget ért, a munkások már ... az egész sírt. Elég durva.'::text,'betemették'::text,'betemették'::text,'temetik be'::text,'Haver, mire a temetés véget ért, a munkások már betemették az egész sírt. Elég durva.'::text),
(356880,39654,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn eine Beerdigung länger als 60 Minuten ..., zahlt das Friedhofsbudget den Arbeitern Überstunden.'::text,'dauert'::text,'dauerte'::text,'dauern wird'::text,'Wenn eine Beerdigung länger als 60 Minuten dauert, zahlt das Friedhofsbudget den Arbeitern Überstunden.'::text),
(356884,39654,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо похорон ... довше 60 хвилин, бюджет кладовища оплачує робітникам понаднормові.'::text,'триває'::text,'тривав'::text,'триватиме'::text,'Якщо похорон триває довше 60 хвилин, бюджет кладовища оплачує робітникам понаднормові.'::text),
(356883,39654,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un funeral ... más de 60 minutos, el presupuesto del cementerio paga horas extra a los operarios.'::text,'dura'::text,'duró'::text,'durará'::text,'Si un funeral dura más de 60 minutos, el presupuesto del cementerio paga horas extra a los operarios.'::text),
(356882,39654,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un enterrement ... plus de 60 minutes, le budget du cimetière paie des heures sup aux ouvriers.'::text,'dure'::text,'a duré'::text,'durera'::text,'Si un enterrement dure plus de 60 minutes, le budget du cimetière paie des heures sup aux ouvriers.'::text),
(356885,39654,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir cenaze 60 dakikadan uzun ..., mezarlık bütçesi işçilere fazla mesai öder.'::text,'sürerse'::text,'sürdüyse'::text,'sürecekse'::text,'Bir cenaze 60 dakikadan uzun sürerse, mezarlık bütçesi işçilere fazla mesai öder.'::text),
(356886,39654,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy temetés 60 percnél tovább ..., a temető költségvetése túlórát fizet a munkásoknak.'::text,'tart'::text,'tartott'::text,'fog tartani'::text,'Ha egy temetés 60 percnél tovább tart, a temető költségvetése túlórát fizet a munkásoknak.'::text),
(356898,39656,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Würde die Erde neben dem Grab liegen bleiben, ... der Bestattungsprozess unvollständig.'::text,'bliebe'::text,'bleibt'::text,'blieb'::text,'Würde die Erde neben dem Grab liegen bleiben, bliebe der Bestattungsprozess unvollständig.'::text),
(356902,39656,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби земля лишилася біля могили, похоронний процес ... незавершеним.'::text,'залишився б'::text,'залишиться'::text,'залишився'::text,'Якби земля лишилася біля могили, похоронний процес залишився б незавершеним.'::text),
(356901,39656,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la tierra se dejara junto a la tumba, el proceso funerario ... incompleto.'::text,'quedaría'::text,'quedará'::text,'quedó'::text,'Si la tierra se dejara junto a la tumba, el proceso funerario quedaría incompleto.'::text),
(356900,39656,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la terre était laissée à côté de la tombe, le processus funéraire ... incomplet.'::text,'resterait'::text,'restera'::text,'est resté'::text,'Si la terre était laissée à côté de la tombe, le processus funéraire resterait incomplet.'::text),
(356903,39656,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toprak mezarın yanında bırakılsaydı cenaze süreci eksik ...'::text,'kalırdı'::text,'kalacak'::text,'kaldı'::text,'Toprak mezarın yanında bırakılsaydı cenaze süreci eksik kalırdı.'::text),
(356904,39656,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a földet a sír mellett hagynák, a temetési folyamat befejezetlen ...'::text,'maradna'::text,'marad'::text,'maradt'::text,'Ha a földet a sír mellett hagynák, a temetési folyamat befejezetlen maradna.'::text),
(356907,39657,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bei der Beerdigung gestern ... eine weiße Rose auf den Sargdeckel gelegt.'::text,'wurde'::text,'legte'::text,'wird'::text,'Bei der Beerdigung gestern wurde eine weiße Rose auf den Sargdeckel gelegt.'::text),
(356911,39657,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На вчорашньому похороні на кришку труни ... білу троянду.'::text,'поклали'::text,'поклала'::text,'кладуть'::text,'На вчорашньому похороні на кришку труни поклали білу троянду.'::text),
(356910,39657,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En el funeral de ayer, ... una rosa blanca sobre la tapa del ataúd.'::text,'se colocó'::text,'colocó'::text,'se coloca'::text,'En el funeral de ayer, se colocó una rosa blanca sobre la tapa del ataúd.'::text),
(356909,39657,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À l''enterrement d''hier, une rose blanche ... sur le couvercle du cercueil.'::text,'a été posée'::text,'a posé'::text,'est posée'::text,'À l''enterrement d''hier, une rose blanche a été posée sur le couvercle du cercueil.'::text),
(356912,39657,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dünkü cenazede tabutun kapağına beyaz bir gül ...'::text,'bırakıldı'::text,'bıraktı'::text,'bırakılıyor'::text,'Dünkü cenazede tabutun kapağına beyaz bir gül bırakıldı.'::text),
(356913,39657,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tegnapi temetésen egy fehér rózsát ... a koporsó fedelére.'::text,'helyeztek'::text,'helyezett'::text,'helyeznek'::text,'A tegnapi temetésen egy fehér rózsát helyeztek a koporsó fedelére.'::text),
(356916,39658,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nach der Beerdigung ... zwei Arbeiter Erde auf den Sarg.'::text,'schaufelten'::text,'wurden geschaufelt'::text,'schaufelnd'::text,'Nach der Beerdigung schaufelten zwei Arbeiter Erde auf den Sarg.'::text),
(356920,39658,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Після похорону двоє робітників ... землю на труну.'::text,'накидали лопатами'::text,'були накидані'::text,'накидаючи'::text,'Після похорону двоє робітників накидали лопатами землю на труну.'::text),
(356919,39658,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Después del funeral, dos operarios ... tierra sobre el ataúd.'::text,'palearon'::text,'fueron paleados'::text,'paleando'::text,'Después del funeral, dos operarios palearon tierra sobre el ataúd.'::text),
(356918,39658,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Après l''enterrement, deux ouvriers ... de la terre sur le cercueil.'::text,'ont pelleté'::text,'ont été pelletés'::text,'pelletant'::text,'Après l''enterrement, deux ouvriers ont pelleté de la terre sur le cercueil.'::text),
(356921,39658,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cenazeden sonra iki işçi tabutun üzerine kürekle toprak ...'::text,'attı'::text,'atıldı'::text,'atan'::text,'Cenazeden sonra iki işçi tabutun üzerine kürekle toprak attı.'::text),
(356922,39658,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A temetés után két munkás földet ... a koporsóra.'::text,'lapátolt'::text,'lett lapátolva'::text,'lapátolva'::text,'A temetés után két munkás földet lapátolt a koporsóra.'::text),
(356925,39659,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Trauernden haben die Köpfe gesenkt, also ... die Beerdigung für jemanden sein, den sie liebten.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Die Trauernden haben die Köpfe gesenkt, also muss die Beerdigung für jemanden sein, den sie liebten.'::text),
(356929,39659,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Присутні схилили голови, тож це ... бути похорон когось, кого вони любили.'::text,'мусить'::text,'не може'::text,'має'::text,'Присутні схилили голови, тож це мусить бути похорон когось, кого вони любили.'::text),
(356928,39659,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los asistentes tienen la cabeza agachada, así que el funeral ... ser por alguien a quien querían.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Los asistentes tienen la cabeza agachada, así que el funeral debe de ser por alguien a quien querían.'::text),
(356927,39659,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les proches ont la tête baissée, donc l''enterrement ... être celui de quelqu''un qu''ils aimaient.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Les proches ont la tête baissée, donc l''enterrement doit être celui de quelqu''un qu''ils aimaient.'::text),
(356930,39659,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yas tutanların başları eğik, demek ki cenaze sevdikleri biri için ...'::text,'olmalı'::text,'olamaz'::text,'olsa gerek'::text,'Yas tutanların başları eğik, demek ki cenaze sevdikleri biri için olmalı.'::text),
(356931,39659,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gyászolók lehajtott fejjel állnak, szóval a temetés ... valakié, akit szerettek.'::text,'biztosan'::text,'nem lehet'::text,'valószínűleg'::text,'A gyászolók lehajtott fejjel állnak, szóval a temetés biztosan valakié, akit szerettek.'::text),
(356934,39660,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, die Rose, ... du bei der Beerdigung hingelegt hast, war echt eine stilvolle Geste.'::text,'die'::text,'wer'::text,'deren'::text,'Ehrlich gesagt, die Rose, die du bei der Beerdigung hingelegt hast, war echt eine stilvolle Geste.'::text),
(356938,39660,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брехатиму, троянда, ... ти поклав на похороні, була дуже стильним жестом.'::text,'яку'::text,'хто'::text,'чия'::text,'Не брехатиму, троянда, яку ти поклав на похороні, була дуже стильним жестом.'::text),
(356937,39660,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, la rosa ... dejaste en el funeral fue un detalle con mucha clase.'::text,'que'::text,'quien'::text,'cuya'::text,'No voy a mentir, la rosa que dejaste en el funeral fue un detalle con mucha clase.'::text),
(356936,39660,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, la rose ... tu as posée à l''enterrement, c''était une touche vraiment classe.'::text,'que'::text,'qui'::text,'dont'::text,'Je vais pas mentir, la rose que tu as posée à l''enterrement, c''était une touche vraiment classe.'::text),
(356939,39660,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, cenazede ... gül gerçekten çok şık bir dokunuştu.'::text,'bıraktığın'::text,'bırakan'::text,'bıraktığın'::text,'Yalan yok, cenazede bıraktığın gül gerçekten çok şık bir dokunuştu.'::text),
(356940,39660,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, a rózsa, ... a temetésen letettél, nagyon elegáns gesztus volt.'::text,'amit'::text,'aki'::text,'akinek'::text,'Nem hazudok, a rózsa, amit a temetésen letettél, nagyon elegáns gesztus volt.'::text),
(356943,39661,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Arbeiter sagte, die Beerdigung ... schnell gehen. Ein echter Profi, offensichtlich, mit dieser Schaufel.'::text,'würde'::text,'werde'::text,'könne'::text,'Ein Arbeiter sagte, die Beerdigung würde schnell gehen. Ein echter Profi, offensichtlich, mit dieser Schaufel.'::text),
(356947,39661,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Один робітник сказав, що похорон ... швидким. Справжній профі, звісно, з тією лопатою.'::text,'буде'::text,'буде'::text,'може бути'::text,'Один робітник сказав, що похорон буде швидким. Справжній профі, звісно, з тією лопатою.'::text),
(356946,39661,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un operario dijo que el funeral ... rápido. Todo un profesional, obviamente, con esa pala.'::text,'sería'::text,'será'::text,'puede ser'::text,'Un operario dijo que el funeral sería rápido. Todo un profesional, obviamente, con esa pala.'::text),
(356945,39661,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un ouvrier a dit que l''enterrement ... rapide. Un vrai pro, évidemment, avec cette pelle.'::text,'serait'::text,'sera'::text,'peut être'::text,'Un ouvrier a dit que l''enterrement serait rapide. Un vrai pro, évidemment, avec cette pelle.'::text),
(356948,39661,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir işçi cenazenin çabuk ... söyledi. Gerçek bir profesyonel, belli ki, o kürekle.'::text,'olacağını'::text,'olacağını'::text,'olabileceğini'::text,'Bir işçi cenazenin çabuk olacağını söyledi. Gerçek bir profesyonel, belli ki, o kürekle.'::text),
(356949,39661,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egyik munkás azt mondta, hogy gyors ... a temetés. Igazi profi, nyilván, azzal a lapáttal.'::text,'lesz'::text,'lesz'::text,'lehet'::text,'Az egyik munkás azt mondta, hogy gyors lesz a temetés. Igazi profi, nyilván, azzal a lapáttal.'::text),
(356952,39662,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Friedhof ... an Beerdigungstagen ruhig. Zwei Schaufeln gleichzeitig, genau das, was wir gebraucht haben.'::text,'war früher'::text,'war früher'::text,'ist es gewohnt zu sein'::text,'Der Friedhof war früher an Beerdigungstagen ruhig. Zwei Schaufeln gleichzeitig, genau das, was wir gebraucht haben.'::text),
(356956,39662,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кладовище ... тихим у дні похоронів. Дві лопати одночасно, саме те, що треба.'::text,'раніше було'::text,'раніше було'::text,'звикло бути'::text,'Кладовище раніше було тихим у дні похоронів. Дві лопати одночасно, саме те, що треба.'::text),
(356955,39662,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cementerio ... estar tranquilo los días de funeral. Dos palas a la vez, justo lo que necesitábamos.'::text,'solía'::text,'solía'::text,'está acostumbrado a'::text,'El cementerio solía estar tranquilo los días de funeral. Dos palas a la vez, justo lo que necesitábamos.'::text),
(356954,39662,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, le cimetière ... calme les jours d''enterrement. Deux pelles en même temps, exactement ce qu''il nous fallait.'::text,'était'::text,'était'::text,'a l''habitude d''être'::text,'Avant, le cimetière était calme les jours d''enterrement. Deux pelles en même temps, exactement ce qu''il nous fallait.'::text),
(356957,39662,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mezarlık cenaze günlerinde eskiden sessiz ...; aynı anda iki kürek, tam da ihtiyacımız olan şey.'::text,'olurdu'::text,'olurdu'::text,'olmaya alışkın'::text,'Mezarlık cenaze günlerinde eskiden sessiz olurdu; aynı anda iki kürek, tam da ihtiyacımız olan şey.'::text),
(356958,39662,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A temető régen csendes ... a temetések napján. Egyszerre két lapát, pont erre volt szükségünk.'::text,'volt'::text,'volt'::text,'szokott lenni'::text,'A temető régen csendes volt a temetések napján. Egyszerre két lapát, pont erre volt szükségünk.'::text),
(356961,39663,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, niemand auf der Beerdigung hatte Lust, auch nur ein Wort ..., echt.'::text,'zu sagen'::text,'zu sagen'::text,'sagen'::text,'Bro, niemand auf der Beerdigung hatte Lust, auch nur ein Wort zu sagen, echt.'::text),
(356965,39663,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ніхто на похороні не мав бажання ... ані слова, реально.'::text,'сказати'::text,'сказати'::text,'сказати'::text,'Бро, ніхто на похороні не мав бажання сказати ані слова, реально.'::text),
(356964,39663,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, nadie en el funeral tenía ganas de ... ni una palabra, en serio.'::text,'decir'::text,'decir'::text,'decir'::text,'Bro, nadie en el funeral tenía ganas de decir ni una palabra, en serio.'::text),
(356963,39663,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, personne à l''enterrement n''avait envie de ... un mot, pour de vrai.'::text,'dire'::text,'dire'::text,'dire'::text,'Frère, personne à l''enterrement n''avait envie de dire un mot, pour de vrai.'::text),
(356966,39663,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, cenazede kimsenin tek kelime ... hali yoktu, cidden.'::text,'etmeye'::text,'etmeye'::text,'et'::text,'Kanka, cenazede kimsenin tek kelime etmeye hali yoktu, cidden.'::text),
(356967,39663,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a temetésen senkinek sem volt kedve egy szót sem ..., komolyan.'::text,'szólni'::text,'szólni'::text,'szól'::text,'Tesó, a temetésen senkinek sem volt kedve egy szót sem szólni, komolyan.'::text),
(328827,36537,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... gerade in den Stadtbus, als er seine Karte an das Lesegerät hielt.'::text,'stieg'::text,'stieg'::text,'ist gestiegen'::text,'Er stieg gerade in den Stadtbus, als er seine Karte an das Lesegerät hielt.'::text),
(328831,36537,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... в міський автобус, коли приклав картку до зчитувача.'::text,'заходив'::text,'зайшов'::text,'зайшов'::text,'Він заходив в міський автобус, коли приклав картку до зчитувача.'::text),
(328830,36537,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... al autobús urbano cuando pasó la tarjeta por el lector.'::text,'estaba subiendo'::text,'subió'::text,'ha subido'::text,'Él estaba subiendo al autobús urbano cuando pasó la tarjeta por el lector.'::text),
(328829,36537,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... dans le bus de ville quand il a passé sa carte sur le lecteur.'::text,'montait'::text,'est monté'::text,'est monté'::text,'Il montait dans le bus de ville quand il a passé sa carte sur le lecteur.'::text),
(328832,36537,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kartını okuyucuya okuttuğunda şehir otobüsüne ...'::text,'biniyordu'::text,'bindi'::text,'bindi'::text,'Kartını okuyucuya okuttuğunda şehir otobüsüne biniyordu.'::text),
(328833,36537,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... a városi buszra, amikor a kártyáját az olvasóhoz érintette.'::text,'szállt fel'::text,'szállt fel'::text,'szállt fel'::text,'Épp szállt fel a városi buszra, amikor a kártyáját az olvasóhoz érintette.'::text),
(328845,36539,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis heute Abend wird er in vier verschiedene Busse ...'::text,'eingestiegen sein'::text,'einsteigen'::text,'einsteigen'::text,'Bis heute Abend wird er in vier verschiedene Busse eingestiegen sein.'::text),
(328849,36539,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечора він ... у чотири різні автобуси.'::text,'встигне сісти'::text,'сяде'::text,'сідатиме'::text,'До вечора він встигне сісти у чотири різні автобуси.'::text),
(328848,36539,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para esta noche, él ... a cuatro autobuses distintos.'::text,'habrá subido'::text,'subirá'::text,'estará subiendo'::text,'Para esta noche, él habrá subido a cuatro autobuses distintos.'::text),
(328847,36539,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, il ... dans quatre bus différents.'::text,'sera monté'::text,'montera'::text,'sera en train de monter'::text,'D''ici ce soir, il sera monté dans quatre bus différents.'::text),
(328850,36539,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar dört farklı otobüse ...'::text,'binmiş olacak'::text,'binecek'::text,'biniyor olacak'::text,'Bu akşama kadar dört farklı otobüse binmiş olacak.'::text),
(328851,36539,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estére már négy különböző buszra ...'::text,'felszállt'::text,'fel fog szállni'::text,'fog szállni'::text,'Estére már négy különböző buszra felszállt.'::text),
(328854,36540,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mann, wenn er sich nicht in diesen Minibus gequetscht hätte, ... er den Tourbus nicht erwischt, echt.'::text,'hätte'::text,'wird'::text,'hat'::text,'Mann, wenn er sich nicht in diesen Minibus gequetscht hätte, hätte er den Tourbus nicht erwischt, echt.'::text),
(328858,36540,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, якби він не втиснувся в той мікроавтобус, він ... на екскурсійний автобус, реально.'::text,'не встиг би'::text,'не встигне'::text,'не встиг'::text,'Чувак, якби він не втиснувся в той мікроавтобус, він не встиг би на екскурсійний автобус, реально.'::text),
(328857,36540,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, si no se hubiera metido en ese microbús, no ... el autobús turístico, en serio.'::text,'habría pillado'::text,'pillará'::text,'pilló'::text,'Tío, si no se hubiera metido en ese microbús, no habría pillado el autobús turístico, en serio.'::text),
(328856,36540,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, s''il ne s''était pas faufilé dans ce minibus, il ... le bus touristique, pour de vrai.'::text,'n''aurait pas eu'::text,'n''aura pas'::text,'n''a pas eu'::text,'Mec, s''il ne s''était pas faufilé dans ce minibus, il n''aurait pas eu le bus touristique, pour de vrai.'::text),
(328859,36540,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o minibüse sıkışıp binmeseydi tur otobüsünü ..., cidden.'::text,'yakalayamazdı'::text,'yakalayamayacak'::text,'yakalayamadı'::text,'Kanka, o minibüse sıkışıp binmeseydi tur otobüsünü yakalayamazdı, cidden.'::text),
(328860,36540,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, ha nem préselődött volna fel arra a kisbuszra, nem ... el a városnéző buszt, komolyan.'::text,'érte volna'::text,'fogja érni'::text,'érte'::text,'Haver, ha nem préselődött volna fel arra a kisbuszra, nem érte volna el a városnéző buszt, komolyan.'::text),
(328863,36541,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Fahrer bat ihn, seine Karte vor dem Einsteigen ..., gemäß dem 2-Sekunden-Protokoll.'::text,'hinzuhalten'::text,'hinhaltend'::text,'hielt hin'::text,'Der Fahrer bat ihn, seine Karte vor dem Einsteigen hinzuhalten, gemäß dem 2-Sekunden-Protokoll.'::text),
(328867,36541,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Водій попросив його ... картку перед посадкою, згідно з 2-секундним протоколом.'::text,'прикласти'::text,'прикладаючи'::text,'приклав'::text,'Водій попросив його прикласти картку перед посадкою, згідно з 2-секундним протоколом.'::text),
(328866,36541,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El conductor le pidió ... la tarjeta antes de subir, según el protocolo de 2 segundos.'::text,'pasar'::text,'pasando'::text,'pasó'::text,'El conductor le pidió pasar la tarjeta antes de subir, según el protocolo de 2 segundos.'::text),
(328865,36541,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chauffeur lui a demandé de ... sa carte avant de monter, selon le protocole des 2 secondes.'::text,'valider'::text,'validant'::text,'a validé'::text,'Le chauffeur lui a demandé de valider sa carte avant de monter, selon le protocole des 2 secondes.'::text),
(328868,36541,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şoför, 2 saniye protokolü gereği binmeden önce ondan kartını ... istedi.'::text,'okutmasını'::text,'okutmayı'::text,'okuttu'::text,'Şoför, 2 saniye protokolü gereği binmeden önce ondan kartını okutmasını istedi.'::text),
(328869,36541,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sofőr megkérte, hogy ... a kártyáját felszállás előtt, a 2 másodperces protokoll szerint.'::text,'érintse oda'::text,'odaérintve'::text,'odaérintette'::text,'A sofőr megkérte, hogy érintse oda a kártyáját felszállás előtt, a 2 másodperces protokoll szerint.'::text),
(328881,36543,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor dem Einsteigen lässt der Fahrgast seine Karte typischerweise vom Lesegerät ...'::text,'auslesen'::text,'auslesend'::text,'auszulesen'::text,'Vor dem Einsteigen lässt der Fahrgast seine Karte typischerweise vom Lesegerät auslesen.'::text),
(328885,36543,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перед посадкою пасажир зазвичай дає ... свою картку зчитувачу.'::text,'зчитати'::text,'зчитуючи'::text,'зчитати'::text,'Перед посадкою пасажир зазвичай дає зчитати свою картку зчитувачу.'::text),
(328884,36543,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de subir, el pasajero normalmente hace que el lector ... su tarjeta.'::text,'lea'::text,'leyendo'::text,'leer'::text,'Antes de subir, el pasajero normalmente hace que el lector lea su tarjeta.'::text),
(328883,36543,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant de monter, le passager fait généralement ... sa carte par le lecteur.'::text,'lire'::text,'lisant'::text,'lire'::text,'Avant de monter, le passager fait généralement lire sa carte par le lecteur.'::text),
(328886,36543,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Binmeden önce yolcu kartını genellikle okuyucuya ...'::text,'okutur'::text,'okutarak'::text,'okutmaya'::text,'Binmeden önce yolcu kartını genellikle okuyucuya okutur.'::text),
(328887,36543,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felszállás előtt az utas jellemzően ... a kártyáját az olvasóval.'::text,'leolvastatja'::text,'leolvasva'::text,'leolvasni'::text,'Felszállás előtt az utas jellemzően leolvastatja a kártyáját az olvasóval.'::text),
(328890,36544,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, ich wünschte, ich ... mit deinem Selbstbewusstsein in Busse steigen.'::text,'könnte'::text,'kann'::text,'werde'::text,'Ehrlich, ich wünschte, ich könnte mit deinem Selbstbewusstsein in Busse steigen.'::text),
(328894,36544,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби ж я ... в автобуси з твоєю впевненістю.'::text,'міг заходити'::text,'можу заходити'::text,'заходитиму'::text,'Чесно, якби ж я міг заходити в автобуси з твоєю впевненістю.'::text),
(328893,36544,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, ojalá ... subir a los autobuses con tu seguridad.'::text,'pudiera'::text,'puedo'::text,'podré'::text,'La verdad, ojalá pudiera subir a los autobuses con tu seguridad.'::text),
(328892,36544,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si seulement je ... monter dans les bus avec ton assurance.'::text,'pouvais'::text,'peux'::text,'pourrai'::text,'Franchement, si seulement je pouvais monter dans les bus avec ton assurance.'::text),
(328895,36544,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, keşke otobüslere senin özgüveninle ...'::text,'binebilsem'::text,'binebiliyorum'::text,'binebileceğim'::text,'Açıkçası, keşke otobüslere senin özgüveninle binebilsem.'::text),
(328896,36544,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, bárcsak ... felszállni a buszokra olyan magabiztosan, mint te.'::text,'tudnék'::text,'tudok'::text,'fogok tudni'::text,'Őszintén, bárcsak tudnék felszállni a buszokra olyan magabiztosan, mint te.'::text),
(328899,36545,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Tourbus, auf ... Oberdeck du mit ausgebreiteten Armen gesessen hast, war legendär.'::text,'dessen'::text,'dem'::text,'der'::text,'Der Tourbus, auf dessen Oberdeck du mit ausgebreiteten Armen gesessen hast, war legendär.'::text),
(328903,36545,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Екскурсійний автобус, на ... верхній палубі ти сидів із розкинутими руками, був культовим.'::text,'чиїй'::text,'якому'::text,'що'::text,'Екскурсійний автобус, на чиїй верхній палубі ти сидів із розкинутими руками, був культовим.'::text),
(328902,36545,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El autobús turístico, en ... piso de arriba te sentaste con los brazos abiertos, fue icónico.'::text,'cuyo'::text,'el cual'::text,'que'::text,'El autobús turístico, en cuyo piso de arriba te sentaste con los brazos abiertos, fue icónico.'::text),
(328901,36545,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le bus touristique, sur l''impériale ... tu étais assis les bras grands ouverts, était iconique.'::text,'duquel'::text,'lequel'::text,'que'::text,'Le bus touristique, sur l''impériale duquel tu étais assis les bras grands ouverts, était iconique.'::text),
(328904,36545,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Üst katında kollarını açıp ... tur otobüsü efsaneydi.'::text,'oturduğun'::text,'oturduğun'::text,'oturduğun'::text,'Üst katında kollarını açıp oturduğun tur otobüsü efsaneydi.'::text),
(328905,36545,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A városnéző busz, ... felső szintjén széttárt karokkal ültél, ikonikus volt.'::text,'amelynek a'::text,'amely'::text,'ami'::text,'A városnéző busz, amelynek a felső szintjén széttárt karokkal ültél, ikonikus volt.'::text),
(328908,36546,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er stieg in den Minibus, ... er schon überfüllt war.'::text,'obwohl'::text,'wegen'::text,'falls'::text,'Er stieg in den Minibus, obwohl er schon überfüllt war.'::text),
(328912,36546,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сів у мікроавтобус, ... той уже був переповнений.'::text,'хоча'::text,'через те, що'::text,'на випадок, якщо'::text,'Він сів у мікроавтобус, хоча той уже був переповнений.'::text),
(328911,36546,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se subió al microbús ... ya iba lleno.'::text,'aunque'::text,'debido a'::text,'por si'::text,'Se subió al microbús aunque ya iba lleno.'::text),
(328910,36546,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il est monté dans le minibus ... celui-ci était déjà bondé.'::text,'même si'::text,'en raison de'::text,'au cas où'::text,'Il est monté dans le minibus même si celui-ci était déjà bondé.'::text),
(328913,36546,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zaten kalabalık ... minibüse bindi.'::text,'olmasına rağmen'::text,'olduğu için'::text,'olursa diye'::text,'Zaten kalabalık olmasına rağmen minibüse bindi.'::text),
(328914,36546,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felszállt a kisbuszra, ... az már zsúfolt volt.'::text,'pedig'::text,'amiatt, hogy'::text,'arra az esetre, ha'::text,'Felszállt a kisbuszra, pedig az már zsúfolt volt.'::text),
(328917,36547,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... er gerade in seinen fünften Bus des Tages. Ein ruhiger freier Tag, ganz klar.'::text,'steigt'::text,'wird steigen'::text,'wird gestiegen sein'::text,'Morgen um diese Zeit steigt er gerade in seinen fünften Bus des Tages. Ein ruhiger freier Tag, ganz klar.'::text),
(328921,36547,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час він ... у свій п''ятий автобус за день. Спокійний вихідний, ясно.'::text,'сідатиме'::text,'сяде'::text,'вже сяде'::text,'Завтра в цей час він сідатиме у свій п''ятий автобус за день. Спокійний вихідний, ясно.'::text),
(328920,36547,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora él ... a su quinto autobús del día. Un tranquilo día libre, está claro.'::text,'estará subiendo'::text,'subirá'::text,'habrá subido'::text,'Mañana a esta hora él estará subiendo a su quinto autobús del día. Un tranquilo día libre, está claro.'::text),
(328919,36547,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à cette heure-ci, il ... dans son cinquième bus de la journée. Un jour de repos tranquille, clairement.'::text,'sera en train de monter'::text,'montera'::text,'sera monté'::text,'Demain à cette heure-ci, il sera en train de monter dans son cinquième bus de la journée. Un jour de repos tranquille, clairement.'::text),
(328922,36547,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte günün beşinci otobüsüne ...; sakin bir izin günü, belli ki.'::text,'biniyor olacak'::text,'binecek'::text,'binmiş olacak'::text,'Yarın bu saatte günün beşinci otobüsüne biniyor olacak; sakin bir izin günü, belli ki.'::text),
(328923,36547,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor épp ... a napi ötödik buszára. Nyugis szabadnap, egyértelműen.'::text,'fog felszállni'::text,'száll fel'::text,'fel fog szállni már'::text,'Holnap ilyenkor épp fog felszállni a napi ötödik buszára. Nyugis szabadnap, egyértelműen.'::text),
(375645,41739,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Träger stand nicht still und seine Last ..., weil sie auf ihm lag.'::text,'auch nicht'::text,'auch'::text,'auch nicht'::text,'Der Träger stand nicht still und seine Last auch nicht, weil sie auf ihm lag.'::text),
(375649,41739,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Носій не стояв на місці, і його вантаж ..., бо він був на ньому.'::text,'теж ні'::text,'теж'::text,'теж ні'::text,'Носій не стояв на місці, і його вантаж теж ні, бо він був на ньому.'::text),
(375648,41739,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El mozo no se quedaba quieto, y ... su carga, porque estaba encima de él.'::text,'tampoco'::text,'también'::text,'tampoco'::text,'El mozo no se quedaba quieto, y tampoco su carga, porque estaba encima de él.'::text),
(375647,41739,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le porteur ne restait pas immobile, et sa charge ..., parce qu''elle était sur lui.'::text,'non plus'::text,'aussi'::text,'non plus'::text,'Le porteur ne restait pas immobile, et sa charge non plus, parce qu''elle était sur lui.'::text),
(375650,41739,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hamal yerinde durmuyordu, yükü de ..., çünkü onun üzerindeydi.'::text,'durmuyordu'::text,'öyleydi'::text,'durmuyordu'::text,'Hamal yerinde durmuyordu, yükü de durmuyordu, çünkü onun üzerindeydi.'::text),
(375651,41739,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hordár nem állt egy helyben, és a terhe ..., mert rajta volt.'::text,'sem'::text,'is'::text,'sem'::text,'A hordár nem állt egy helyben, és a terhe sem, mert rajta volt.'::text),
(375663,41741,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Sonnenuntergang ... dieser arme Träger buchstäblich jeden Teppich des Marktes auf dem Rücken getragen haben!'::text,'wird'::text,'wird'::text,'trägt'::text,'Bis Sonnenuntergang wird dieser arme Träger buchstäblich jeden Teppich des Marktes auf dem Rücken getragen haben!'::text),
(375667,41741,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця цей бідолашний носій ... на спині буквально кожен килим на ринку!'::text,'перенесе'::text,'носитиме'::text,'носить'::text,'До заходу сонця цей бідолашний носій перенесе на спині буквально кожен килим на ринку!'::text),
(375666,41741,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para el atardecer, este pobre mozo ... a la espalda literalmente todas las alfombras del mercado!'::text,'habrá cargado'::text,'cargará'::text,'carga'::text,'¡Para el atardecer, este pobre mozo habrá cargado a la espalda literalmente todas las alfombras del mercado!'::text),
(375665,41741,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, ce pauvre porteur ... littéralement chaque tapis du marché sur son dos !'::text,'aura porté'::text,'portera'::text,'porte'::text,'D''ici le coucher du soleil, ce pauvre porteur aura porté littéralement chaque tapis du marché sur son dos !'::text),
(375668,41741,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar bu zavallı hamal pazardaki kelimenin tam anlamıyla her halıyı sırtında ...!'::text,'taşımış olacak'::text,'taşıyacak'::text,'taşıyor'::text,'Gün batımına kadar bu zavallı hamal pazardaki kelimenin tam anlamıyla her halıyı sırtında taşımış olacak!'::text),
(375669,41741,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Napnyugtára ez a szegény hordár szó szerint a piac összes szőnyegét ... a hátán!'::text,'el fogja cipelni'::text,'cipeli majd'::text,'cipeli'::text,'Napnyugtára ez a szegény hordár szó szerint a piac összes szőnyegét el fogja cipelni a hátán!'::text),
(375672,41742,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zu Mittag ... der Träger diese Albtraumlast schon seit sechs Stunden!'::text,'schleppt'::text,'wird schleppen'::text,'hat geschleppt'::text,'Zu Mittag schleppt der Träger diese Albtraumlast schon seit sechs Stunden!'::text),
(375676,41742,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До полудня носій ... той жахливий вантаж уже шість годин!'::text,'нестиме'::text,'нестиме'::text,'ніс'::text,'До полудня носій нестиме той жахливий вантаж уже шість годин!'::text),
(375675,41742,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Al mediodía, el mozo ... seis horas cargando esa pesadilla de carga!'::text,'llevará'::text,'estará'::text,'ha estado'::text,'¡Al mediodía, el mozo llevará seis horas cargando esa pesadilla de carga!'::text),
(375674,41742,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À midi, le porteur ... ce cauchemar de chargement depuis six heures !'::text,'portera'::text,'sera en train de porter'::text,'a porté'::text,'À midi, le porteur portera ce cauchemar de chargement depuis six heures !'::text),
(375677,41742,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar hamal o kâbus gibi yükü altı saattir ...!'::text,'taşıyor olacak'::text,'taşıyor olacak'::text,'taşıdı'::text,'Öğlene kadar hamal o kâbus gibi yükü altı saattir taşıyor olacak!'::text),
(375678,41742,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre a hordár már hat órája ... azt a rémálomszerű terhet!'::text,'fogja cipelni'::text,'fogja cipelni'::text,'cipelte'::text,'Délre a hordár már hat órája fogja cipelni azt a rémálomszerű terhet!'::text),
(375681,41743,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wäre der Träger gestolpert, ... die silberne Teekanne in einer totalen Katastrophe heruntergekracht!'::text,'wäre'::text,'wird'::text,'ist'::text,'Wäre der Träger gestolpert, wäre die silberne Teekanne in einer totalen Katastrophe heruntergekracht!'::text),
(375685,41743,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби носій спіткнувся, срібний чайник ... донизу, повна катастрофа!'::text,'упав би'::text,'упаде'::text,'упав'::text,'Якби носій спіткнувся, срібний чайник упав би донизу, повна катастрофа!'::text),
(375684,41743,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si el mozo hubiera tropezado, la tetera de plata ... al suelo en un desastre total!'::text,'se habría estrellado'::text,'se estrellará'::text,'se estrelló'::text,'¡Si el mozo hubiera tropezado, la tetera de plata se habría estrellado al suelo en un desastre total!'::text),
(375683,41743,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le porteur avait trébuché, la théière en argent ... par terre dans une catastrophe totale !'::text,'se serait écrasée'::text,'s''écrasera'::text,'s''est écrasée'::text,'Si le porteur avait trébuché, la théière en argent se serait écrasée par terre dans une catastrophe totale !'::text),
(375686,41743,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hamal tökezleseydi gümüş çaydanlık tam bir felaketle yere ...!'::text,'çakılırdı'::text,'çakılacak'::text,'çakıldı'::text,'Hamal tökezleseydi gümüş çaydanlık tam bir felaketle yere çakılırdı!'::text),
(375687,41743,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a hordár megbotlott volna, az ezüst teáskanna totális katasztrófában ... a földre!'::text,'zuhant volna'::text,'fog zuhanni'::text,'zuhant'::text,'Ha a hordár megbotlott volna, az ezüst teáskanna totális katasztrófában zuhant volna a földre!'::text),
(375690,41744,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wäre der Träger zweimal gegangen, ... seine Last jetzt nicht so hoch über seinem Kopf.'::text,'wäre'::text,'wäre gewesen'::text,'wird'::text,'Wäre der Träger zweimal gegangen, wäre seine Last jetzt nicht so hoch über seinem Kopf.'::text),
(375694,41744,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби носій пішов двічі, його вантаж зараз ... так високо над головою.'::text,'не був би'::text,'не був би'::text,'не буде'::text,'Якби носій пішов двічі, його вантаж зараз не був би так високо над головою.'::text),
(375693,41744,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el mozo hubiera hecho dos viajes, su carga no ... tan alta sobre su cabeza ahora.'::text,'estaría'::text,'habría estado'::text,'estará'::text,'Si el mozo hubiera hecho dos viajes, su carga no estaría tan alta sobre su cabeza ahora.'::text),
(375692,41744,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le porteur avait fait deux voyages, son chargement ne ... pas aussi haut au-dessus de sa tête maintenant.'::text,'serait'::text,'aurait été'::text,'sera'::text,'Si le porteur avait fait deux voyages, son chargement ne serait pas aussi haut au-dessus de sa tête maintenant.'::text),
(375695,41744,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hamal iki seferde taşısaydı yükü şimdi başının bu kadar üstünde ...'::text,'olmazdı'::text,'olmamış olurdu'::text,'olmayacak'::text,'Hamal iki seferde taşısaydı yükü şimdi başının bu kadar üstünde olmazdı.'::text),
(375696,41744,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a hordár kétszer fordult volna, a terhe most nem ... ilyen magasan a feje fölött.'::text,'lenne'::text,'lett volna'::text,'lesz'::text,'Ha a hordár kétszer fordult volna, a terhe most nem lenne ilyen magasan a feje fölött.'::text),
(375699,41745,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Träger soll diesen ganzen Stapel für den Mann im gemusterten Hemd ...'::text,'tragen'::text,'tragend'::text,'tragen'::text,'Der Träger soll diesen ganzen Stapel für den Mann im gemusterten Hemd tragen.'::text),
(375703,41745,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, носій ... всю цю купу для чоловіка в сорочці з візерунком.'::text,'несе'::text,'несучи'::text,'несе'::text,'Кажуть, носій несе всю цю купу для чоловіка в сорочці з візерунком.'::text),
(375702,41745,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice que el mozo ... todo este montón para el hombre de la camisa estampada.'::text,'está cargando'::text,'cargando'::text,'está cargando'::text,'Se dice que el mozo está cargando todo este montón para el hombre de la camisa estampada.'::text),
(375701,41745,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que le porteur ... toute cette pile pour l''homme à la chemise à motifs.'::text,'porte'::text,'portant'::text,'porte'::text,'On dit que le porteur porte toute cette pile pour l''homme à la chemise à motifs.'::text),
(375704,41745,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hamalın bu yığının tamamını desenli gömlekli adam için ... söyleniyor.'::text,'taşıdığı'::text,'taşıyarak'::text,'taşıdığı'::text,'Hamalın bu yığının tamamını desenli gömlekli adam için taşıdığı söyleniyor.'::text),
(375705,41745,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Állítólag a hordár ... ezt az egész halmot a mintás inges férfinak.'::text,'cipeli'::text,'cipelve'::text,'cipeli'::text,'Állítólag a hordár cipeli ezt az egész halmot a mintás inges férfinak.'::text),
(375708,41746,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, anscheinend hat der Käufer den Träger gefragt, ob er alles zu seinem Hotel ...'::text,'tragen könnte'::text,'könnte er tragen'::text,'tragen kann'::text,'Okay, anscheinend hat der Käufer den Träger gefragt, ob er alles zu seinem Hotel tragen könnte.'::text),
(375712,41746,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, кажуть, покупець спитав носія, ... віднести все до його готелю.'::text,'чи міг би він'::text,'чи міг би він'::text,'чи може він'::text,'Отже, кажуть, покупець спитав носія, чи міг би він віднести все до його готелю.'::text),
(375711,41746,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, al parecer el cliente le preguntó al mozo ... llevarlo todo a su hotel.'::text,'si podía'::text,'podía él'::text,'si puede'::text,'Vale, al parecer el cliente le preguntó al mozo si podía llevarlo todo a su hotel.'::text),
(375710,41746,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment le client a demandé au porteur ... tout porter jusqu''à son hôtel.'::text,'s''il pouvait'::text,'pouvait-il'::text,'s''il peut'::text,'Bon, apparemment le client a demandé au porteur s''il pouvait tout porter jusqu''à son hôtel.'::text),
(375713,41746,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, anlaşılan müşteri hamala her şeyi oteline ... sormuş.'::text,'taşıyıp taşıyamayacağını'::text,'taşıyabilir mi'::text,'taşıyabilir mi'::text,'Tamam, anlaşılan müşteri hamala her şeyi oteline taşıyıp taşıyamayacağını sormuş.'::text),
(375714,41746,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval állítólag a vásárló megkérdezte a hordárt, hogy ... elvinni mindent a szállodájába.'::text,'tudná-e'::text,'tudná'::text,'tudja-e'::text,'Szóval állítólag a vásárló megkérdezte a hordárt, hogy tudná-e elvinni mindent a szállodájába.'::text),
(375717,41747,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Träger ... Hilfe gebraucht haben, denn er trug viel zu viel für einen Mann.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Der Träger muss Hilfe gebraucht haben, denn er trug viel zu viel für einen Mann.'::text),
(375721,41747,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Носій ... потребувати допомоги, бо ніс набагато більше, ніж під силу одній людині.'::text,'мусив'::text,'не міг'::text,'не мусив'::text,'Носій мусив потребувати допомоги, бо ніс набагато більше, ніж під силу одній людині.'::text),
(375720,41747,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El mozo ... necesitado ayuda, porque llevaba demasiado para un solo hombre.'::text,'debe de haber'::text,'no puede haber'::text,'no debe haber'::text,'El mozo debe de haber necesitado ayuda, porque llevaba demasiado para un solo hombre.'::text),
(375719,41747,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le porteur ... avoir besoin d''aide, parce qu''il portait beaucoup trop pour un seul homme.'::text,'a dû'::text,'n''a pas pu'::text,'ne devait pas'::text,'Le porteur a dû avoir besoin d''aide, parce qu''il portait beaucoup trop pour un seul homme.'::text),
(375722,41747,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hamalın yardıma ihtiyacı ..., çünkü tek bir adam için çok fazla şey taşıyordu.'::text,'olmuş olmalı'::text,'olmuş olamaz'::text,'olmamalıydı'::text,'Hamalın yardıma ihtiyacı olmuş olmalı, çünkü tek bir adam için çok fazla şey taşıyordu.'::text),
(375723,41747,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hordárnak ... segítségre volt szüksége, mert túl sokat cipelt egy emberhez képest.'::text,'biztosan'::text,'nem lehet, hogy'::text,'nem szabadott'::text,'A hordárnak biztosan segítségre volt szüksége, mert túl sokat cipelt egy emberhez képest.'::text),
(375726,41748,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selten ... einen Träger eine so hohe Last über den Markt tragen.'::text,'sah ich'::text,'ich sah'::text,'ich sah'::text,'Selten sah ich einen Träger eine so hohe Last über den Markt tragen.'::text),
(375730,41748,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рідко ... носія, який ніс би такий високий вантаж через ринок.'::text,'я бачив'::text,'я бачив'::text,'я бачив'::text,'Рідко я бачив носія, який ніс би такий високий вантаж через ринок.'::text),
(375729,41748,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pocas veces ... a un mozo llevar una carga tan alta por el mercado.'::text,'he visto'::text,'he visto'::text,'vi'::text,'Pocas veces he visto a un mozo llevar una carga tan alta por el mercado.'::text),
(375728,41748,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rarement ... un porteur transporter une charge aussi haute à travers le marché.'::text,'ai-je vu'::text,'j''ai vu'::text,'j''ai vu'::text,'Rarement ai-je vu un porteur transporter une charge aussi haute à travers le marché.'::text),
(375731,41748,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pazarda bu kadar yüksek bir yük taşıyan bir hamalı nadiren ...'::text,'gördüm'::text,'gördüm'::text,'gördüm'::text,'Pazarda bu kadar yüksek bir yük taşıyan bir hamalı nadiren gördüm.'::text),
(375732,41748,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ritkán ... hordárt, aki ilyen magas terhet vitt át a piacon.'::text,'láttam'::text,'láttam'::text,'láttam'::text,'Ritkán láttam hordárt, aki ilyen magas terhet vitt át a piacon.'::text),
(392637,43627,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... schon den ganzen Vormittag Teller in diesen Schrank, und ehrlich, dein System ist legendär.'::text,'stapelst'::text,'stapelst'::text,'stapelst'::text,'Du stapelst schon den ganzen Vormittag Teller in diesen Schrank, und ehrlich, dein System ist legendär.'::text),
(392641,43627,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... тарілки в ту шафку весь ранок, і чесно, твоя система — культова.'::text,'складаєш'::text,'складаєш'::text,'складаєш'::text,'Ти складаєш тарілки в ту шафку весь ранок, і чесно, твоя система — культова.'::text),
(392640,43627,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... platos en ese armario toda la mañana, y la verdad, tu sistema es icónico.'::text,'llevas guardando'::text,'estás guardando'::text,'guardas'::text,'Tú llevas guardando platos en ese armario toda la mañana, y la verdad, tu sistema es icónico.'::text),
(392639,43627,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... des assiettes dans ce placard depuis ce matin, et franchement, ton système est iconique.'::text,'ranges'::text,'ranges'::text,'ranges'::text,'Tu ranges des assiettes dans ce placard depuis ce matin, et franchement, ton système est iconique.'::text),
(392642,43627,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün sabah o dolaba tabak ... ve açıkçası sistemin efsane.'::text,'diziyorsun'::text,'diziyorsun'::text,'dizersin'::text,'Bütün sabah o dolaba tabak diziyorsun ve açıkçası sistemin efsane.'::text),
(392643,43627,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egész délelőtt tányérokat ... abba a szekrénybe, és őszintén, a rendszered ikonikus.'::text,'pakolsz'::text,'pakolsz'::text,'pakolsz'::text,'Egész délelőtt tányérokat pakolsz abba a szekrénybe, és őszintén, a rendszered ikonikus.'::text),
(392646,43628,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während du die Schüsseln ..., wurden die leeren Regale zu einem Regenbogen. Ehrlich, Respekt.'::text,'einräumtest'::text,'einräumtest'::text,'eingeräumt hast'::text,'Während du die Schüsseln einräumtest, wurden die leeren Regale zu einem Regenbogen. Ehrlich, Respekt.'::text),
(392650,43628,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки ти ... миски, порожні полиці перетворилися на веселку. Чесно, респект.'::text,'розставляв'::text,'розставив'::text,'розставив'::text,'Поки ти розставляв миски, порожні полиці перетворилися на веселку. Чесно, респект.'::text),
(392649,43628,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ... los boles, los estantes vacíos se convirtieron en un arcoíris. La verdad, respeto.'::text,'guardabas'::text,'guardaste'::text,'has guardado'::text,'Mientras guardabas los boles, los estantes vacíos se convirtieron en un arcoíris. La verdad, respeto.'::text),
(392648,43628,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que tu ... les bols, les étagères vides se sont transformées en arc-en-ciel. Franchement, respect.'::text,'rangeais'::text,'as rangé'::text,'as rangé'::text,'Pendant que tu rangeais les bols, les étagères vides se sont transformées en arc-en-ciel. Franchement, respect.'::text),
(392651,43628,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen kâseleri ..., boş raflar gökkuşağına döndü. Açıkçası, saygılar.'::text,'yerleştirirken'::text,'yerleştirdin'::text,'yerleştirdin'::text,'Sen kâseleri yerleştirirken, boş raflar gökkuşağına döndü. Açıkçası, saygılar.'::text),
(392652,43628,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben ... a tálakat, az üres polcok szivárvánnyá változtak. Őszintén, respekt.'::text,'pakoltad be'::text,'bepakoltad'::text,'bepakoltad'::text,'Miközben pakoltad be a tálakat, az üres polcok szivárvánnyá változtak. Őszintén, respekt.'::text),
(392655,43629,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Offensichtlich ein fauler Typ: Er ... jeden einzelnen Teller in den Schrank geräumt.'::text,'hat'::text,'hat'::text,'räumt'::text,'Offensichtlich ein fauler Typ: Er hat jeden einzelnen Teller in den Schrank geräumt.'::text),
(392659,43629,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, лінивий хлопець: він ... кожну тарілку в шафку.'::text,'поставив'::text,'ставив'::text,'ставить'::text,'Очевидно, лінивий хлопець: він поставив кожну тарілку в шафку.'::text),
(392658,43629,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente un vago: ... cada plato en el armario.'::text,'ha guardado'::text,'ha estado guardando'::text,'está guardando'::text,'Obviamente un vago: ha guardado cada plato en el armario.'::text),
(392657,43629,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement un paresseux : il ... chaque assiette dans le placard.'::text,'a rangé'::text,'a rangé'::text,'range'::text,'Clairement un paresseux : il a rangé chaque assiette dans le placard.'::text),
(392660,43629,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki tembel biri: dolaba her bir tabağı tek tek ...'::text,'yerleştirdi'::text,'yerleştiriyordu'::text,'yerleştiriyor'::text,'Belli ki tembel biri: dolaba her bir tabağı tek tek yerleştirdi.'::text),
(392661,43629,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván egy lusta alak: minden egyes tányért ... a szekrénybe.'::text,'betett'::text,'rakosgatott'::text,'rak'::text,'Nyilván egy lusta alak: minden egyes tányért betett a szekrénybe.'::text),
(392664,43630,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein echter Profi, ganz klar: Als er die Türen schloss, ... er alles verstaut.'::text,'hatte'::text,'hat'::text,'verstaut'::text,'Ein echter Profi, ganz klar: Als er die Türen schloss, hatte er alles verstaut.'::text),
(392668,43630,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Справжній професіонал, ясно: поки він зачинив дверцята, він ... все.'::text,'розклав'::text,'розклав'::text,'розкладає'::text,'Справжній професіонал, ясно: поки він зачинив дверцята, він розклав все.'::text),
(392667,43630,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todo un profesional, está claro: para cuando cerró las puertas, ya lo ... todo.'::text,'había guardado'::text,'ha guardado'::text,'guarda'::text,'Todo un profesional, está claro: para cuando cerró las puertas, ya lo había guardado todo.'::text),
(392666,43630,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un vrai pro, clairement : quand il a fermé les portes, il ... tout.'::text,'avait rangé'::text,'a rangé'::text,'range'::text,'Un vrai pro, clairement : quand il a fermé les portes, il avait rangé tout.'::text),
(392669,43630,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerçek bir profesyonel, belli ki: kapakları kapattığında her şeyi çoktan ...'::text,'yerleştirmişti'::text,'yerleştirdi'::text,'yerleştiriyor'::text,'Gerçek bir profesyonel, belli ki: kapakları kapattığında her şeyi çoktan yerleştirmişti.'::text),
(392670,43630,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Igazi profi, egyértelműen: mire becsukta az ajtókat, már mindent ...'::text,'elpakolt'::text,'elpakolt'::text,'elpakol'::text,'Igazi profi, egyértelműen: mire becsukta az ajtókat, már mindent elpakolt.'::text),
(392673,43631,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz klar zu wenig Schränke. Wenn er mehr Gläser kauft, ... er sie aufs oberste Regal.'::text,'stellt'::text,'würde'::text,'stellte'::text,'Ganz klar zu wenig Schränke. Wenn er mehr Gläser kauft, stellt er sie aufs oberste Regal.'::text),
(392677,43631,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно замало шафок. Якщо він купить більше банок, він ... їх на верхню полицю.'::text,'поставить'::text,'поставив би'::text,'поставив'::text,'Явно замало шафок. Якщо він купить більше банок, він поставить їх на верхню полицю.'::text),
(392676,43631,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente faltan armarios. Si compra más tarros, los ... en el estante de arriba.'::text,'guardará'::text,'guardaría'::text,'guardó'::text,'Claramente faltan armarios. Si compra más tarros, los guardará en el estante de arriba.'::text),
(392675,43631,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement pas assez de placards. S''il achète plus de bocaux, il les ... sur l''étagère du haut.'::text,'rangera'::text,'rangerait'::text,'a rangés'::text,'Clairement pas assez de placards. S''il achète plus de bocaux, il les rangera sur l''étagère du haut.'::text),
(392678,43631,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki dolap yetmiyor. Daha fazla kavanoz alırsa onları en üst rafa ...'::text,'koyacak'::text,'koyardı'::text,'koydu'::text,'Belli ki dolap yetmiyor. Daha fazla kavanoz alırsa onları en üst rafa koyacak.'::text),
(392679,43631,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván kevés a szekrény. Ha több befőttesüveget vesz, a legfelső polcra ... őket.'::text,'teszi'::text,'tenné'::text,'tette'::text,'Nyilván kevés a szekrény. Ha több befőttesüveget vesz, a legfelső polcra teszi őket.'::text),
(392682,43632,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er noch einen Teller da hinein ..., würde der ganze Schrank zusammenbrechen!'::text,'stellte'::text,'stellt'::text,'stellen würde'::text,'Wenn er noch einen Teller da hinein stellte, würde der ganze Schrank zusammenbrechen!'::text),
(392686,43632,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він ... туди ще одну тарілку, уся шафка б розвалилася!'::text,'поставив'::text,'поставить'::text,'поставив би'::text,'Якби він поставив туди ще одну тарілку, уся шафка б розвалилася!'::text),
(392685,43632,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si ... un plato más ahí dentro, todo el armario se vendría abajo!'::text,'guardara'::text,'guarda'::text,'guardaría'::text,'¡Si guardara un plato más ahí dentro, todo el armario se vendría abajo!'::text),
(392684,43632,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il ... une assiette de plus là-dedans, tout le placard s''effondrerait !'::text,'rangeait'::text,'range'::text,'rangerait'::text,'S''il rangeait une assiette de plus là-dedans, tout le placard s''effondrerait !'::text),
(392687,43632,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oraya bir tabak daha ..., bütün dolap çökerdi!'::text,'koysa'::text,'koyuyor'::text,'koyardı'::text,'Oraya bir tabak daha koysa, bütün dolap çökerdi!'::text),
(392688,43632,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha még egy tányért ... oda, az egész szekrény összeomlana!'::text,'tenne'::text,'tesz'::text,'tenne'::text,'Ha még egy tányért tenne oda, az egész szekrény összeomlana!'::text),
(392700,43634,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... die Teller und Schüsseln auf das untere Regal.'::text,'stellte'::text,'wurde gestellt'::text,'stellend'::text,'Er stellte die Teller und Schüsseln auf das untere Regal.'::text),
(392704,43634,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... тарілки й миски на нижню полицю.'::text,'поставив'::text,'був поставлений'::text,'ставлячи'::text,'Він поставив тарілки й миски на нижню полицю.'::text),
(392703,43634,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... los platos y los boles en el estante de abajo.'::text,'guardó'::text,'fue guardado'::text,'guardando'::text,'Él guardó los platos y los boles en el estante de abajo.'::text),
(392702,43634,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... les assiettes et les bols sur l''étagère du bas.'::text,'a rangé'::text,'a été rangé'::text,'rangeant'::text,'Il a rangé les assiettes et les bols sur l''étagère du bas.'::text),
(392705,43634,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabakları ve kâseleri alt rafa ...'::text,'yerleştirdi'::text,'yerleştirildi'::text,'yerleştiren'::text,'Tabakları ve kâseleri alt rafa yerleştirdi.'::text),
(392706,43634,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tányérokat és a tálakat az alsó polcra ...'::text,'tette'::text,'lett téve'::text,'téve'::text,'A tányérokat és a tálakat az alsó polcra tette.'::text),
(392709,43635,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Schrank ist jetzt voll, also ... er das ganze Geschirr dort verstaut haben.'::text,'muss'::text,'könnte'::text,'kann nicht'::text,'Der Schrank ist jetzt voll, also muss er das ganze Geschirr dort verstaut haben.'::text),
(392713,43635,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Шафка тепер повна, тож він ... скласти туди весь посуд.'::text,'мусив'::text,'міг'::text,'не міг'::text,'Шафка тепер повна, тож він мусив скласти туди весь посуд.'::text),
(392712,43635,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El armario ya está lleno, así que ... guardado ahí todos los platos.'::text,'debe de haber'::text,'podría haber'::text,'no puede haber'::text,'El armario ya está lleno, así que debe de haber guardado ahí todos los platos.'::text),
(392711,43635,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le placard est plein maintenant, donc il ... ranger toute la vaisselle là-dedans.'::text,'a dû'::text,'a pu'::text,'n''a pas pu'::text,'Le placard est plein maintenant, donc il a dû ranger toute la vaisselle là-dedans.'::text),
(392714,43635,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dolap artık dolu, demek ki bütün bulaşıkları oraya ...'::text,'koymuş olmalı'::text,'koymuş olabilir'::text,'koymuş olamaz'::text,'Dolap artık dolu, demek ki bütün bulaşıkları oraya koymuş olmalı.'::text),
(392715,43635,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szekrény most tele van, szóval ... oda pakolta az összes edényt.'::text,'biztosan'::text,'talán'::text,'nem lehet, hogy'::text,'A szekrény most tele van, szóval biztosan oda pakolta az összes edényt.'::text),
(392718,43636,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gläser, ... er aufs oberste Regal gestellt hat, haben alle verschiedene Farben.'::text,'die'::text,'wer'::text,'was'::text,'Die Gläser, die er aufs oberste Regal gestellt hat, haben alle verschiedene Farben.'::text),
(392722,43636,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Банки, ... він поставив на верхню полицю, всі різних кольорів.'::text,'які'::text,'хто'::text,'що'::text,'Банки, які він поставив на верхню полицю, всі різних кольорів.'::text),
(392721,43636,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los tarros ... guardó en el estante de arriba son todos de colores distintos.'::text,'que'::text,'quien'::text,'lo que'::text,'Los tarros que guardó en el estante de arriba son todos de colores distintos.'::text),
(392720,43636,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les bocaux ... a rangés sur l''étagère du haut sont tous de couleurs différentes.'::text,'qu''il'::text,'qui il'::text,'ce qu''il'::text,'Les bocaux qu''il a rangés sur l''étagère du haut sont tous de couleurs différentes.'::text),
(392723,43636,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En üst rafa ... kavanozların hepsi farklı renkte.'::text,'koyduğu'::text,'koyan'::text,'koyduğu şey'::text,'En üst rafa koyduğu kavanozların hepsi farklı renkte.'::text),
(392724,43636,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A befőttesüvegek, ... a legfelső polcra tett, mind különböző színűek.'::text,'amiket'::text,'akiket'::text,'amit'::text,'A befőttesüvegek, amiket a legfelső polcra tett, mind különböző színűek.'::text),
(392727,43637,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, du hast gesagt, du ... das ganze Geschirr bis zum Mittag wegräumen, und du hast es geschafft.'::text,'würdest'::text,'wirst'::text,'räumtest'::text,'Ehrlich gesagt, du hast gesagt, du würdest das ganze Geschirr bis zum Mittag wegräumen, und du hast es geschafft.'::text),
(392731,43637,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брехатиму, ти сказав, що ... весь посуд до обіду, і ти це зробив.'::text,'розкладеш'::text,'розкладеш'::text,'розклав'::text,'Не брехатиму, ти сказав, що розкладеш весь посуд до обіду, і ти це зробив.'::text),
(392730,43637,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, dijiste que ... todos los platos antes de comer, y lo hiciste.'::text,'guardarías'::text,'guardarás'::text,'guardaste'::text,'No voy a mentir, dijiste que guardarías todos los platos antes de comer, y lo hiciste.'::text),
(392729,43637,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu as dit que tu ... toute la vaisselle avant midi, et tu l''as fait.'::text,'rangerais'::text,'rangeras'::text,'as rangé'::text,'Je vais pas mentir, tu as dit que tu rangerais toute la vaisselle avant midi, et tu l''as fait.'::text),
(392732,43637,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, bütün bulaşıkları öğlene kadar ... söyledin ve yaptın.'::text,'yerleştireceğini'::text,'yerleştireceğini'::text,'yerleştirdiğini'::text,'Yalan yok, bütün bulaşıkları öğlene kadar yerleştireceğini söyledin ve yaptın.'::text),
(392733,43637,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, azt mondtad, hogy ebédig ... az összes edényt, és megcsináltad.'::text,'elpakolod'::text,'elpakolod'::text,'elpakoltad'::text,'Nem hazudok, azt mondtad, hogy ebédig elpakolod az összes edényt, és megcsináltad.'::text),
(330285,36699,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... sich gerade aus dem Fenster, als die Höhe plötzlich ernst wurde. Total entspannt.'::text,'lehnte'::text,'lehnte'::text,'hat'::text,'Er lehnte sich gerade aus dem Fenster, als die Höhe plötzlich ernst wurde. Total entspannt.'::text),
(330289,36699,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... з вікна, коли висота раптом стала серйозною. Абсолютно розслаблений.'::text,'висувався'::text,'висунувся'::text,'висунувся'::text,'Він висувався з вікна, коли висота раптом стала серйозною. Абсолютно розслаблений.'::text),
(330288,36699,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... por la ventana cuando la altitud de repente se puso seria. Totalmente relajado.'::text,'se estaba asomando'::text,'se asomó'::text,'se ha asomado'::text,'Él se estaba asomando por la ventana cuando la altitud de repente se puso seria. Totalmente relajado.'::text),
(330287,36699,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... par la fenêtre quand l''altitude est soudain devenue sérieuse. Totalement détendu.'::text,'se penchait'::text,'s''est penché'::text,'s''est penché'::text,'Il se penchait par la fenêtre quand l''altitude est soudain devenue sérieuse. Totalement détendu.'::text),
(330290,36699,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rakım aniden ciddileştiğinde camdan dışarı ...; tamamen rahat.'::text,'sarkıyordu'::text,'sarktı'::text,'sarktı'::text,'Rakım aniden ciddileştiğinde camdan dışarı sarkıyordu; tamamen rahat.'::text),
(330291,36699,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... az ablakon, amikor a magasság hirtelen komolyra fordult. Teljesen nyugodt.'::text,'hajolt ki'::text,'kihajolt'::text,'kihajolt'::text,'Épp hajolt ki az ablakon, amikor a magasság hirtelen komolyra fordult. Teljesen nyugodt.'::text),
(330294,36700,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... schon hundert Fotos von dieser furchterregenden Höhe gemacht!'::text,'hat'::text,'hat'::text,'macht'::text,'Er hat schon hundert Fotos von dieser furchterregenden Höhe gemacht!'::text),
(330298,36700,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він уже ... сто фото цієї жахливої висоти!'::text,'зробив'::text,'робив'::text,'робить'::text,'Він уже зробив сто фото цієї жахливої висоти!'::text),
(330297,36700,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él ya ... cien fotos de esta altitud aterradora!'::text,'ha hecho'::text,'ha estado haciendo'::text,'está haciendo'::text,'¡Él ya ha hecho cien fotos de esta altitud aterradora!'::text),
(330296,36700,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... déjà cent photos de cette altitude terrifiante !'::text,'a pris'::text,'a pris'::text,'prend'::text,'Il a pris déjà cent photos de cette altitude terrifiante !'::text),
(330299,36700,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu korkunç yüksekliğin şimdiden yüz fotoğrafını ...!'::text,'çekti'::text,'çekiyordu'::text,'çekiyor'::text,'Bu korkunç yüksekliğin şimdiden yüz fotoğrafını çekti!'::text),
(330300,36700,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már száz fotót ... erről a rémisztő magasságról!'::text,'készített'::text,'készítgetett'::text,'készít'::text,'Már száz fotót készített erről a rémisztő magasságról!'::text),
(330303,36701,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Kabine die Felswand erreichte, ... die Höhe seinen Mut völlig zerstört!'::text,'hatte'::text,'hat'::text,'zerstört'::text,'Als die Kabine die Felswand erreichte, hatte die Höhe seinen Mut völlig zerstört!'::text),
(330307,36701,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки кабіна дісталася скелі, висота ... його сміливість повністю!'::text,'знищила'::text,'знищила'::text,'знищує'::text,'Поки кабіна дісталася скелі, висота знищила його сміливість повністю!'::text),
(330306,36701,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para cuando la cabina llegó al acantilado, la altitud ... por completo su valor!'::text,'había destruido'::text,'ha destruido'::text,'destruye'::text,'¡Para cuando la cabina llegó al acantilado, la altitud había destruido por completo su valor!'::text),
(330305,36701,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand la cabine a atteint la falaise, l''altitude ... complètement son courage !'::text,'avait détruit'::text,'a détruit'::text,'détruit'::text,'Quand la cabine a atteint la falaise, l''altitude avait détruit complètement son courage !'::text),
(330308,36701,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kabin uçuruma ulaştığında rakım cesaretini tamamen ...!'::text,'yok etmişti'::text,'yok etti'::text,'yok ediyor'::text,'Kabin uçuruma ulaştığında rakım cesaretini tamamen yok etmişti!'::text),
(330309,36701,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a kabin a sziklafalhoz ért, a magasság teljesen ... a bátorságát!'::text,'elvette'::text,'elvette'::text,'elveszi'::text,'Mire a kabin a sziklafalhoz ért, a magasság teljesen elvette a bátorságát!'::text),
(330321,36703,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Kabine in geringerer Höhe ..., würde er das Tal nicht so tief unter sich sehen.'::text,'führe'::text,'fährt'::text,'fahren würde'::text,'Wenn die Kabine in geringerer Höhe führe, würde er das Tal nicht so tief unter sich sehen.'::text),
(330325,36703,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби кабіна ... на меншій висоті, він не бачив би долину так глибоко внизу.'::text,'їхала'::text,'їде'::text,'їхала б'::text,'Якби кабіна їхала на меншій висоті, він не бачив би долину так глибоко внизу.'::text),
(330324,36703,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la cabina ... a menor altitud, él no vería el valle tan abajo.'::text,'viajara'::text,'viaja'::text,'viajaría'::text,'Si la cabina viajara a menor altitud, él no vería el valle tan abajo.'::text),
(330323,36703,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la cabine ... à une altitude plus basse, il ne verrait pas la vallée si loin en contrebas.'::text,'circulait'::text,'circule'::text,'circulerait'::text,'Si la cabine circulait à une altitude plus basse, il ne verrait pas la vallée si loin en contrebas.'::text),
(330326,36703,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kabin daha alçak bir rakımda ..., vadiyi o kadar aşağıda görmezdi.'::text,'gitse'::text,'gidiyor'::text,'giderdi'::text,'Kabin daha alçak bir rakımda gitse, vadiyi o kadar aşağıda görmezdi.'::text),
(330327,36703,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a kabin alacsonyabb magasságban ..., nem látná a völgyet ilyen mélyen maga alatt.'::text,'haladna'::text,'halad'::text,'haladna'::text,'Ha a kabin alacsonyabb magasságban haladna, nem látná a völgyet ilyen mélyen maga alatt.'::text),
(330330,36704,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Höhe der Bergstation ... auf einem Schild am Bahnsteig angegeben.'::text,'wird'::text,'zeigt'::text,'zeigt'::text,'Die Höhe der Bergstation wird auf einem Schild am Bahnsteig angegeben.'::text),
(330334,36704,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Висота гірської станції ... на табличці на платформі.'::text,'вказана'::text,'показує'::text,'показує'::text,'Висота гірської станції вказана на табличці на платформі.'::text),
(330333,36704,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La altitud de la estación de montaña ... en un cartel del andén.'::text,'se indica'::text,'indica'::text,'está indicando'::text,'La altitud de la estación de montaña se indica en un cartel del andén.'::text),
(330332,36704,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''altitude de la station de montagne ... sur un panneau du quai.'::text,'est indiquée'::text,'indique'::text,'est en train d''indiquer'::text,'L''altitude de la station de montagne est indiquée sur un panneau du quai.'::text),
(330335,36704,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dağ istasyonunun rakımı perondaki bir tabelada ...'::text,'gösteriliyor'::text,'gösteriyor'::text,'gösteriyor'::text,'Dağ istasyonunun rakımı perondaki bir tabelada gösteriliyor.'::text),
(330336,36704,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hegyi állomás magassága ... egy táblán a peronon.'::text,'fel van tüntetve'::text,'mutat'::text,'mutatja'::text,'A hegyi állomás magassága fel van tüntetve egy táblán a peronon.'::text),
(330339,36705,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Seilbahn ... ihn in eine größere Höhe über den Bäumen.'::text,'brachte'::text,'wurde gebracht'::text,'bringend'::text,'Die Seilbahn brachte ihn in eine größere Höhe über den Bäumen.'::text),
(330343,36705,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Канатна дорога ... його на більшу висоту над деревами.'::text,'підняла'::text,'була піднята'::text,'піднімаючи'::text,'Канатна дорога підняла його на більшу висоту над деревами.'::text),
(330342,36705,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El teleférico lo ... a una altitud mayor por encima de los árboles.'::text,'llevó'::text,'fue llevado'::text,'llevando'::text,'El teleférico lo llevó a una altitud mayor por encima de los árboles.'::text),
(330341,36705,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le téléphérique ... à une altitude plus élevée au-dessus des arbres.'::text,'l''a emmené'::text,'a été emmené'::text,'l''emmenant'::text,'Le téléphérique l''a emmené à une altitude plus élevée au-dessus des arbres.'::text),
(330344,36705,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Teleferik onu ağaçların üstünde daha yüksek bir rakıma ...'::text,'taşıdı'::text,'taşındı'::text,'taşıyan'::text,'Teleferik onu ağaçların üstünde daha yüksek bir rakıma taşıdı.'::text),
(330345,36705,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kabinos felvonó ... őt magasabbra, a fák fölé.'::text,'vitte'::text,'lett vive'::text,'víve'::text,'A kabinos felvonó vitte őt magasabbra, a fák fölé.'::text),
(330348,36706,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ist nicht sicher, aber die Höhe ... über 2.000 Meter betragen.'::text,'könnte'::text,'muss'::text,'sollte'::text,'Er ist nicht sicher, aber die Höhe könnte über 2.000 Meter betragen.'::text),
(330352,36706,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він не впевнений, але висота ... перевищувати 2 000 метрів.'::text,'може'::text,'мусить'::text,'має'::text,'Він не впевнений, але висота може перевищувати 2 000 метрів.'::text),
(330351,36706,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No está seguro, pero la altitud ... superar los 2.000 metros.'::text,'podría'::text,'debe de'::text,'debería'::text,'No está seguro, pero la altitud podría superar los 2.000 metros.'::text),
(330350,36706,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il n''est pas sûr, mais l''altitude ... dépasser 2 000 mètres.'::text,'pourrait'::text,'doit'::text,'devrait'::text,'Il n''est pas sûr, mais l''altitude pourrait dépasser 2 000 mètres.'::text),
(330353,36706,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Emin değil, ama rakım 2.000 metrenin üzerinde ...'::text,'olabilir'::text,'olmalı'::text,'olması gerek'::text,'Emin değil, ama rakım 2.000 metrenin üzerinde olabilir.'::text),
(330354,36706,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem biztos benne, de a magasság ... meghaladja a 2000 métert.'::text,'talán'::text,'biztosan'::text,'elvileg'::text,'Nem biztos benne, de a magasság talán meghaladja a 2000 métert.'::text),
(330357,36707,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wie du in einer Höhe lächelst, ... den meisten Leuten Angst macht, ist beeindruckend.'::text,'die'::text,'wer'::text,'wo'::text,'Ehrlich, wie du in einer Höhe lächelst, die den meisten Leuten Angst macht, ist beeindruckend.'::text),
(330361,36707,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, те, як ти усміхаєшся на висоті, ... лякає більшість людей, вражає.'::text,'яка'::text,'хто'::text,'де'::text,'Чесно, те, як ти усміхаєшся на висоті, яка лякає більшість людей, вражає.'::text),
(330360,36707,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, cómo sonríes a una altitud ... asusta a la mayoría es impresionante.'::text,'que'::text,'quien'::text,'donde'::text,'La verdad, cómo sonríes a una altitud que asusta a la mayoría es impresionante.'::text),
(330359,36707,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, ta façon de sourire à une altitude ... fait peur à la plupart des gens est impressionnante.'::text,'qui'::text,'qui'::text,'où'::text,'Franchement, ta façon de sourire à une altitude qui fait peur à la plupart des gens est impressionnante.'::text),
(330362,36707,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, çoğu insanı ... bir yükseklikte gülümseme şeklin etkileyici.'::text,'korkutan'::text,'korkutan'::text,'korkutan'::text,'Açıkçası, çoğu insanı korkutan bir yükseklikte gülümseme şeklin etkileyici.'::text),
(330363,36707,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, lenyűgöző, ahogy olyan magasságban mosolyogsz, ... a legtöbb embert megrémíti.'::text,'amely'::text,'aki'::text,'ahol'::text,'Őszintén, lenyűgöző, ahogy olyan magasságban mosolyogsz, amely a legtöbb embert megrémíti.'::text),
(330366,36708,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte, die Höhe ... ihn nicht stören. Total ruhig, offensichtlich.'::text,'würde'::text,'werde'::text,NULL::text,'Er sagte, die Höhe würde ihn nicht stören. Total ruhig, offensichtlich.'::text),
(330370,36708,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що висота йому не ... заважати. Абсолютно спокійний, звісно.'::text,'буде'::text,'буде'::text,NULL::text,'Він сказав, що висота йому не буде заважати. Абсолютно спокійний, звісно.'::text),
(330369,36708,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que la altitud no le ... en absoluto. Totalmente tranquilo, obviamente.'::text,'molestaría'::text,'molestará'::text,NULL::text,'Dijo que la altitud no le molestaría en absoluto. Totalmente tranquilo, obviamente.'::text),
(330368,36708,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit que l''altitude ne le ... pas. Totalement calme, évidemment.'::text,'dérangerait'::text,'dérangera'::text,NULL::text,'Il a dit que l''altitude ne le dérangerait pas. Totalement calme, évidemment.'::text),
(330371,36708,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rakımın onu ... söyledi. Tamamen sakin, belli ki.'::text,'rahatsız etmeyeceğini'::text,'rahatsız etmeyeceğini'::text,NULL::text,'Rakımın onu rahatsız etmeyeceğini söyledi. Tamamen sakin, belli ki.'::text),
(330372,36708,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy a magasság nem ... zavarni. Teljesen nyugodt, nyilván.'::text,'fogja'::text,'fogja'::text,NULL::text,'Azt mondta, hogy a magasság nem fogja zavarni. Teljesen nyugodt, nyilván.'::text),
(330375,36709,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nichts Großes, nur ... von etwa 2.000 Metern über dem Tal.'::text,'eine Höhe'::text,'die Höhe'::text,'eine Höhe'::text,'Nichts Großes, nur eine Höhe von etwa 2.000 Metern über dem Tal.'::text),
(330379,36709,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Нічого особливого, лише ... близько 2 000 метрів над долиною.'::text,'висота'::text,'висота'::text,'висота'::text,'Нічого особливого, лише висота близько 2 000 метрів над долиною.'::text),
(330378,36709,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nada del otro mundo, solo ... de unos 2.000 metros sobre el valle.'::text,'una altitud'::text,'la altitud'::text,'una altitud'::text,'Nada del otro mundo, solo una altitud de unos 2.000 metros sobre el valle.'::text),
(330377,36709,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rien de grave, juste ... d''environ 2 000 mètres au-dessus de la vallée.'::text,'une altitude'::text,'l''altitude'::text,'une altitude'::text,'Rien de grave, juste une altitude d''environ 2 000 mètres au-dessus de la vallée.'::text),
(330380,36709,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Önemli bir şey yok, sadece vadinin yaklaşık 2.000 metre üzerinde ...'::text,'bir rakım'::text,'rakım'::text,'bir rakım'::text,'Önemli bir şey yok, sadece vadinin yaklaşık 2.000 metre üzerinde bir rakım.'::text),
(330381,36709,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Semmi komoly, csak ... nagyjából 2000 méterrel a völgy felett.'::text,'egy magasság'::text,'a magasság'::text,'egy magasság'::text,'Semmi komoly, csak egy magasság nagyjából 2000 méterrel a völgy felett.'::text)
